// Configuración → "Ritmos por categoría y modalidad": reglas admin-editables de qué subconjunto de
// DANCESETS[style] baila cada categoría (ej: "F" en Latin = solo Samba/Cha Cha Cha/Rumba; "BR" en
// Smooth = todo menos Peabody). Se cargan desde dance-rules-config.json (ver loadDanceRulesConfig,
// llamado en el boot del admin) — hasta que eso resuelva, o si nunca se guardó nada, esta misma
// variable ya trae sembrados los defaults que antes estaban hardcodeados en 2 lugares distintos
// (danceSetFor/INS_PRE y ritmosDe/PRE_DANCES, exports XLSX) para "F"/"NC"/"Newcomer", así no cambia
// nada para torneos existentes hasta que el admin agregue/edite reglas a mano.
let DANCE_RULES=[
  {style:'Standard',cat:'NC',dances:['Slow Waltz','European Tango','Quick Step']},
  {style:'Latin',cat:'NC',dances:['Samba','Cha Cha Cha','Rumba']},
  {style:'Smooth',cat:'NC',dances:['Waltz','American Tango','FoxTrot']},
  {style:'Rhythm',cat:'NC',dances:['Cha Cha','Rumba','East Coast Swing']}
];
const _normCat=c=>(c==null?'':String(c)).toUpperCase().replace(/[^A-Z0-9]/g,'');
// El campo "Categoría" de una regla admite varios códigos separados por coma (ej: "NC, HB") para
// cubrir 2+ categorías que bailan exactamente el mismo set sin duplicar la fila — se matchea por OR
// contra cada código normalizado individualmente. ANTES esto se comparaba como un solo string
// normalizado completo (_normCat(r.cat)===c), lo que colapsaba "NC, HB" a "NCHB" y nunca matcheaba
// ni "NC" ni "HB" por separado — la regla quedaba muerta sin avisar nada al admin (bug reportado
// 2026-06-25 PM: el admin armó reglas "NC, HB" para los 4 estilos esperando que cubrieran ambas
// categorías, y ninguna aplicaba).
const _catTokens=c=>(c==null?'':String(c)).split(',').map(_normCat).filter(Boolean);
// Ritmos que baila una categoría puntual dentro de una modalidad. Si hay una regla puntual para
// (style,cat) se usa esa. Si no, y la categoría es "F" o "Newcomer" (alias históricos de "NC"),
// se cae a la regla de "NC" si existe (compat con el comportamiento pre-configuración). Si nada de
// eso aplica, se devuelve el set completo de la modalidad — comportamiento original, sin reducir.
function dancesForCategory(style,cat){
  const c=_normCat(cat);
  // Alias: 'F' (Int'l Half-Bronze) ↔ 'HB'; 'NEWCOMER'/'NC' son equivalentes
  const aliases={'F':['F','HB','HALFBRONZE'],'HB':['HB','F','HALFBRONZE'],'HALFBRONZE':['HB','F','HALFBRONZE'],'NC':['NC','NEWCOMER'],'NEWCOMER':['NC','NEWCOMER']};
  const tokens=aliases[c]||[c];
  const direct=DANCE_RULES.find(r=>r.style===style&&tokens.some(t=>_catTokens(r.cat).includes(t)));
  if(direct&&direct.dances&&direct.dances.length)return direct.dances;
  if(c==='F'||c==='HB'||c==='HALFBRONZE'||c==='NEWCOMER'||c==='NC'){
    const ncTokens=['NC','NEWCOMER','F','HB','HALFBRONZE'];
    const ncRule=DANCE_RULES.find(r=>r.style===style&&ncTokens.some(t=>_catTokens(r.cat).includes(t)));
    if(ncRule&&ncRule.dances&&ncRule.dances.length)return ncRule.dances;
  }
  return DANCESETS[style]||[];
}
