function phaseList(n){if(n<=0)return[];if(n<=6)return['Final'];if(n===7)return['General Look','Final'];let c=n<=12?2:n<=24?3:n<=48?4:n<=96?5:6;if(c===2)return['Semifinal','Final'];const l=['¼ de Final','Semifinal','Final'],r=[];for(let i=1;i<=c-3;i++)r.push('Ronda '+i);return r.concat(l);}
// Resuelve "misma persona" por ID (lead/follId, normalmente basado en DNI) Y TAMBIÉN por nombre
// normalizado (mismo nameKey que usa idOf para el fallback sin DNI). Por qué: el DNI del follower
// suele ser opcional, así que la MISMA persona puede registrarse con dos parejas distintas y
// terminar con dos IDs distintos si una inscripción trae el DNI y la otra no — sin este refuerzo
// por nombre, esa persona podía terminar bailando en el mismo heat contra sí misma.
const identityKeysOf=c=>{const ks=[];if(c.leadId)ks.push(c.leadId);if(c.follId)ks.push(c.follId);const nl=c.lead?nameKey(c.lead):'',nf=c.foll?nameKey(c.foll):'';if(nl)ks.push('nm:'+nl);if(nf)ks.push('nm:'+nf);return ks;};
function makeHeats(es,m){const h=[];for(const e of es){const c=[...h].sort((a,b)=>a.length-b.length);let p=false;for(const x of c){if(x.length>=m)continue;const eb=identityKeysOf(e);const cl=x.some(y=>identityKeysOf(y).some(id=>eb.includes(id)));if(cl)continue;x.push(e);p=true;break;}if(!p)h.push([e]);}return h;}
const peopleOf=cs=>{const s=new Set();cs.forEach(c=>{identityKeysOf(c).forEach(k=>s.add(k));});return s;};
function spreadHeats(heats){
  const hash=s=>{let h=2166136261>>>0;s=String(s);for(let i=0;i<s.length;i++){h^=s.charCodeAt(i);h=Math.imul(h,16777619)>>>0;}return h/4294967296;};
  const rem=heats.map((h,idx)=>({h,people:peopleOf(h.couples),ord:hash((h.rl||'')+':'+idx)}));
  const out=[];let p1=new Set(),p2=new Set(),lastRl=null;
  while(rem.length){
    let bi=0,bs=Infinity;
    for(let i=0;i<rem.length;i++){let o=0;rem[i].people.forEach(p=>{if(p1.has(p))o+=100;if(p2.has(p))o+=20;});if(rem[i].h.rl===lastRl)o+=8;const sc=o+rem[i].ord;if(sc<bs){bs=sc;bi=i;}}
    const x=rem.splice(bi,1)[0];out.push(x.h);p2=p1;p1=x.people;lastRl=x.h.rl;
  }
  return out;
}
function packBuckets(buckets,maxX){
  const heats=[];
  buckets.forEach(b=>{
    let placed=false;
    for(const h of heats){
      if(h.couples.length+b.couples.length>maxX)continue;
      if([...b.people].some(p=>h.people.has(p)))continue;
      b.couples.forEach(c=>h.couples.push(c));b.people.forEach(p=>h.people.add(p));h.buckets.push(b.ev);placed=true;break;
    }
    if(!placed)heats.push({couples:[...b.couples],people:new Set(b.people),buckets:[b.ev]});
  });
  return heats;
}
