  let gateIntIdx = firstMatch('singles de standard',['singles','standard'],['singles','int-st'],'int-st',['singles dance','2'],['singles dance','1']); // col31 → rango pareja INT
  const gateSyRH   = idx('singles dance','3');    // col59 → rango synchro AM-RH
