        const row=Object.assign(mk(),idCols);row[B.style+' categoria']=cat;row['Grupo de edad']=age;row['Elegir modalidad']=B.style==='Rhythm'?'American Style':'International Style';row['Elija la especialidad']=mkEsp('Synchro Duo',lvl.cat,lvl.open);out.push(row);
