// Tilde/destilde de la grilla "¿Qué ve y qué puede hacer cada Usuario/PIN?" — role es 'view' o
// 'scrut' (Admin/Locutor/Juez no son editables: Admin ve siempre todo, Locutor/Juez tienen su
// propia pantalla y no usan este sistema de solapas). Actualiza VIEW_TABS/SCRUT_TABS en memoria,
// guarda en _localPins.tabPerms (localStorage) y publica para que otros dispositivos lo adopten.
async function saveTabPerm(role,tabId,checked){
  const arr=role==='view'?VIEW_TABS:SCRUT_TABS;
  const i=arr.indexOf(tabId);
  if(checked&&i===-1)arr.push(tabId);
  if(!checked&&i>-1)arr.splice(i,1);
  _localPins={..._localPins,tabPerms:{view:VIEW_TABS,scrut:SCRUT_TABS,edicionesPerms:EDICIONES_PERMS}};
  localStorage.setItem('rc_pins',JSON.stringify(_localPins));
  const si=document.getElementById('saveInfo');
  if(!si)return;
  if(!COMPS||!COMPS.length)return;
  si.style.display='block';si.style.background='#f5f5f5';si.style.borderColor='#ccc';si.style.color='#666';
  si.textContent='⏳ Publicando permisos...';
  const res=await pushPinsUpdate();
  if(res.ok){
    si.style.background='#eef6f0';si.style.borderColor='#b8d4bb';si.style.color='#3f6b4a';
    si.textContent='✓ Permisos guardados y publicados.';
  }else{
    si.style.background='#fdf0ee';si.style.borderColor='#e3b8b0';si.style.color='#a00';
    si.textContent='⚠ Guardado localmente, pero no se publicó: '+(res.msg||'error desconocido');
  }
  setTimeout(()=>si.style.display='none',5000);
}
