function showLockedView(){
  if(APP_MODE==='judge'){
    document.getElementById('app-layout').style.display='none';
    document.getElementById('locutor-view').style.display='none';
    const jv=document.getElementById('judge-view');
    jv.style.display='block';
    jv.innerHTML='<div style="padding:40px;text-align:center;color:var(--ink-soft);font-size:15px">🔒 La votación no está disponible en este momento. Consultá con el organizador.</div>';
    return;
  }
  ['panes','stats','comptitle'].forEach(id=>{const el=document.getElementById(id);if(el)el.innerHTML='';});
  document.getElementById('tabs').innerHTML='';
  document.getElementById('controls').classList.remove('show');
  document.getElementById('stats').classList.remove('show');
  document.getElementById('tabs').classList.remove('show');
  document.getElementById('panes').innerHTML='<div class="note" style="padding:32px;text-align:center;font-size:16px;color:var(--ink-soft)">🔒 La vista pública no está disponible en este momento.</div>';
}
function applyPublishedData(raw){
  try{
    let parsed=JSON.parse(raw);
    const isWrapper=parsed&&typeof parsed==='object'&&'enabled' in parsed;
    if(isWrapper){
      if(!parsed.enabled){showLockedView();return;}
      parsed=parsed.data;
    }
    loadProjectData(parsed);
  }catch(e){
    const si=document.getElementById('saveInfo');
    si.style.display='block';si.textContent='⚠ No se pudo cargar la vista publicada.';
    setTimeout(()=>si.style.display='none',4000);
  }
}
async function loadPublished(){
  // Si se está navegando una edición archivada (solo lectura), el polling normal no debe pisarla
  // con los datos en vivo de la competencia activa.
  if(MODO_HISTORICO)return;
  // Todos los dispositivos (juez/viewer/locutor) leen directo de Supabase con la misma anon key
  // embebida en este index.html — ya no hace falta credenciales por dispositivo ni archivo estático.
  try{
    // Reglas de "Ritmos por categoría y modalidad" (Configuración, admin-editable): hay que tenerlas
    // resueltas ANTES de applyPublishedData→loadProjectData→buildModel, porque buildModel decide qué
    // ritmos baila cada heat llamando a dancesForCategory()/DANCE_RULES. Antes solo el boot del admin
    // llamaba a loadDanceRulesConfig(), así que cualquier dispositivo no-admin (juez/escrutinador/
    // locutor/viewer) reconstruía el modelo con los defaults sembrados (solo regla "NC") y mostraba
    // heats con MÁS ritmos de los configurados (ej: el juez veía Peabody en un heat "Open Smooth"
    // donde el admin lo había destildado, aunque el panel del admin ya lo mostraba bien) — bug
    // reportado 2026-06-25. Cargarlo acá (se ejecuta en cada loadPublished: boot, polling de 60s en
    // "view", refresh manual del juez) lo mantiene siempre en sync con lo que ve el admin.
    await loadDanceRulesConfig();
    await Promise.all([loadSemifinalConfig(),loadSemifinalFinalists()]);
    // Si es un juez, primero traemos SUS votos desde Supabase y pisamos la copia local con eso.
    // Antes los votos del juez se leían solo de localStorage (rc_judge_votes_N), que queda pegado
    // al dispositivo: si ese dispositivo se usó antes (otra competencia, u otra sesión de prueba),
    // mostraba esos votos viejos aunque la competencia activa en Supabase fuera otra. Ahora Supabase
    // es siempre la fuente de verdad también para los votos, no solo para los datos del evento.
    if(APP_MODE==='judge'){await pullJudgeVotesFromSupabase();await pullJudgeMultiVotesFromSupabase();}
    const raw=await dbGetFile('published-data.json');
    if(!raw){showLockedView();return;}
    applyPublishedData(raw);
    // Overlay the controls from admin-backup (always up-to-date) so config
    // changes made by the admin without publishing are reflected everywhere.
    try{const ab=await dbGetFile('admin-backup.json');if(ab){const abd=JSON.parse(ab);if(abd&&abd.controls)setControls(abd.controls);}}catch(_){}
  }catch(e){showLockedView();}
}
