let TABS=[{id:'dorsales',label:'Dorsales'},{id:'cron',label:'Cronograma'},{id:'tandas',label:'Singles Dances'},{id:'comp',label:'Competencias'},{id:'inscripciones',label:'Inscripciones'},{id:'pagos',label:'💰 Pagos'},{id:'orden',label:'Orden General'},{id:'cp',label:'Planillas CP'},{id:'jreport',label:'🏆 Resultados Singles'},{id:'mdreport',label:'🏅 Resultados Multidance'},{id:'config',label:'⚙ Configuración'}];
// Grilla "¿Qué ve y qué puede hacer cada Usuario/PIN?" en Configuración › Permisos. Las columnas
// Vista pública y Escrutinador son TILDES editables (ver saveTabPerm) que controlan VIEW_TABS/
// SCRUT_TABS — las mismas listas que ya filtran las solapas reales, así que tildar/destildar acá
// tiene efecto inmediato en qué solapas puede abrir cada rol. Admin no es editable (ve siempre
// todo). Locutor y Juez no usan el sistema de solapas (tienen su propia pantalla dedicada), así
// que se muestran como dos filas aparte en vez de columnas, también fijas.
function renderPermisosMatrix(){
  const el=document.getElementById('permisosMatrix');
  if(!el)return;
  const roles=[
    {key:'admin',label:'Admin',desc:'Ve y edita todo: todas las solapas, Configuración, Inscripciones y Pagos. No es editable.',editable:false},
    {key:'view',label:'Vista pública',desc:'Solo lectura, sin botones de editar. Tildá qué solapas puede ver.',editable:true},
    {key:'scrut',label:'Escrutinador',desc:'Ve sus solapas; puede mover y/o fusionar heats solo si está habilitado arriba — si no, son de solo lectura para él también. Tildá qué solapas puede ver.',editable:true},
    {key:'locutor',label:'Locutor',desc:'No usa estas solapas: tiene su propia pantalla (checklist de heats + 🏆 Resultados premios). No es editable.',editable:false},
    {key:'judge',label:'Juez',desc:'No usa estas solapas: tiene su propia pantalla (vota Single Dances/Multidance solo en lo que se le asignó). No ve resultados ni premios. No es editable.',editable:false},
  ];
  const sees=(roleKey,tabId)=>{
    if(roleKey==='admin')return true;
    if(roleKey==='view')return VIEW_TABS.includes(tabId);
    if(roleKey==='scrut')return SCRUT_TABS.includes(tabId);
    return false;
  };
  const cell=(r,tabId)=>{
    if(r.editable)return `<td style="text-align:center"><input type="checkbox" ${sees(r.key,tabId)?'checked':''} onchange="saveTabPerm('${r.key}','${tabId}',this.checked)" style="width:16px;height:16px;cursor:pointer;vertical-align:middle"></td>`;
    return `<td style="text-align:center;font-weight:700">${sees(r.key,tabId)?'✓':'<span style="color:var(--ink-soft);font-weight:400">—</span>'}</td>`;
  };
  let html=`<table class="t" style="font-size:12.5px"><thead><tr><th style="text-align:left">Solapa</th>`+
    roles.map(r=>`<th style="text-align:center">${r.label}</th>`).join('')+`</tr></thead><tbody>`;
  TABS.forEach(t=>{
    html+=`<tr><td>${t.label}</td>`+roles.map(r=>cell(r,t.id)).join('')+`</tr>`;
  });
  const edCell=r=>{
    if(r.key==='admin')return `<td style="text-align:center;font-weight:700">✓</td>`;
    if(r.key==='view'||r.key==='scrut')return `<td style="text-align:center"><input type="checkbox" ${EDICIONES_PERMS[r.key]?'checked':''} onchange="saveEdicionesPerm('${r.key}',this.checked)" style="width:16px;height:16px;cursor:pointer;vertical-align:middle"></td>`;
    return `<td style="text-align:center;font-weight:400"><span style="color:var(--ink-soft)">—</span></td>`;
  };
  html+=`<tr><td>📚 Ediciones anteriores</td>`+roles.map(r=>edCell(r)).join('')+`</tr>`;
  html+=`<tr><td>🎤 Modo Locutor</td>`+roles.map(r=>`<td style="text-align:center;font-weight:700">${r.key==='locutor'?'✓':'<span style="color:var(--ink-soft);font-weight:400">—</span>'}</td>`).join('')+`</tr>`;
  html+=`<tr><td>⚖ Modo Juez</td>`+roles.map(r=>`<td style="text-align:center;font-weight:700">${r.key==='judge'?'✓':'<span style="color:var(--ink-soft);font-weight:400">—</span>'}</td>`).join('')+`</tr>`;
  html+=`</tbody></table>`;
  html+=`<div style="font-size:11px;color:var(--ink-soft);line-height:1.5">`+roles.map(r=>`<div style="margin-top:3px"><b style="color:var(--ink)">${r.label}:</b> ${r.desc}</div>`).join('')+
    `<div style="margin-top:6px">* En ediciones históricas archivadas, Vista pública también puede ver 🏆 Resultados Singles y 🏅 Resultados Multidance (quedan congelados, ya no cambian).</div></div>`;
  el.innerHTML=html;
}
