function judgeNames(){const n=Math.max(1,parseInt(document.getElementById('nJudges').value)||5);const raw=(document.getElementById('judges').value||'').split(',').map(x=>x.trim()).filter(Boolean);const out=[];for(let i=0;i<n;i++)out.push(raw[i]||'');return out;}
// gkey = identificador estable del grupo de comparación real (heat + bucket dentro de ese heat).
// Un heat "compartido" (pista compartida entre 2+ categorías/edades) puede tener varios buckets —
// cada bucket es su propio grupo de comparación y NO debe mezclarse con los demás del mismo heat
// PARA SKATING (ver collectContrapuestos: eso no cambia, 2+ parejas de un mismo bucket siguen
// comparándose solo entre sí). Pero si 2+ buckets de ESE heat compartido tienen, cada uno, una sola
// pareja ("contra el puesto"), se agrupan bajo UNA sola gkey ('<heat>:solo') para que el juez y los
// reportes los vean como una sola pantalla/heat (pedido explícito: heats fusionados manualmente con
// una pareja sola por categoría deben verse juntos) — cada pareja sigue puntuándose independiente
// (1-20), no se comparan entre sí entre categorías distintas. Si el heat compartido tiene un único
// bucket-solo, se mantiene exactamente como antes (gkey por bucket, sin tocar votos ya existentes).
function collectCP(SCH){
  // Heats/parejas anulados quedan AFUERA de las planillas y de las unidades de voto de jueces
  // (no se juzgan, no cuentan para resultados). El conteo de "soloBuckets"/"merge" se calcula
  // ya descontando las parejas anuladas, para que si una de 2 parejas fusionadas en :solo se
  // anula, la sobreviviente vuelva a su gkey individual (mismo principio de auto-corrección
  // que el booleano `skating` en buildMultidanceVoteUnits, ver collectContrapuestos).
  const out=[];
  SCH.blocks.forEach(B=>B.comps.forEach(e=>{
    const hKey=compVoidKey(e);
    if(isHeatVoided(hKey))return;
    if(e.kind==='TEAM'){
      // Equipos (Showdance/Formation): cada equipo es su propio heat/gkey (1 sola "pareja"
      // sintética, sin leadId real) — se le asigna leadId=e.eventKey (string único y estable)
      // para que la votación por componentes se pueda guardar/leer igual que cualquier otra pareja.
      if(!isCoupleVoided(hKey,e.couples[0]))out.push({heat:e.heat,gkey:e.heat+':e',style:e.style,cat:e.cat,age:e.age,couple:{...e.couples[0],leadId:e.eventKey},dances:e.dances,isTeam:true,tipo:e.tipo,team:e.team,kind:e.kind});
    }
    else if(e.shared){
      const soloBuckets=e.buckets.filter(b=>b.couples.length===1&&!isCoupleVoided(hKey,b.couples[0]));
      const merge=soloBuckets.length>1;
      const mergedLabel=merge?soloBuckets.map(b=>[(b.kind==='OPEN'?'Open':b.cat),ageRegLabel(b.age)].filter(Boolean).join(' · ')).join(' / '):null;
      soloBuckets.forEach(b=>{
        const realBi=e.buckets.indexOf(b);
        out.push({heat:e.heat,gkey:merge?(e.heat+':solo'):(e.heat+':b'+realBi),style:b.style,cat:(b.kind==='OPEN'?'Open':b.cat),age:b.age,couple:b.couples[0],dances:b.dances,soloGroup:merge,mergedLabel,kind:b.kind,name:b.name,synchro:!!e.synchro});
      });
    }
    else if(e.couples.length===1&&!isCoupleVoided(hKey,e.couples[0]))out.push({heat:e.heat,gkey:e.heat+':e',style:e.style,cat:(e.kind==='OPEN'?'Open':(e.cat||'')),age:e.age,couple:e.couples[0],dances:e.dances,kind:e.kind,name:e.name,synchro:!!e.synchro,isSemiF:e.isSemiF||false,baseKey:e.baseKey||null,roundName:e.roundName||null,advanceCount:e.advanceCount||0});
  }));
  return out;
}
function collectContrapuestos(SCH){
  // Misma exclusión que collectCP. b.couples.length>=2/e.couples.length>=2 se evalúa sobre el
  // total ORIGINAL (estructural: define si el bucket es "Contrapuestos" por inscripción), pero
  // las parejas anuladas se quitan recién al volcar al array de salida — así, si un grupo de 2
  // se queda en 1 pareja real, buildMultidanceVoteUnits la detecta como "Contra el puesto"
  // (couples.length<2) en vez de Skating, sin necesidad de lógica extra.
  const out=[];
  SCH.blocks.forEach(B=>B.comps.forEach(e=>{
    const hKey=compVoidKey(e);
    if(isHeatVoided(hKey))return;
    if(e.shared){e.buckets.forEach((b,bi)=>{if(b.couples.length>=2)b.couples.filter(c=>!isCoupleVoided(hKey,c)).forEach(c=>out.push({heat:e.heat,gkey:e.heat+':b'+bi,style:b.style,cat:(b.kind==='OPEN'?'Open':b.cat),age:b.age,couple:c,dances:b.dances,kind:b.kind,name:b.name,synchro:!!e.synchro,isSemiF:e.isSemiF||false,baseKey:e.baseKey||null,roundName:e.roundName||null,advanceCount:e.advanceCount||0}));});}
    else if(e.couples.length>=2)e.couples.filter(c=>!isCoupleVoided(hKey,c)).forEach(c=>out.push({heat:e.heat,gkey:e.heat+':e',style:e.style,cat:(e.kind==='OPEN'?'Open':(e.cat||'')),age:e.age,couple:c,dances:e.dances,kind:e.kind,name:e.name,synchro:!!e.synchro,isSemiF:e.isSemiF||false,baseKey:e.baseKey||null,roundName:e.roundName||null,advanceCount:e.advanceCount||0,_isFinal:e._isFinal||false}));
  }));
  return out;
}
const dnClean=r=>r.replace(/^\([^)]*\) /,'').replace(/^\[|\]$/g,'');
// Challenge no tiene categoría propia (cat queda en '—'), así que sin esto un heat de Challenge se
// veía idéntico a un Multidance sin categoría/edad — ninguna de las dos vistas (resumida ni detalle/
// PDF) decía "Challenge" en ningún lado. Reusa las mismas clases .badge.b-ch que ya usa el Cronograma.
const mdChallengeBadge=kind=>kind==='CHALLENGE'?' <span class="badge b-ch">Challenge</span>':'';
// Si la unidad tiene un solo baile (típico de Challenge: 1 ritmo = 1 heat), lo mostramos directo en el
// título del heat — antes solo se veía bajando a la sección de detalle por baile.
const mdRitmoSuffix=u=>(u.dances&&u.dances.length===1&&u.dances[0])?(' · '+(dnClean(u.dances[0])||u.dances[0])):'';
const surnames=c=>{const sn=s=>{const w=(s||'').trim().split(/\s+/);return (w[w.length-1]||'').toUpperCase();};return c.foll?sn(c.lead)+'-'+sn(c.foll):sn(c.lead);};
function paneCP(SCH,q){
  const p=pane('cp');
  const cp=collectCP(SCH).filter(x=>!q||key((x.couple.lead||'')+' '+(x.couple.foll||'')+' '+x.cat+' '+x.age+' '+String(dorsalOf(x.couple))).includes(q));
  const J=judgeNames();
  if(!cp.length){p.innerHTML=`<div class="sech">Planillas · Contra el puesto<span class="tag">0</span></div><div class="rule"></div><div class="note">No hay competencias "contra el puesto" (parejas/solos solos en su categoría) en esta competencia.</div>`;return p;}
  p.innerHTML=`<div class="sech">Planillas · Contra el puesto<span class="tag">${cp.length}</span></div><div class="rule"></div>`+
    `<div class="note">Una planilla por cada pareja/solo que compite contra el puesto. Ajustá la cantidad y nombres de jueces en los controles de arriba. Imprimí esta solapa para PDF, o usá "Exportar a Excel".</div>`+
    cp.map((x,i)=>{
      const dz=(x.dances||[]).map(dnClean);
      return `<div class="cpsheet"><div class="cph"><div class="cpt"><b>HEAT ${x.heat}</b> · ${x.style.toUpperCase()}</div><div class="cpn">CP ${i+1}</div></div>`+
      `<div class="cpsub"><b>${x.cat} ${ageRegLabel(x.age)}</b> · Dorsal <span class="dor">${dorsalOf(x.couple)}</span> · <span class="lead">${x.couple.lead}</span>${x.couple.foll?` <span class="foll">-</span> <span class="lead">${x.couple.foll}</span>`:''} · <span class="cp">Contra el puesto</span></div>`+
      `<table class="cptab"><thead><tr><th>Ritmo</th>${J.map((n,k)=>`<th>${n||('Juez '+(k+1))}</th>`).join('')}<th>Pos.</th></tr></thead><tbody>`+
      dz.map((d,di)=>`<tr><td class="rl">${di+1}- ${d}</td>${J.map(()=>`<td></td>`).join('')}<td></td></tr>`).join('')+
      `</tbody></table></div>`;
    }).join('');
  return p;
}
const coupleTxt=c=>{if(c._jjFollDorsal!=null&&c._jjFollDorsal!=='')return '<span class="lead">'+c.lead+'</span> <span class="foll">- <b>'+c._jjFollDorsal+'</b> '+c.foll+'</span>';return '<span class="lead">'+c.lead+'</span>'+(c.foll?' <span class="foll">-</span> <span class="lead">'+c.foll+'</span>':' <span class="foll">-</span>');}
// dorsalOf funciona en modo individual (MODEL) y en modo all (busca en todos los modelos)
const dorsalOf=c=>{if(c._jjLeadDorsal!=null&&c._jjLeadDorsal!=='')return c._jjLeadDorsal;if(MODEL&&MODEL.dorsalOf)return MODEL.dorsalOf(c);for(const comp of COMPS){const v=comp.model.dorsalOf(c);if(v!=='')return v;}return'';};
const matchC=(c,q)=>!q||key(c.lead+' '+(c.foll||'')+' '+(c.esc||'')+' '+(c.age||'')+' '+String(dorsalOf(c))).includes(q);

function toggleBreak(key){
  if(HIDDEN_BREAKS.has(key))HIDDEN_BREAKS.delete(key);else HIDDEN_BREAKS.add(key);
  localStorage.setItem('rc_hidden_breaks',JSON.stringify([...HIDDEN_BREAKS]));
  render();
}
function applyExclusions(m){
  if(!EXCLUDED_LEADS.size)return;
  m.events.forEach(e=>{e.couples=e.couples.filter(c=>!EXCLUDED_LEADS.has(c.leadId));});
  m.events=m.events.filter(e=>e.couples.length>0);
  m.order=m.order.filter(id=>!EXCLUDED_LEADS.has(id));
}
function rebuildAllModels(){
  COMPS.forEach(c=>{
    try{c.model=buildModel(c.rows,c.ageMode==='AABD'?ageNormAABD:ageNorm);applyExclusions(c.model);}catch{}
  });
  if(CUR!=='all'&&COMPS[CUR])MODEL=COMPS[CUR].model;
  const dStart=parseInt(document.getElementById('dStart').value)||1;
  const sStart=parseInt(document.getElementById('sStart').value)||0;
  rebuildDorsals(dStart,sStart);applyDorsalOverrides();
  _jreportCache=null;_mdreportCache=null;_mdVoteFilesCache=null; // los heats pueden haber cambiado: refrescar "Resultados Singles"
  render();
}
function excludeLead(leadId){
  // find display name for confirmation
  let name=leadId;
  COMPS.forEach(c=>{const p=c.model?.persons?.[leadId];if(p)name=p.name;});
  if(!confirm(`¿Eliminar a "${name}" de la competencia?\n\nSus heats y dorsal no se generarán. Podés restaurarla desde la pestaña Dorsales.`))return;
  EXCLUDED_LEADS.add(leadId);
  localStorage.setItem('rc_excluded_leads',JSON.stringify([...EXCLUDED_LEADS]));
  rebuildAllModels();
}
function restoreLead(leadId){
  EXCLUDED_LEADS.delete(leadId);
  localStorage.setItem('rc_excluded_leads',JSON.stringify([...EXCLUDED_LEADS]));
  rebuildAllModels();
}
function paneDorsales(q){
  const p=pane('dorsales');
  const models=CUR==='all'?COMPS.map(c=>c.model):(MODEL?[MODEL]:[]);
  // acumular todos los followers por leadId de TODOS los modelos
  const folls={};
  models.forEach(M=>{
    // usar events para capturar todas las combinaciones lead+foll reales
    M.events.forEach(e=>e.couples.forEach(c=>{
      if(!c.leadId)return;
      const fn=c.foll||'';
      if(!folls[c.leadId])folls[c.leadId]=[];
      if(!folls[c.leadId].some(x=>key(x.name)===key(fn)))folls[c.leadId].push({name:fn,dni:(c.follId&&M.persons[c.follId])?M.persons[c.follId].dni:''});
    }));
  });
  // armar filas: una fila por (leader, follower), sin duplicar personas ya vistas
  const seen=new Set(), rows=[];
  models.forEach(M=>{
    M.order.forEach(id=>{
      const pe=M.persons[id];
      if(pe.dorsal===''||seen.has(id)||EXCLUDED_LEADS.has(id))return;
      seen.add(id);
      const fl=(folls[id]||[]).filter(f=>f.name); // solo followers con nombre
      if(!fl.length){rows.push({d:pe.dorsal,lead:pe.name,leadDni:pe.dni,foll:'',follDni:'',lid:id});}
      else{
        // Si también baila en solitario (isSolo), agregar fila extra sin follower (ej: Sabrina que baila Solo Y Synchro Dúo)
        if(pe.isSolo)rows.push({d:pe.dorsal,lead:pe.name,leadDni:pe.dni,foll:'',follDni:'',lid:id});
        fl.forEach(f=>rows.push({d:pe.dorsal,lead:pe.name,leadDni:pe.dni,foll:f.name,follDni:f.dni,lid:id}));
      }
    });
  });
  const fil=rows.filter(r=>!q||key(r.lead).includes(q)||key(r.foll).includes(q)||String(r.d).includes(q)||key(r.leadDni||'').includes(q)||key(r.follDni||'').includes(q)).sort((a,b)=>(a.d-b.d)||(key(a.lead)<key(b.lead)?-1:1));
  const nd=new Set(fil.map(r=>r.d)).size;
  let html=`<div class="sech">Dorsales<span class="tag">${nd}</span></div><div class="rule"></div>`;
  html+=`<div class="note">El dorsal identifica al leader (o solo). Si un leader baila con varios followers, se repite el dorsal y el leader en cada fila.</div>`;
  const showDel=APP_MODE==='admin';
  const canEditDorsal=APP_MODE==='admin'||APP_MODE==='escrutinador';
  if(canEditDorsal)html+=`<div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-bottom:10px"><button type="button" class="act" id="dorsalTabReset" style="font-size:12px">↺ Restablecer automáticos</button><span id="dorsalTabStatus" style="font-size:11px;color:var(--ink-soft)"></span></div>`;
  if(showDel)html+=`<div style="display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin-bottom:12px;padding:10px 12px;background:var(--card);border:1px solid var(--line);border-radius:10px">
    <button type="button" class="act" onclick="printAllDorsals()" style="font-size:12px">🖨 Imprimir todos los dorsales</button>
    <span style="font-size:11px;color:var(--ink-soft);margin-left:2px">Opciones:</span>
    <label style="font-size:12px;cursor:pointer"><input type="checkbox" id="dpShowCompName" checked style="vertical-align:-2px;margin-right:4px"> Nombre evento</label>
    <label style="font-size:12px;cursor:pointer"><input type="checkbox" id="dpShowLogo" style="vertical-align:-2px;margin-right:4px"> Logo</label>
    <label style="font-size:12px;cursor:pointer;display:flex;align-items:center;gap:4px">Tamaño logos<input type="number" id="dpLogoSize" value="100" min="30" max="250" step="5" style="width:52px;text-align:center;padding:1px 4px;font-size:12px">%</label>
    <label style="font-size:12px;cursor:pointer;display:flex;align-items:center;gap:4px">Espacio<input type="number" id="dpLogoGap" value="10" min="0" max="80" step="2" style="width:44px;text-align:center;padding:1px 4px;font-size:12px">pt</label>
  </div>`;
  html+=`<table class="t"><thead><tr>${showDel?'<th style="width:56px"></th>':''}<th style="width:70px">Dorsal</th><th>Leader</th>${showDel?'<th style="width:110px">DNI Leader</th>':''}<th>Follower</th>${showDel?'<th style="width:110px">DNI Follower</th>':''}</tr></thead><tbody>`;
  let prevLead='';
  fil.forEach(r=>{
    const isFirst=r.lead!==prevLead;prevLead=r.lead;
    html+=`<tr>`;
    if(showDel){
      if(isFirst)html+=`<td style="text-align:center;white-space:nowrap"><button onclick="excludeLead('${r.lid}')" title="Eliminar de la competencia" style="background:none;border:none;cursor:pointer;color:#c0392b;font-size:14px;padding:2px 4px;border-radius:4px;line-height:1">✕</button><button onclick="printDorsal(${r.d},'${r.lead.replace(/'/g,"&#39;")}')" title="Imprimir dorsal" style="background:none;border:none;cursor:pointer;color:var(--ink-soft);font-size:13px;padding:2px 4px;border-radius:4px;line-height:1">🖨</button></td>`;
      else html+=`<td></td>`;
    }
    html+=(canEditDorsal&&isFirst)?`<td><input type="number" class="dor" data-dorsal-lid="${r.lid}" value="${r.d}" min="1" style="width:58px;text-align:center;border:1px solid var(--line);border-radius:4px;font-size:13px;font-weight:700;padding:2px 4px;background:var(--bg);color:var(--ink)"></td>`:`<td><span class="dor">${r.d}</span></td>`;
    html+=`<td class="lead">${r.lead}</td>`;
    if(showDel)html+=`<td style="font-size:12px;color:var(--ink-soft)">${isFirst?(r.leadDni||''):''}</td>`;
    html+=`<td>${r.foll?`<span class="lead">${r.foll}</span>`:'<span class="foll">— (solo)</span>'}</td>`;
    if(showDel)html+=`<td style="font-size:12px;color:var(--ink-soft)">${r.foll?(r.follDni||''):''}</td>`;
    html+=`</tr>`;
  });
  html+=`</tbody></table>`;
  // Jack & Jill: dorsales individuales guardados en _JJ_ROUNDS
  if(_JJ_ROUNDS&&_JJ_ROUNDS.groups&&_JJ_ROUNDS.groups.length){
    const jjRows=[];
    _JJ_ROUNDS.groups.forEach(group=>{
      const names=group.participantNames||{};
      const dorsals=group.dorsals||{};
      Object.entries(dorsals).forEach(([k,d])=>{
        const nombre=names[k]||k;
        if(q&&!key(nombre).includes(q)&&!String(d).includes(q))return;
        jjRows.push({d,nombre,nivel:group.level});
      });
    });
    if(jjRows.length){
      jjRows.sort((a,b)=>a.d-b.d);
      html+=`<div class="sech" style="margin-top:20px">Jack & Jill<span class="tag">${jjRows.length}</span></div><div class="rule"></div>`;
      html+=`<table class="t"><thead><tr><th style="width:70px">Dorsal</th><th>Participante</th><th>Nivel</th></tr></thead><tbody>`;
      jjRows.forEach(r=>{
        html+=`<tr><td><span class="dor">${r.d}</span></td><td class="lead">${r.nombre}</td><td>${r.nivel}</td></tr>`;
      });
      html+=`</tbody></table>`;
    }
  }
  // Equipos coreográficos (Showdance/Formation): tienen su propio dorsal, se listan aparte
  const teamRows=[];
  models.forEach(M=>{(M.teams||[]).forEach(t=>{if(!q||key(t.name+' '+(t.esc||'')+' '+(t.tipo||'')).includes(q)||String(t.dorsal||'').includes(q))teamRows.push(t);});});
  if(teamRows.length){
    teamRows.sort((a,b)=>(a.dorsal||0)-(b.dorsal||0));
    html+=`<div class="sech" style="margin-top:20px">Equipos coreográficos<span class="tag">${teamRows.length}</span></div><div class="rule"></div>`;
    html+=`<table class="t"><thead><tr><th style="width:70px">Dorsal</th><th>Equipo</th><th>Tipo</th><th>Escuela</th><th>Edad</th></tr></thead><tbody>`;
    teamRows.forEach(t=>{
      html+=`<tr><td><span class="dor">${t.dorsal||''}</span></td><td class="lead">${t.name}</td><td>${t.tipo||''}</td><td>${t.esc||''}</td><td>${ageRegLabel(t.age)||''}</td></tr>`;
    });
    html+=`</tbody></table>`;
  }
  // Show excluded section if any
  if(EXCLUDED_LEADS.size>0){
    html+=`<div class="sech" style="margin-top:20px">Excluidos<span class="tag" style="background:#c0392b;color:#fff">${EXCLUDED_LEADS.size}</span></div><div class="rule"></div>`;
    html+=`<div class="note" style="color:#c0392b">Estas personas fueron eliminadas de la competencia. Sus heats y dorsales no se generan.</div>`;
    html+=`<table class="t"><thead><tr><th style="width:32px"></th><th>Leader / Solo</th></tr></thead><tbody>`;
    EXCLUDED_LEADS.forEach(id=>{
      // Try to find their name from COMPS
      let name=id;
      COMPS.forEach(c=>{const p=c.model?.persons?.[id];if(p)name=p.name;});
      html+=`<tr><td style="text-align:center"><button onclick="restoreLead('${id}')" title="Restaurar" style="background:none;border:none;cursor:pointer;color:#2e7d4f;font-size:14px;padding:2px 4px;border-radius:4px;line-height:1">↩</button></td><td class="lead">${name}</td></tr>`;
    });
    html+=`</tbody></table>`;
  }
  p.innerHTML=html;
  if(canEditDorsal){
    p.querySelectorAll('input[data-dorsal-lid]').forEach(inp=>{
      inp.addEventListener('change',async()=>{
        const lid=inp.dataset.dorsalLid,val=parseInt(inp.value);
        if(isNaN(val)||val<1)return;
        const st=p.querySelector('#dorsalTabStatus');
        if(st)st.textContent='⏳ Guardando...';
        DORSAL_OVERRIDES[lid]=val;applyDorsalOverrides();
        const res=await dbUpload(JSON.stringify(DORSAL_OVERRIDES),true,'dorsal-overrides.json');
        if(st)st.textContent=res.ok?'✓ Guardado.':'⚠ Error: '+res.msg;
        render();
      });
    });
    p.querySelector('#dorsalTabReset')?.addEventListener('click',async()=>{
      DORSAL_OVERRIDES={};
      const st=p.querySelector('#dorsalTabStatus');
      if(st)st.textContent='⏳ Restableciendo...';
      const dS=parseInt(document.getElementById('dStart').value)||1,sS=parseInt(document.getElementById('sStart').value)||0;
      rebuildDorsals(dS,sS);
      const res=await dbUpload(JSON.stringify({}),true,'dorsal-overrides.json');
      if(st)st.textContent=res.ok?'✓ Automáticos restablecidos.':'⚠ Error: '+res.msg;
      render();
    });
  }
  return p;
}

// ==================== Impresión de dorsales ====================
async function _getDorsalPrintMeta(){
  let logoUrl=null;
  try{const raw=await dbGetFile('reg-logo.json');const lg=raw?JSON.parse(raw):null;if(lg&&lg.img)logoUrl=lg.img;}catch(e){}
  const compName=COMP_DISPLAY_NAME||(COMPS[0]&&COMPS[0].title)||'';
  try{const raw=await dbGetFile('dorsal-extra-logos.json');const cfg=raw?JSON.parse(raw):null;if(cfg){DORSAL_EXTRA_LOGOS.logo1=cfg.logo1||null;DORSAL_EXTRA_LOGOS.logo2=cfg.logo2||null;}}catch(e){}
  return{logoUrl,compName};
}
const RC_LOGO_B64='';
function _buildDorsalPrintHtml(dorsalRows,{logoUrl,compName,showCompName,showLogo,logoSize,logoGap}){
  const escH=s=>s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
  const rcImg=`<img src="data:image/png;base64,${RC_LOGO_B64}" class="dc-rc-logo" alt="RC">`;
  const buildCard=r=>`<div class="dc">
    ${showCompName&&compName?`<div class="dc-comp">${escH(compName)}</div>`:''}
    <div class="dc-num">${r.d}</div>
    <div class="dc-logo-area">
      ${showLogo&&logoUrl?`<img src="${logoUrl}" class="dc-ev-logo">`:''}
      ${DORSAL_EXTRA_LOGOS.logo1?`<img src="${DORSAL_EXTRA_LOGOS.logo1}" class="dc-ev-logo" alt="Logo 1">`:''}
      ${DORSAL_EXTRA_LOGOS.logo2?`<img src="${DORSAL_EXTRA_LOGOS.logo2}" class="dc-ev-logo" alt="Logo 2">`:''}
      ${DORSAL_EXTRA_LOGOS.logo3?`<img src="${DORSAL_EXTRA_LOGOS.logo3}" class="dc-ev-logo" alt="Logo 3">`:''}
      ${DORSAL_EXTRA_LOGOS.logo4?`<img src="${DORSAL_EXTRA_LOGOS.logo4}" class="dc-ev-logo" alt="Logo 4">`:''}
      ${rcImg}
    </div>
  </div>`;
  // 2 dorsales por hoja A4 (cada uno = mitad A4 = 210mm x 148mm)
  const pages=[];
  for(let i=0;i<dorsalRows.length;i+=2){const pair=dorsalRows.slice(i,i+2);pages.push(`<div class="dpage">${pair.map(buildCard).join('')}</div>`);}
  return`<!DOCTYPE html><html><head><meta charset="utf-8"><title>Dorsales</title><style>
    *{box-sizing:border-box;margin:0;padding:0}
    body{font-family:system-ui,sans-serif;background:#fff}
    .dpage{width:210mm;height:296mm;display:flex;flex-direction:column;page-break-after:always;break-after:page;overflow:hidden}
    .dc{flex:0 0 148mm;width:210mm;height:148mm;display:flex;flex-direction:column;align-items:center;justify-content:space-between;padding:7mm 14mm;text-align:center}
    .dpage .dc:first-child{border-bottom:1.5px dashed #bbb}
    .dc-comp{font-size:${DORSAL_FONT_SIZES.comp}pt;font-weight:700;color:#222;line-height:1.2;word-break:break-word}
    .dc-num{font-size:${DORSAL_FONT_SIZES.num}pt;font-weight:900;color:#111;line-height:1;letter-spacing:-4pt}
    .dc-name{font-size:${DORSAL_FONT_SIZES.name}pt;font-weight:600;color:#333;word-break:break-word}
    .dc-logo-area{display:flex;flex-direction:row;align-items:center;justify-content:center;gap:${logoGap||10}pt;flex-wrap:wrap;padding:0 4pt}
    .dc-ev-logo{max-height:${Math.round(20*(logoSize||100)/100)}mm;max-width:${Math.round(46*(logoSize||100)/100)}mm;object-fit:contain}
    .dc-rc-logo{max-height:${Math.round(24*(logoSize||100)/100)}mm;max-width:${Math.round(52*(logoSize||100)/100)}mm;object-fit:contain}
    @page{margin:0;size:A4 portrait}
    @media print{body{margin:0}.dpage .dc:first-child{border-bottom:1.5px dashed #aaa}}
  </style></head><body>${pages.join('')}</body></html>`;
}
function _openDorsalPrintWindow(html){
  const w=window.open('','_blank','width=700,height=900');
  if(!w){alert('Permití las ventanas emergentes para imprimir.');return;}
  w.document.write(html);
  w.document.close();
  w.onload=()=>{w.focus();w.print();};
}
async function printDorsal(d,leadName){
  const meta=await _getDorsalPrintMeta();
  const showCompName=document.getElementById('dpShowCompName')?.checked!==false;
  const showLogo=document.getElementById('dpShowLogo')?.checked!==false;
  const logoSize=parseFloat(document.getElementById('dpLogoSize')?.value)||100;
  const logoGap=parseFloat(document.getElementById('dpLogoGap')?.value)||10;
  const html=_buildDorsalPrintHtml([{d,leadName}],{...meta,showCompName,showLogo,logoSize,logoGap});
  _openDorsalPrintWindow(html);
}
async function printAllDorsals(){
  const models=CUR==='all'?COMPS.map(c=>c.model):(MODEL?[MODEL]:[]);
  const seen=new Set(),dorsalRows=[];
  models.forEach(M=>{
    M.order.forEach(id=>{
      const pe=M.persons[id];
      if(pe.dorsal===''||seen.has(id)||EXCLUDED_LEADS.has(id))return;
      seen.add(id);
      dorsalRows.push({d:pe.dorsal,leadName:pe.name});
    });
  });
  dorsalRows.sort((a,b)=>a.d-b.d);
  if(!dorsalRows.length){alert('No hay dorsales para imprimir.');return;}
  const meta=await _getDorsalPrintMeta();
  const showCompName=document.getElementById('dpShowCompName')?.checked!==false;
  const showLogo=document.getElementById('dpShowLogo')?.checked!==false;
  const logoSize=parseFloat(document.getElementById('dpLogoSize')?.value)||100;
  const logoGap=parseFloat(document.getElementById('dpLogoGap')?.value)||10;
  const html=_buildDorsalPrintHtml(dorsalRows,{...meta,showCompName,showLogo,logoSize,logoGap});
  _openDorsalPrintWindow(html);
}
function evCard(e,q){
  if(e.kind==='TEAM'){
    const t=e.team;
    if(q&&!key(t.name+' '+(t.members||'')+' '+(t.coreo||'')+' '+e.tipo).includes(q))return null;
    const teamHK=compVoidKey(e);
    const d=document.createElement('details');d.className='ev'+(isHeatVoided(teamHK)?' voided':'');
    const tlabel=(e.time!=null&&horaVisible())?`<span class="hclock">${min2hm(e.time)}</span>`:'';
    const tipoBadge=e.tipo==='Showdance'?`<span class="badge b-sy">Showdance</span>`:e.tipo==='Formation'?`<span class="badge b-ab">Formation</span>`:`<span class="badge b-ph">${e.tipo}</span>`;
    const coreoHtml=t.coreo?`<div class="note" style="font-weight:700;color:var(--wine,#2e6da8)">Coreografía: ${t.coreo}</div>`:'';
    // botones para mover este equipo a cualquiera de los dos bloques (override por equipo)
    const tk=(e.tipo||'Equipo')+'§'+(t.name||'');
    let blockBtns='';
    if(APP_MODE==='admin'){
      const btnStyle=(v)=>'font:inherit;font-size:12px;font-weight:600;padding:4px 10px;border-radius:7px;border:1px solid var(--line);cursor:pointer;background:'+(e.block===v?'var(--wine)':'#fff')+';color:'+(e.block===v?'#fff':'var(--wine)')+';transition:.15s';
      blockBtns='<div class="team-blk" style="display:flex;gap:6px;margin:8px 0 4px;flex-wrap:wrap">'
        +'<span style="font-size:12px;font-weight:600;color:var(--ink-soft);align-self:center">Mover a:</span>'
        +'<button class="team-blk-btn" data-tk="'+tk+'" data-blk="1" style="'+btnStyle(1)+'">Bloque 1 (Smooth / Standard)</button>'
        +'<button class="team-blk-btn" data-tk="'+tk+'" data-blk="2" style="'+btnStyle(2)+'">Bloque 2 (Rhythm / Latin)</button>'
        +'</div>';
    }
    const teamVoidBtn=canFusionarHeats()?`<div style="margin:8px 0 4px"><button class="void-btn${isHeatVoided(teamHK)?' is-voided':''}" id="voidteam-${e.heat}">${isHeatVoided(teamHK)?'✓ Restaurar heat':'🚫 Anular heat'}</button></div>`:'';
    d.innerHTML=`<summary><span class="chev">▸</span><span class="name">HEAT ${(e._displayHeat??e.heat)||'—'} · ${t.name}<small>${t.esc||''} · ${ageRegLabel(t.age)}${e.compTitle?' · '+e.compTitle:''}</small></span>${tlabel}${tipoBadge}${voidBadgeHtml(teamHK)}</summary><div class="body">${teamVoidBtn}${blockBtns}${coreoHtml}<div class="note">${(t.members||'Sin detalle de integrantes').replace(/\n/g,'<br>')}</div></div>`;
    d.querySelectorAll('.team-blk-btn').forEach(btn=>btn.addEventListener('click',ev=>{
      ev.stopPropagation();
      const k=btn.dataset.tk,blk=parseInt(btn.dataset.blk)||1;
      const dflt=parseInt(document.getElementById('teamBlock')?.value||TEAM_BLOCK||1);
      if(blk===dflt){delete TEAM_BLOCKS[k];}else{TEAM_BLOCKS[k]=blk;}
      render();
    }));
    {
      const vb=d.querySelector('#voidteam-'+e.heat);
      if(vb)vb.addEventListener('click',ev=>{ev.stopPropagation();toggleHeatVoided(teamHK);render();});
    }
    return d;
  }
  const cs=e.couples.filter(c=>matchC(c,q));if(q&&!cs.length&&!key(e.name).includes(q))return null;
  const showAll=!q||key(e.name).includes(q);
  const hKey=compVoidKey(e);
  const d=document.createElement('details');d.className='ev'+(isHeatVoided(hKey)?' voided':'');
  const kindBadge=e.kind==='OPEN'?`<span class="badge b-op">Open</span>`:e.kind==='LM'?`<span class="badge b-lm">${lmLabel(e.style)}</span>`:e.kind==='CHALLENGE'?`<span class="badge b-ch">Challenge</span>`:'';
  const synchBadge=e.synchro?`<span class="badge b-sy">Synchro Duo</span>`:'';
  const dancesTxt=e.dances.map(r=>r.replace(/^\([^)]*\) /,'')).join(' · ');
  const tlabel=(e.time!=null&&horaVisible())?`<span class="hclock">${min2hm(e.time)}</span>`:'';
  const maxX=parseInt(document.getElementById('maxper').value)||6;
  const voidCoupleBtnHtml=c=>{
    if(!canFusionarHeats())return'';
    const cV=isCoupleVoided(hKey,c);
    return `<button class="void-couple-btn" data-lead="${c.leadId||''}" data-foll="${c.follId||''}" title="${cV?'Restaurar pareja':'Anular esta pareja'}">${cV?'↺':'⛔'}</button>`;
  };
  const tandasHtml=tandas=>tandas.map((tnd,i)=>`<div class="tanda"><div class="th">Tanda ${i+1} · ${tnd.length} ${tnd.length===1?'pareja':'parejas'}</div>`+
      tnd.map(c=>`<div class="tr${isCoupleVoided(hKey,c)?' void-couple':''}"><span class="dor">${dorsalOf(c)}${checkinBadge(dorsalOf(c))}</span><span>${coupleTxt(c)}</span><span class="bktag">${e.kind==='OPEN'?`<span class="catdim">${c.cat||''}</span>`:(c.cat||'')} ${ageAbbr(c.age)}</span>${voidCoupleBtnHtml(c)}</div>`).join('')+`</div>`).join('');
  const voidHeatBtnHtml=`<button class="void-btn${isHeatVoided(hKey)?' is-voided':''}" id="voidh-${e.heat}">${isHeatVoided(hKey)?'✓ Restaurar heat':'🚫 Anular heat completo'}</button>`;

  if(e.shared){
    const buckHtml=e.buckets.map(b=>{
      const bc=b.couples.filter(c=>showAll||matchC(c,q));if(!bc.length)return'';
      const alone=b.couples.length===1;
      const head=`${b.style} ${b.cat} ${ageRegLabel(b.age)} · ${b.couples.length} ${b.couples.length===1?'pareja':'parejas'}`+(alone?` <span class="cp">Contra el puesto</span>`:` <span class="vs">compiten entre sí</span>`);
      const bDorsBtn=APP_MODE==='admin'?`<button class="act bkt-add-dorsal" style="font-size:10px;padding:2px 8px;margin-left:8px" data-heat="${e.heat}" data-style="${(b.style||e.style||'').replace(/"/g,'&quot;')}" data-cat="${(b.cat||'').replace(/"/g,'&quot;')}" data-age="${(b.age||'').replace(/"/g,'&quot;')}" title="Agregar pareja a este grupo">➕</button>`:'';
      return `<div class="bucket"><div class="bh">${head}${bDorsBtn}</div><table class="t"><tbody>`+
        bc.map(c=>`<tr class="${isCoupleVoided(hKey,c)?'void-couple':''}"><td style="width:56px"><span class="dor">${dorsalOf(c)}${checkinBadge(dorsalOf(c))}</span></td><td>${coupleTxt(c)}${alone?' <span class="cp">· contra el puesto</span>':''}</td><td class="foll">${c.esc||''}${voidCoupleBtnHtml(c)}</td></tr>`).join('')+`</tbody></table></div>`;
    }).join('');
    const nTS=e.tandas?e.tandas.length:1;
    const byCapS=Math.ceil(e.couples.length/maxX),conflictS=nTS>byCapS;
    const tHtml=nTS>1?`<div class="note warn">En pista se baila en ${nTS} tandas (${conflictS?'hay bailarines en más de una pareja':'capacidad de pista'}).</div>${tandasHtml(e.tandas)}`:'';
    // botones de override para este heat
    const sk=e.shareKey||'';
    const curOv=sk?SHARE_OVERRIDES[sk]||'age':'age';
    let ovBtns='';
    if(sk&&APP_MODE==='admin'){
      const btnStyle=(v)=>'font:inherit;font-size:12px;font-weight:600;padding:4px 10px;border-radius:7px;border:1px solid var(--line);cursor:pointer;background:'+(curOv===v?'var(--wine)':'#fff')+';color:'+(curOv===v?'#fff':'var(--wine)')+';transition:.15s';
      ovBtns='<div class="share-ov" style="display:flex;gap:6px;margin:8px 0 4px;flex-wrap:wrap">'
        +'<span style="font-size:12px;font-weight:600;color:var(--ink-soft);align-self:center">Este heat:</span>';
      if(e.synchro||e.abmerge){
        // Synchro y A+B: sólo "Juntar" o "Separar"
        ovBtns+='<button class="ov-btn" data-sk="'+sk+'" data-ov="age" style="'+btnStyle('age')+'">'+(e.synchro?'Pista compartida':'Juntar A+B')+'</button>'
          +'<button class="ov-btn" data-sk="'+sk+'" data-ov="solo" style="'+btnStyle('solo')+'">Separar</button>';
      } else {
        // Shared normal: 3 opciones
        ovBtns+='<button class="ov-btn" data-sk="'+sk+'" data-ov="age" style="'+btnStyle('age')+'">Agrupar por edad</button>'
          +'<button class="ov-btn" data-sk="'+sk+'" data-ov="exact" style="'+btnStyle('exact')+'">Solo iguales</button>'
          +'<button class="ov-btn" data-sk="'+sk+'" data-ov="solo" style="'+btnStyle('solo')+'">Separar</button>';
      }
      ovBtns+='</div>';
    }
    const _showPB=(document.getElementById('pistaLabel')?.value||'show')==='show';
    const _pistaBadge=_showPB?'<span class="badge b-warn">pista compartida</span>':'';
    d.innerHTML=`<summary><span class="chev">▸</span><span class="name">HEAT ${(e._displayHeat??e.heat)||'—'} · ${e.name}<small>${e.couples.length} parejas · ${e.buckets.length} pruebas en pista</small></span>${tlabel}${kindBadge}${_pistaBadge}${conflictBadgeHtml(e)}${voidBadgeHtml(hKey)}${e.manualMerge?'<span class="badge" style="background:#dde9f0;color:var(--blue)">fusión manual</span>':''}</summary>
      <div class="body">${conflictNoteHtml(e)}${ovBtns}${canFusionarHeats()?`<div style="margin:8px 0 4px">${voidHeatBtnHtml}</div>`:''}${(e.manualMerge&&canFusionarHeats())?`<div style="margin:8px 0 4px"><button class="act" style="font-size:12px;padding:4px 12px" id="unmerge-${e.heat}">✕ Deshacer fusión</button></div>`:''}
      <div class="note warn">Comparten pista. Cada grupo de abajo es una <b>competencia aparte</b> (se rankea por su categoría y grupo de edad). Quien está solo en su grupo va <b>contra el puesto</b>.</div>
      <div class="note">Bailes: ${dancesTxt}</div>${buckHtml}${tHtml}</div>`;
    // listener override
    d.querySelectorAll('.ov-btn').forEach(btn=>btn.addEventListener('click',ev=>{
      ev.stopPropagation();
      const sk=btn.dataset.sk,ov=btn.dataset.ov;
      // Para synchro/abmerge: 'age' = default (juntar) → limpiar override. Para shared normal: comparar con global.
      const isSynchroOrAB=sk.startsWith('synchro|')||sk.startsWith('abmerge|');
      if(isSynchroOrAB){
        if(ov==='age'){delete SHARE_OVERRIDES[sk];}else{SHARE_OVERRIDES[sk]=ov;}
      } else {
        const global=document.getElementById('shareMode')?.value||'age';
        if(ov===global){delete SHARE_OVERRIDES[sk];}else{SHARE_OVERRIDES[sk]=ov;}
      }
      render();
    }));
    // listener deshacer fusión manual
    if(e.manualMerge){
      const unBtn=d.querySelector('#unmerge-'+e.heat);
      if(unBtn)unBtn.addEventListener('click',ev=>{
        ev.stopPropagation();
        if(e.directMerge){
          // fusión directa: eliminar por _drk
          DIRECT_MERGES=DIRECT_MERGES.filter(m=>!m.includes(e._drk));
        } else {
          const keys=e.buckets.map(b=>b.eventKey).filter(Boolean);
          MANUAL_MERGES=MANUAL_MERGES.filter(m=>!keys.some(k=>m.includes(k)));
        }
        render();
      });
    }
    // listener anular heat completo / restaurar
    {
      const vb=d.querySelector('#voidh-'+e.heat);
      if(vb)vb.addEventListener('click',ev=>{ev.stopPropagation();toggleHeatVoided(hKey);render();});
    }
    // listener anular pareja individual (dentro de cualquier bucket)
    d.querySelectorAll('.void-couple-btn').forEach(btn=>btn.addEventListener('click',ev=>{
      ev.stopPropagation();
      toggleCoupleVoided(hKey,{leadId:btn.dataset.lead,follId:btn.dataset.foll});
      render();
    }));
    // listener agregar dorsal a un bucket
    d.querySelectorAll('.bkt-add-dorsal').forEach(btn=>btn.addEventListener('click',ev=>{
      ev.stopPropagation();
      openAddDorsalToHeat(parseInt(btn.dataset.heat),btn.dataset.style,btn.dataset.cat,btn.dataset.age,btn.dataset.style+' '+btn.dataset.cat+' '+btn.dataset.age);
    }));
    // Checkbox para agregar más heats a esta fusión
    {
      let ekeyData;
      if(e.manualMerge){
        // Solo necesitamos 1 key para identificar la entrada existente en MANUAL_MERGES
        ekeyData=(e.buckets&&e.buckets[0]?.eventKey)||e.shareKey||('h:'+e.heat);
      } else {
        // Necesitamos TODAS las keys de los buckets para que entren todas en MANUAL_MERGES
        const allBucketKeys=(e.buckets||[]).map(b=>b.eventKey).filter(Boolean);
        ekeyData=allBucketKeys.length>0?allBucketKeys.join(';'):(e.shareKey||('h:'+e.heat));
      }
      if(ekeyData){
        const dkeyS=(e.buckets&&e.buckets[0]?.eventKey)||e.shareKey||('h:'+e.heat);
        if(canFusionarHeats()){
        const selDivS=document.createElement('div');selDivS.className='ev-sel';
        const cbIdS='sel-'+ekeyData.replace(/[^a-z0-9]/gi,'_');
        selDivS.innerHTML=`<input type="checkbox" id="${cbIdS}" data-ekey="${ekeyData}" data-dkey="${dkeyS}"><label for="${cbIdS}">${e.manualMerge?'Seleccionar para agregar más heats':'Seleccionar para fusionar'}</label>`;
        d.appendChild(selDivS);
        selDivS.querySelector('input').addEventListener('change',updateMergeBar);
        }
      }
    }
    return d;
  }

  const sfBadgeEv=e.isSemiF?`<span class="badge" style="background:#fff3d6;color:#b8860b">SEMIFINAL</span>`
                :e.isFinal?`<span class="badge" style="background:#e8f0fe;color:#1a5c8c">FINAL</span>`:'';
  const list=showAll?e.couples:cs;
  const ph=phaseList(e.couples.length);
  const nT=e.tandas?e.tandas.length:1;
  const byCap=Math.ceil(e.couples.length/maxX),conflict=nT>byCap;
  const contra=e.couples.length===1;
  const abBadge=e.abmerge?`<span class="badge b-ab">A+B juntas</span>`:'';
  const cpBadge=contra?`<span class="badge b-cp">Contra el puesto</span>`:'';
  const tandaBadge=nT>1?`<span class="badge b-warn">${nT} tandas</span>`:'';
  // Botones de override para heats abmerge (en el branch no-shared)
  let abOvBtns='';
  if(e.abmerge&&e.shareKey){
    const skAB=e.shareKey;
    const curOvAB=SHARE_OVERRIDES[skAB]||'age';
    const bsAB=(v)=>'font:inherit;font-size:12px;font-weight:600;padding:4px 10px;border-radius:7px;border:1px solid var(--line);cursor:pointer;background:'+(curOvAB===v?'var(--wine)':'#fff')+';color:'+(curOvAB===v?'#fff':'var(--wine)')+';transition:.15s';
    abOvBtns='<div class="share-ov" style="display:flex;gap:6px;margin:8px 0 4px;flex-wrap:wrap">'
      +'<span style="font-size:12px;font-weight:600;color:var(--ink-soft);align-self:center">Este heat:</span>'
      +'<button class="ov-btn" data-sk="'+skAB+'" data-ov="age" style="'+bsAB('age')+'">Juntar A+B</button>'
      +'<button class="ov-btn" data-sk="'+skAB+'" data-ov="solo" style="'+bsAB('solo')+'">Separar A y B</button>'
      +'</div>';
  }
  // Finalist selector para semifinales Multidance (admin/escrutinador only)
  let sfSelectorHtml='';
  if(e.isSemiF&&e.baseKey&&canFusionarHeats()){
    const baseKey=e.baseKey;
    const advance=e.advanceCount||(SEMIFINAL_CONFIG&&SEMIFINAL_CONFIG.advance?SEMIFINAL_CONFIG.advance:6);
    const nextRound=getNextRoundName(e.roundName||'Semifinal');
    const rfKey=e.baseKey+'§'+nextRound;
    const currentFinalists=(ROUNDS_FINALISTS&&ROUNDS_FINALISTS[rfKey])||[];
    const safeKey=baseKey.replace(/&/g,'&amp;').replace(/"/g,'&quot;');
    const safeRfKey=rfKey.replace(/&/g,'&amp;').replace(/"/g,'&quot;');
    const allC=e.couples||[];
    sfSelectorHtml=`<div class="sf-select-panel" data-base="${safeKey}" style="margin:10px 0 4px;padding:12px;border:1px solid var(--line);border-radius:10px;background:var(--card)">
      <div style="font-size:12px;font-weight:700;color:var(--ink);margin-bottom:6px">🏁 Seleccionar ${advance} para ${nextRound==='Final'?'la Final':nextRound}</div>
      <div style="font-size:11px;color:var(--ink-soft);margin-bottom:8px">Marcá las parejas que pasan a ${nextRound==='Final'?'la Final':nextRound}. Sin resultados, pre-selecciona las primeras ${advance} por dorsal.</div>`+
      allC.map((c,i)=>{
        const checked=currentFinalists.length>0?currentFinalists.includes(c.leadId):i<advance;
        return `<label style="display:flex;align-items:center;gap:8px;padding:2px 0;font-size:12px;cursor:pointer">
          <input type="checkbox" data-sf-lid="${c.leadId}" ${checked?'checked':''} style="width:15px;height:15px;flex-shrink:0">
          <span style="font-weight:700;color:#1a5c8c;min-width:40px">${dorsalOf(c)}</span>
          <span style="flex:1">${coupleTxt(c)}</span>
          <span style="color:var(--ink-soft);font-size:11px">${c.cat||''} ${ageAbbr(c.age)}</span>
        </label>`;
      }).join('')+
      `<div style="display:flex;gap:8px;margin-top:10px;align-items:center;flex-wrap:wrap">
        <button type="button" class="act solid sf-save-btn" data-base="${safeKey}" data-rf-key="${safeRfKey}" style="font-size:12px">💾 Guardar pasantes</button>
        <button type="button" class="act sf-print-btn" style="font-size:12px">🖨️ Imprimir listado</button>
        <span class="sf-status" style="font-size:11px;color:var(--ink-soft)"></span>
      </div></div>`;
  }
  // Mensaje para final sin finalistas aún
  const finalEmptyNote=e.isFinal&&e.couples.length===0?`<div class="note warn">Sin finalistas seleccionados aún. Abrí la ronda anterior para elegir quiénes pasan.</div>`:'';
  // Botón para quitar finalistas de la Final (solo admin/escrutinador, solo cuando ya hay parejas cargadas)
  const safeBaseKeyFinal=(e.baseKey||'').replace(/&/g,'&amp;').replace(/"/g,'&quot;');
  const finalRemoveBtn=e.isFinal&&e.baseKey&&e.couples.length>0&&canFusionarHeats()?`<div style="margin:6px 0 2px"><button class="act" style="background:#c0392b;border-color:#c0392b;font-size:12px" onclick="clearFinalFinalists('${safeBaseKeyFinal}')">✕ Quitar finalistas de la Final</button></div>`:'';
  const addDorsEvBtn=APP_MODE==='admin'&&!e.isFinal?`<div style="margin:4px 0"><button class="act ev-add-dorsal" style="font-size:11px;padding:3px 10px" data-heat="${e.heat}" data-style="${(e.style||'').replace(/"/g,'&quot;')}" data-cat="${(e.cat||'').replace(/"/g,'&quot;')}" data-age="${(e.age||'').replace(/"/g,'&quot;')}" title="Agregar pareja a este heat">➕ dorsal</button></div>`:'';
  const _safeEKey=(e.eventKey||'').replace(/"/g,'&quot;');
  const _tandasOk=_HEAT_TANDAS&&e.eventKey&&_HEAT_TANDAS[e.eventKey]?Object.keys(_HEAT_TANDAS[e.eventKey]).length:0;
  const genTandasBtn=canFusionarHeats()&&!e.isFinal&&e.dances&&e.dances.length>0&&e.couples.length>maxX?`<div style="margin:4px 0;display:flex;align-items:center;gap:8px"><button class="act ev-gen-tandas" style="font-size:11px;padding:3px 10px" data-ekey="${_safeEKey}" title="Genera asignación aleatoria de tandas por baile">🎲 Generar tandas</button>${_tandasOk?'<span style="font-size:10.5px;color:#2e7d4f;font-weight:600">✓ '+_tandasOk+' bailes</span>':''}</div>`:'';
  d.innerHTML=`<summary><span class="chev">▸</span><span class="name">HEAT ${(e._displayHeat??e.heat)||'—'} · ${e.name}<small>${e.dances.length} baile(s) · ${e.couples.length} ${e.couples.length===1?'pareja':'parejas'}${nT>1?' · '+nT+' tandas':''}</small></span>${tlabel}${kindBadge}${sfBadgeEv}${synchBadge}${abBadge}${cpBadge}${e.isSemiF||e.isFinal?'':e.couples.length?`<span class="badge b-ph">${ph.length} ${ph.length===1?'ronda':'rondas'}</span>`:''}${tandaBadge}${conflictBadgeHtml(e)}${voidBadgeHtml(hKey)}</summary>
    <div class="body">${conflictNoteHtml(e)}${canFusionarHeats()&&!e.isFinal?`<div style="margin:8px 0 4px">${voidHeatBtnHtml}</div>`:''}${addDorsEvBtn}${genTandasBtn}${abOvBtns}<div class="phases">${ph.map((x,i)=>`<span class="phase ${x==='Final'?'final':''}">${x}</span>${i<ph.length-1?'<span class="ar">→</span>':''}`).join('')}</div>
    ${e.synchro?`<div class="note">Competencia de <b>Synchro Duo</b>: dos bailarines realizan la misma coreografía en sincronía. Se rankea por separado de las parejas y los solos.</div>`:''}
    ${e.abmerge?`<div class="note">Las parejas A y B de este grupo de edad <b>compiten entre sí</b> (mismo ranking).</div>`:''}
    ${contra?`<div class="note">Única pareja en su categoría y grupo de edad: compite <b>contra el puesto</b>.</div>`:''}
    <div class="note">Bailes: ${dancesTxt}</div>${finalEmptyNote}${finalRemoveBtn}`+
    (nT>1?`<div class="note warn">${conflict?'Hay un bailarín en más de una pareja: se baila en '+nT+' tandas para que nadie coincida en pista.':'Primera ronda repartida en '+nT+' tandas por capacidad de pista.'}</div>${tandasHtml(e.tandas)}`:
    e.couples.length?`<table class="t"><thead><tr><th style="width:60px">Dorsal</th><th>Pareja</th><th style="width:60px">Cat.</th><th>Escuela</th></tr></thead><tbody>`+
    list.map(c=>`<tr class="${isCoupleVoided(hKey,c)?'void-couple':''}"><td><span class="dor">${dorsalOf(c)}${checkinBadge(dorsalOf(c))}</span></td><td>${coupleTxt(c)}</td><td>${e.kind==='OPEN'?`<span class="catdim">${c.cat||''}</span>`:(c.cat||'')}</td><td class="foll">${c.esc||''}${voidCoupleBtnHtml(c)}</td></tr>`).join('')+`</tbody></table>`:'')
    +sfSelectorHtml+`</div>`;
  // listener override para abmerge (branch no-shared)
  if(e.abmerge&&e.shareKey){
    d.querySelectorAll('.ov-btn').forEach(btn=>btn.addEventListener('click',ev=>{
      ev.stopPropagation();
      const skBtn=btn.dataset.sk,ovBtn=btn.dataset.ov;
      if(ovBtn==='age'){delete SHARE_OVERRIDES[skBtn];}else{SHARE_OVERRIDES[skBtn]=ovBtn;}
      render();
    }));
  }
  // listener imprimir listado de pasantes/no-pasantes de SemiFinal
  d.querySelectorAll('.sf-print-btn').forEach(btn=>{
    btn.addEventListener('click',ev=>{
      ev.stopPropagation();
      const panel=btn.closest('.sf-select-panel');
      if(!panel)return;
      const advance=e.advanceCount||(SEMIFINAL_CONFIG&&SEMIFINAL_CONFIG.advance?SEMIFINAL_CONFIG.advance:6);
      const nextRound=getNextRoundName(e.roundName||'Semifinal');
      const checkedIds=new Set(Array.from((panel).querySelectorAll('input[data-sf-lid]:checked')).map(cb=>cb.dataset.sfLid));
      const pasan=e.couples.filter(c=>checkedIds.has(c.leadId));
      const noPasan=e.couples.filter(c=>!checkedIds.has(c.leadId));
      printSemifinalList(e,nextRound,advance,pasan,noPasan);
    });
  });
  // listener anular heat completo / restaurar (branch no-shared)
  {
    const vb=d.querySelector('#voidh-'+e.heat);
    if(vb)vb.addEventListener('click',ev=>{ev.stopPropagation();toggleHeatVoided(hKey);render();});
  }
  // listener anular pareja individual (branch no-shared)
  d.querySelectorAll('.void-couple-btn').forEach(btn=>btn.addEventListener('click',ev=>{
    ev.stopPropagation();
    toggleCoupleVoided(hKey,{leadId:btn.dataset.lead,follId:btn.dataset.foll});
    render();
  }));
  // listener agregar dorsal (branch no-shared)
  d.querySelectorAll('.ev-gen-tandas').forEach(btn=>btn.addEventListener('click',ev=>{ev.stopPropagation();generateTandasForHeat(btn.dataset.ekey);}));
  d.querySelectorAll('.ev-add-dorsal').forEach(btn=>btn.addEventListener('click',ev=>{
    ev.stopPropagation();
    openAddDorsalToHeat(parseInt(btn.dataset.heat),btn.dataset.style,btn.dataset.cat,btn.dataset.age,btn.dataset.style+' '+btn.dataset.cat+' '+btn.dataset.age);
  }));
  // checkbox de selección para fusión manual — disponible en todos los heats
  const ekey=e.eventKey||e.shareKey||('h:'+e.heat);
  if(ekey){
    if(canFusionarHeats()){
    const selDiv=document.createElement('div');selDiv.className='ev-sel';
    const cbId='sel-'+ekey.replace(/[^a-z0-9]/gi,'_');
    selDiv.innerHTML=`<input type="checkbox" id="${cbId}" data-ekey="${ekey}" data-dkey="${ekey}"><label for="${cbId}">Seleccionar para fusionar en pista compartida</label>`;
    d.appendChild(selDiv);
    selDiv.querySelector('input').addEventListener('change',updateMergeBar);
    }
  }
  // Guardar pasantes de ronda de clasificación Multidance
  d.querySelectorAll('.sf-save-btn').forEach(btn=>{
    btn.addEventListener('click',async ev=>{
      ev.stopPropagation();
      const rfKey=btn.dataset.rfKey;
      const panel=btn.closest('.sf-select-panel');
      const checked=Array.from((panel||d).querySelectorAll('input[data-sf-lid]:checked')).map(cb=>cb.dataset.sfLid);
      const st=btn.nextElementSibling;
      if(st)st.textContent='⏳ Guardando...';
      ROUNDS_FINALISTS[rfKey]=checked;
      syncSemifinalFinalistsAlias();
      const res=await dbUpload(JSON.stringify(ROUNDS_FINALISTS),true,'rounds-finalists.json');
      if(st)st.textContent=res.ok?'✓ Guardado. Regenerá el cronograma para aplicar.':'⚠ Error: '+res.msg;
      render();
    });
  });
  return d;
}
function paneComp(SCH,q){
  const p=pane('comp');
  // Expand / collapse all toolbar
  const toolbar=document.createElement('div');
  toolbar.style.cssText='display:flex;gap:8px;margin:6px 0 10px;align-items:center';
  toolbar.innerHTML=`<button class="act" id="compExpandAll" style="font-size:12px">▸ Expandir todo</button><button class="act" id="compCollapseAll" style="font-size:12px">▾ Colapsar todo</button>`;
  p.appendChild(toolbar);
  toolbar.querySelector('#compExpandAll').addEventListener('click',()=>{p.querySelectorAll('details.ev').forEach(d=>d.open=true);});
  toolbar.querySelector('#compCollapseAll').addEventListener('click',()=>{p.querySelectorAll('details.ev').forEach(d=>d.open=false);});
  SCH.blocks.forEach((B,bi)=>{
    if(!B.comps.length)return;
    const blkNum=B.globalIdx||B.id;
    const isEven=blkNum%2===0;
    const _blkEditable1=(APP_MODE==='admin'&&typeof B.id==='number');
    const _lk1=B.lblKey!=null?B.lblKey:String(B.id);
    const _blkLabelHtml1=_blkEditable1?`<input class="blk-label-inp" data-bid="${_lk1}" value="${blkLabelOf(_lk1,B.id).replace(/"/g,'&quot;')}" style="font:inherit;font-weight:700;border:none;background:transparent;outline:none;padding:0;min-width:60px;max-width:560px;cursor:text;color:inherit" title="Editar nombre del bloque">`:`<span>${B.label}</span>`;
    const h=document.createElement('div');h.innerHTML=`<div class="sech">${_blkLabelHtml1}<span class="tag ${isEven?'b2':''}">bloque ${blkNum}</span></div><div class="rule"></div>`;
    const _blkInp1=h.querySelector('.blk-label-inp');
    _autoSizeBlkInp(_blkInp1);
    if(_blkInp1)_blkInp1.addEventListener('blur',()=>{_renameBlkLabel(_lk1,B.id,_blkInp1);});
    if(_blkInp1)_blkInp1.addEventListener('keydown',ev=>{if(ev.key==='Enter')_blkInp1.blur();});
    p.appendChild(h);
    B.comps.forEach(e=>{const c=evCard(e,q);if(c)p.appendChild(c);});
  });
  return p;
}

function heatCard(h,q){
  const cs=h.couples.filter(c=>matchC(c,q));if(q&&!cs.length&&!key(h.rl).includes(q))return null;
  const heatLabel='Heat '+(h._displayHeat??h.heat);
  const el=document.createElement('div');el.className='heat';
  const confNote=conflictNoteHtml(h);
  const coupleBtnHtml=(hk,c)=>{
    if(!canFusionarHeats())return'';
    const cV=isCoupleVoided(hk,c);
    return `<button class="void-couple-btn" data-hk="${hk}" data-lead="${c.leadId||''}" data-foll="${c.follId||''}" title="${cV?'Restaurar pareja':'Anular esta pareja'}">${cV?'↺':'⛔'}</button>`;
  };
  if(h._mergedParts){
    // Heat fusionado para display: cada "parte" (ritmo) es un raw heat propio — se anula
    // por separado (no existe un único heat-level void para toda la tarjeta fusionada).
    const hdr=`<div class="hh"><span class="hn">${heatLabel}</span>${(h.time!=null&&horaVisible())?`<span class="hclock">${min2hm(h.time)}</span>`:''}<span>${h.rl}</span>${conflictBadgeHtml(h)}<span class="badge b-cnt" style="margin-left:auto">${h.couples.length} ${h.couples.length===1?'pareja':'parejas'}</span></div>`;
    const rlMatch=q&&key(h.rl).includes(q);
    const partsHtml=h._mergedParts.map((part,pi)=>{
      const pHK=singleVoidKey(part.heat);
      const pVoided=isHeatVoided(pHK);
      const pList=rlMatch?part.couples:part.couples.filter(c=>matchC(c,q));
      const rows=pList.map(c=>`<div class="hr${isCoupleVoided(pHK,c)?' void-couple':''}"><span class="dor">${dorsalOf(c)}${checkinBadge(dorsalOf(c))}</span><span>${coupleTxt(c)}</span>${coupleBtnHtml(pHK,c)}</div>`).join('');
      const sep=pi>0?'border-top:1.5px dashed #ddd;margin-top:4px;':'';
      const partVoidBtn=canFusionarHeats()?`<button class="void-btn${pVoided?' is-voided':''}" data-voidpart="${part.heat}" style="margin-left:8px">${pVoided?'✓ Restaurar':'🚫 Anular este ritmo'}</button>`:'';
      return `<div style="padding:5px 14px 1px;${sep}font-size:12px;font-weight:700;color:var(--wine,#2e6da8);letter-spacing:.01em${pVoided?';text-decoration:line-through;opacity:.6':''}">${part.rl}<span style="font-weight:400;color:var(--ink-soft);margin-left:6px">${part.couples.length} ${part.couples.length===1?'pareja':'parejas'}</span>${voidBadgeHtml(pHK)}${partVoidBtn}</div>${rows}`;
    }).join('');
    el.innerHTML=hdr+confNote+partsHtml;
    el.querySelectorAll('[data-voidpart]').forEach(btn=>btn.addEventListener('click',ev=>{
      ev.stopPropagation();
      toggleHeatVoided(singleVoidKey(parseInt(btn.dataset.voidpart)));
      render();
    }));
  }else{
    const hKey=singleVoidKey(h.heat);
    if(isHeatVoided(hKey))el.classList.add('voided');
    const hdr=`<div class="hh"><span class="hn">${heatLabel}</span>${(h.time!=null&&horaVisible())?`<span class="hclock">${min2hm(h.time)}</span>`:''}<span>${h.rl}</span>${conflictBadgeHtml(h)}${voidBadgeHtml(hKey)}<span class="badge b-cnt" style="margin-left:auto">${h.couples.length} ${h.couples.length===1?'pareja':'parejas'}</span></div>`;
    const list=(q&&!key(h.rl).includes(q))?cs:h.couples;
    const voidBtn=canFusionarHeats()?`<div style="padding:6px 14px 0"><button class="void-btn${isHeatVoided(hKey)?' is-voided':''}" data-voidheat="1">${isHeatVoided(hKey)?'✓ Restaurar heat':'🚫 Anular heat'}</button></div>`:'';
    const addDorsBtn=APP_MODE==='admin'?`<div style="padding:${canFusionarHeats()?'2':'6'}px 14px 6px"><button class="act hc-add-dorsal" style="font-size:11px;padding:3px 10px" data-heat="${h.heat}" data-style="${(h.style||'').replace(/"/g,'&quot;')}" data-cat="${(h.cat||'').replace(/"/g,'&quot;')}" data-age="${(h.age||'').replace(/"/g,'&quot;')}" data-rl="${(h.rl||'').replace(/"/g,'&quot;')}" title="Agregar pareja a este heat">➕ dorsal</button></div>`:'';
    el.innerHTML=hdr+confNote+voidBtn+addDorsBtn+list.map(c=>`<div class="hr${isCoupleVoided(hKey,c)?' void-couple':''}"><span class="dor">${dorsalOf(c)}${checkinBadge(dorsalOf(c))}</span><span>${coupleTxt(c)}</span>${coupleBtnHtml(hKey,c)}</div>`).join('');
    const vhb=el.querySelector('[data-voidheat]');
    if(vhb)vhb.addEventListener('click',ev=>{ev.stopPropagation();toggleHeatVoided(hKey);render();});
  }
  el.querySelectorAll('.void-couple-btn').forEach(btn=>btn.addEventListener('click',ev=>{
    ev.stopPropagation();
    toggleCoupleVoided(btn.dataset.hk,{leadId:btn.dataset.lead,follId:btn.dataset.foll});
    render();
  }));
  el.querySelectorAll('.hc-add-dorsal').forEach(btn=>btn.addEventListener('click',ev=>{
    ev.stopPropagation();
    openAddDorsalToHeat(parseInt(btn.dataset.heat),btn.dataset.style,btn.dataset.cat,btn.dataset.age,btn.dataset.rl);
  }));
  return el;
}
function paneTandas(SCH,q){
  const p=pane('tandas');
  const blocksDisp=getSinglesForDisplay(SCH);
  blocksDisp.forEach(B=>{
    if(!B._displaySingles||!B._displaySingles.length)return;
    const blkNum2=B.globalIdx||B.id;
    const h=document.createElement('div');h.innerHTML=`<div class="sech">Singles ${B.label}<span class="tag ${blkNum2%2===0?'b2':''}">heats ${B.firstSingle}–${B.lastSingle}</span></div><div class="rule"></div>`;p.appendChild(h);
    let any=false;
    B._displaySingles.forEach(s=>{
      if(!s.couples.length)return; // skip truly empty placeholder heats
      const c=heatCard(s,q);if(!c)return;
      // admin/escrutinador: unmerge button for merged singles
      if(canFusionarHeats()&&s._isMergedSingle){
        const unBtn=document.createElement('button');
        unBtn.className='act';unBtn.style.cssText='font-size:12px;padding:4px 12px;margin:6px 0 2px';
        unBtn.textContent='✕ Deshacer fusión';
        unBtn.dataset.mergeHeats=JSON.stringify(s._mergeGroup);
        unBtn.addEventListener('click',()=>{
          const heats=new Set(JSON.parse(unBtn.dataset.mergeHeats));
          SINGLES_MERGES=SINGLES_MERGES.filter(g=>!g.some(h=>heats.has(h)));
          render();
        });
        c.insertBefore(unBtn,c.firstChild);
      }
      // admin: checkbox for merge selection
      if(canFusionarHeats()&&!s._isMergedSingle){
        const selDiv=document.createElement('div');selDiv.className='single-sel';
        selDiv.style.cssText='display:flex;align-items:center;gap:8px;padding:7px 16px 0;border-top:1.5px dashed var(--gold)';
        const cbId='ss-'+s.heat;
        selDiv.innerHTML=`<input type="checkbox" id="${cbId}" data-heat="${s.heat}" style="width:17px;height:17px;accent-color:var(--wine);cursor:pointer"><label for="${cbId}" style="font-size:12.5px;font-weight:600;color:var(--wine);cursor:pointer">Seleccionar para fusionar</label>`;
        selDiv.querySelector('input').addEventListener('change',updateSinglesMergeBar);
        c.appendChild(selDiv);
      }
      p.appendChild(c);any=true;
    });
    if(!any)h.remove();
  });
  // singles merge bar (admin / escrutinador con permiso)
  if(canFusionarHeats()){
    let bar=document.getElementById('singles-merge-bar');
    if(!bar){
      bar=document.createElement('div');bar.id='singles-merge-bar';
      bar.style.cssText='display:none;position:fixed;bottom:24px;left:50%;transform:translateX(-50%);z-index:1000;background:var(--blue,#1d4e89);color:#fff;border-radius:14px;padding:12px 20px;box-shadow:0 8px 32px rgba(0,0,0,.28);align-items:center;gap:12px;white-space:nowrap';
      bar.innerHTML=`<b id="singles-merge-count">0 singles seleccionados</b>
        <button id="singles-merge-btn" style="font:inherit;font-weight:700;font-size:13px;padding:6px 16px;border-radius:8px;border:2px solid #fff;background:#fff;color:var(--blue,#1d4e89);cursor:pointer">⊕ Fusionar</button>
        <button id="singles-cancel-btn" style="font:inherit;font-weight:700;font-size:13px;padding:6px 14px;border-radius:8px;border:2px solid rgba(255,255,255,.5);background:rgba(255,255,255,.15);color:#fff;cursor:pointer">✕ Cancelar</button>`;
      document.body.appendChild(bar);
      document.getElementById('singles-merge-btn').addEventListener('click',()=>{
        const checked=[...document.querySelectorAll('.single-sel input:checked')];
        const heatNums=checked.map(cb=>parseInt(cb.dataset.heat));
        if(heatNums.length<2)return;
        const dupes=hasSinglesMergeDuplicates(heatNums);
        if(dupes.length){showMergeError(dupes);return;}
        // merge: add or extend existing group
        let merged=false;
        for(const g of SINGLES_MERGES){if(heatNums.some(n=>g.includes(n))){heatNums.forEach(n=>{if(!g.includes(n))g.push(n);});merged=true;break;}}
        if(!merged)SINGLES_MERGES.push([...heatNums]);
        bar.style.display='none';
        render();
      });
      document.getElementById('singles-cancel-btn').addEventListener('click',()=>{
        document.querySelectorAll('.single-sel input:checked').forEach(cb=>cb.checked=false);
        bar.style.display='none';
      });
    }
  }
  if(!p.querySelector('.heat'))p.innerHTML=`<div class="note">No hay inscripciones en modalidad de single dance / por ritmo para mostrar tandas.</div>`;
  return p;
}
function paneCron(SCH,q){
  const p=pane('cron');
  // Toolbar admin: "Agregar bloque" + "Ordenar 1→N"
  if(APP_MODE==='admin'){
    const _toolbar=document.createElement('div');
    _toolbar.style.cssText='display:flex;justify-content:flex-end;gap:8px;padding:6px 14px 0;';
    const _btnStyle='font-size:12px;padding:3px 10px;border:1px solid var(--border);border-radius:6px;cursor:pointer;';
    // Agregar bloque
    const _addBtn=document.createElement('button');
    _addBtn.textContent='➕ Agregar bloque';
    _addBtn.title='Crear un nuevo bloque vacío al final del cronograma';
    _addBtn.style.cssText=_btnStyle+'background:var(--accent,#c9a84c);color:#fff;border-color:var(--accent,#c9a84c);font-weight:600;';
    _addBtn.addEventListener('click',()=>{BLOCK_COUNT=(BLOCK_COUNT||2)+1;render();});
    // Restablecer organización (descarta todos los cambios manuales del cronograma)
    const _resetBtn=document.createElement('button');
    _resetBtn.textContent='↺ Restablecer organización';
    _resetBtn.title='Reorganizar el cronograma desde cero, como si no se hubiera movido nada a mano';
    _resetBtn.style.cssText=_btnStyle+'background:var(--bg2,var(--bg));color:var(--ink);opacity:.8;';
    _resetBtn.addEventListener('mouseenter',()=>_resetBtn.style.opacity='1');
    _resetBtn.addEventListener('mouseleave',()=>_resetBtn.style.opacity='.8');
    _resetBtn.addEventListener('click',()=>{
      const _n=Object.keys(EVENT_BLOCKS).length+Object.keys(TEAM_BLOCKS).length+Object.keys(JJ_BLOCK_OVERRIDES).length+Object.keys(ROUND_BLOCKS).length+Object.keys(HEAT_REORDER).length+HIDDEN_BREAKS.size;
      if(!confirm('¿Restablecer la organización del cronograma?\n\nSe descartan '+_n+' cambio(s) manual(es):\n· heats movidos entre bloques\n· rondas (semifinal/final) movidas por separado\n· reordenamientos dentro de un bloque\n· breaks ocultos\n\nSe conservan los nombres de los bloques, la cantidad de bloques y los horarios.\n\nEsta acción no se puede deshacer.'))return;
      EVENT_BLOCKS={};TEAM_BLOCKS={};JJ_BLOCK_OVERRIDES={};ROUND_BLOCKS={};HEAT_REORDER={};
      HIDDEN_BREAKS=new Set();
      try{localStorage.setItem('rc_hidden_breaks','[]');}catch{}
      render();
    });
    _toolbar.appendChild(_addBtn);
    _toolbar.appendChild(_resetBtn);
    p.appendChild(_toolbar);
  }
  const showPista=(document.getElementById('pistaLabel')?.value||'show')==='show';
  const dispName=n=>showPista?n:n.replace(' · pista compartida','');
  // c.range ya tiene los números de display (actualizado por prepareSCHDisplay en render)
  // Ordenar cron por posición del bloque (SCH.blocks order) para que bloques con heats movidos
  // o JJ overrides no aparezcan duplicados ni fuera de orden en la vista del Cronograma.
  const _cronR=[...SCH.cron].sort((a,b)=>{
    const oa=typeof a.blkSeq==='number'?a.blkSeq:9999;
    const ob=typeof b.blkSeq==='number'?b.blkSeq:9999;
    return oa-ob;
  });
  // Helper compartido: eliminar bloque D, mover sus heats al bloque anterior
  const _deleteBlock=(D)=>{
    if(typeof D!=='number'||BLOCK_COUNT<=1)return;
    const _dest=D>1?D-1:2;                 // bloque destino antes de renumerar
    const _destTxt=D>1?'anterior':'siguiente';
    if(!confirm('¿Eliminar el bloque '+D+'? Sus heats pasan al bloque '+_destTxt+'.'))return;
    // Paso A: heats que están en D por defecto (sin override) → fijarlos en el destino
    SCH.cron.forEach(entry=>{
      if(entry.blockId!==D)return;
      if(entry.roundKey&&entry.baseKey&&entry.roundKey!==entry.baseKey){ROUND_BLOCKS[entry.roundKey]=_dest;}
      else if(entry.teamKey){TEAM_BLOCKS[entry.teamKey]=_dest;}
      else if(entry.ekey&&String(entry.ekey).startsWith('jj\u00a7')){JJ_BLOCK_OVERRIDES[entry.ekey]=_dest;}
      else if(entry.key){EVENT_BLOCKS[entry.key]=_dest;}
    });
    // Paso B: renumerar todos los overrides (===D → destino; >D → baja 1)
    [EVENT_BLOCKS,TEAM_BLOCKS,JJ_BLOCK_OVERRIDES,ROUND_BLOCKS].forEach(map=>{
      Object.keys(map).forEach(k=>{
        if(map[k]===D)map[k]=_dest;
        else if(typeof map[k]==='number'&&map[k]>D)map[k]=map[k]-1;
      });
    });
    // Paso B2: el default global de equipos también se renumera
    if(TEAM_BLOCK===D)TEAM_BLOCK=_dest;
    else if(typeof TEAM_BLOCK==='number'&&TEAM_BLOCK>D)TEAM_BLOCK=TEAM_BLOCK-1;
    if(TEAM_BLOCK>BLOCK_COUNT-1)TEAM_BLOCK=Math.max(1,BLOCK_COUNT-1);
    // Paso C: desplazar horarios de bloque (clave estable "2" / "WEST2§2" y la vieja "b2")
    const _shiftTimes=prefix=>{
      for(let i=D;i<BLOCK_COUNT;i++){
        const nx=BLOCK_TIMES[prefix+(i+1)];
        if(nx!=null)BLOCK_TIMES[prefix+i]=nx; else delete BLOCK_TIMES[prefix+i];
      }
      delete BLOCK_TIMES[prefix+BLOCK_COUNT];
    };
    _shiftTimes('');_shiftTimes('b');
    [...new Set(Object.keys(BLOCK_TIMES).filter(k=>k.includes('§')).map(k=>k.slice(0,k.lastIndexOf('§')+1)))].forEach(_shiftTimes);
    // Paso D: desplazar nombres — tanto la clave global "id" como las "sheet§id"
    const _shiftLabels=prefix=>{
      for(let i=D;i<BLOCK_COUNT;i++){
        const nx=BLOCK_LABELS[prefix+(i+1)];
        if(nx!=null)BLOCK_LABELS[prefix+i]=nx; else delete BLOCK_LABELS[prefix+i];
      }
      delete BLOCK_LABELS[prefix+BLOCK_COUNT];
    };
    _shiftLabels('');
    [...new Set(Object.keys(BLOCK_LABELS).filter(k=>k.includes('\u00a7')).map(k=>k.slice(0,k.lastIndexOf('\u00a7')+1)))].forEach(_shiftLabels);
    BLOCK_COUNT--;
    render();
  };
  // Marcar qué tramos consecutivos tienen al menos un heat real (no solo prueba)
  const cronShow=new Array(_cronR.length).fill(false);
  let ci=0;
  while(ci<_cronR.length){
    let cj=ci;
    while(cj<_cronR.length&&_cronR[cj].lblKey===_cronR[ci].lblKey)cj++;
    if(_cronR.slice(ci,cj).some(x=>!x.isPrueba))for(let k=ci;k<cj;k++)cronShow[k]=true;
    ci=cj;
  }
  let last=null;
  let _lastNumBlkId=0; // tracks last rendered numeric blockId to detect empty-block gaps
  // Control de hora de inicio dentro del encabezado del bloque (solo admin).
  // Usa la misma clave estable que "Inicio de cada bloque" en Configuración.
  const _addBlkTimeCtl=(sech,lblKey,legacy,blkId)=>{
    if(APP_MODE!=='admin'||typeof blkId!=='number'||!sech)return;
    const cur=blkTimeGet(lblKey,legacy);
    const wrap=document.createElement('span');
    wrap.style.cssText='display:inline-flex;align-items:center;gap:4px;margin-left:12px;font-weight:400;flex-shrink:0;white-space:nowrap';
    const lab=document.createElement('span');
    lab.textContent='inicio';
    lab.style.cssText='font-size:11px;color:var(--ink-soft)';
    const inp=document.createElement('input');
    inp.type='text';inp.className='blk-time-cron';
    inp.value=cur!=null?min2hm(cur):'';
    inp.placeholder='HH:MM';
    inp.title='Hora de inicio de este bloque (vacío = seguido del bloque anterior)';
    inp.style.cssText='width:60px;font:inherit;font-size:11px;font-weight:600;padding:2px 5px;border:1px solid var(--line);border-radius:6px;background:var(--bg);color:var(--ink);text-align:center';
    inp.addEventListener('click',ev=>ev.stopPropagation());
    inp.addEventListener('mousedown',ev=>ev.stopPropagation());
    inp.addEventListener('change',()=>{
      const v=hm2min(inp.value);
      if(v!=null){BLOCK_TIMES[lblKey]=v;delete BLOCK_TIMES[legacy];render();}
      else if(!inp.value.trim()){delete BLOCK_TIMES[lblKey];delete BLOCK_TIMES[legacy];render();}
      else{inp.value=cur!=null?min2hm(cur):'';} // valor inválido: volver al anterior
    });
    inp.addEventListener('keydown',ev=>{if(ev.key==='Enter')inp.blur();});
    wrap.appendChild(lab);wrap.appendChild(inp);
    sech.style.display='flex';sech.style.alignItems='center';
    sech.appendChild(wrap);
  };
  // Renombrar un bloque: guarda el override en su clave (global o por competencia),
  // sincroniza las cajas de texto que comparten esa clave y la solapa Configuración.
  // NO llama a render() para no perder el foco ni reordenar el cronograma.
  const _applyBlkRename=_renameBlkLabel;
  // Bloques sin heats: se intercalan en su posición (por blkSeq), no al final
  const _keyOf=B=>B.lblKey!=null?B.lblKey:String(B.id);
  // competencia a la que pertenece una clave "sheet§id" ('' en vista de una sola competencia)
  const _compOfKey=k=>{k=String(k==null?'':k);const i=k.lastIndexOf('§');return i<0?'':k.slice(0,i);};
  // competencias que tienen al menos un heat visible
  const _liveComps=new Set(_cronR.filter((x,xi)=>cronShow[xi]&&x.blockId!=='jj').map(x=>_compOfKey(x.lblKey)));
  const _shownKeys=new Set(_cronR.filter((x,xi)=>cronShow[xi]).map(x=>x.lblKey));
  const _emptyQ=[...(SCH.blocks||[])]
    .filter(B=>typeof B.id==='number')
    .filter(B=>!_shownKeys.has(_keyOf(B)))
    // no mostrar bloques vacíos de una competencia que no tiene ningún heat
    .filter(B=>_liveComps.size===0||_liveComps.has(_compOfKey(_keyOf(B))))
    .sort((a,b)=>(a.blkSeq||0)-(b.blkSeq||0));
  let _eqi=0;
  const _flushEmptyBlks=uptoSeq=>{
    if(APP_MODE!=='admin')return;
    while(_eqi<_emptyQ.length&&(_emptyQ[_eqi].blkSeq||0)<(uptoSeq!=null?uptoSeq:Infinity)){_renderEmptyBlk(_emptyQ[_eqi]);_eqi++;}
  };
  const _defBlkLabelE=id=>id===1?'Smooth / Standard':id===2?'Rhythm / Latin':'Bloque '+id;
  // Helper: render empty block (header + placeholder + drag handlers)
  const _renderEmptyBlk=(B)=>{
    if(last!==null){const brE=document.createElement('div');brE.className='cronrow';brE.innerHTML=`<span class="hh2" style="color:var(--ink)">Break</span><span class="pista" style="background:#f6e2d0;color:var(--warn)">descanso entre bloques</span>`;p.appendChild(brE);}
    const _lkE=B.lblKey!=null?B.lblKey:String(B.id);
    const _blkNm=blkLabelOf(_lkE,B.id);
    const _sufE=(B.label&&B.label.includes(' · '))?B.label.slice(B.label.indexOf(' · ')):'';
    const hE=document.createElement('div');
    hE.innerHTML=`<div class="sech"><input class="blk-label-inp" data-bid="${_lkE}" value="${_blkNm.replace(/"/g,'&quot;')}" style="font:inherit;font-weight:700;border:none;background:transparent;outline:none;padding:0;min-width:60px;max-width:560px;cursor:text;color:inherit" title="Editar nombre del bloque"><span style="font-weight:700">${_sufE}</span></div><div class="rule"></div>`;
    const inpE=hE.querySelector('.blk-label-inp');
    _autoSizeBlkInp(inpE);
    if(inpE){inpE.addEventListener('blur',()=>{_applyBlkRename(_lkE,B.id,inpE);});inpE.addEventListener('keydown',ev=>{if(ev.key==='Enter')inpE.blur();});}
    _addBlkTimeCtl(hE.querySelector('.sech'),_lkE,'b'+(B.globalIdx||B.blkSeq||B.id),B.id);
    if(BLOCK_COUNT>1){
      const _dBtnE=document.createElement('button');
      _dBtnE.title='Eliminar este bloque vacío';_dBtnE.textContent='🗑️';
      _dBtnE.style.cssText='margin-left:auto;background:none;border:none;cursor:pointer;font-size:13px;padding:1px 4px;border-radius:4px;color:var(--ink-soft);opacity:.5;flex-shrink:0;';
      _dBtnE.addEventListener('mouseenter',()=>_dBtnE.style.opacity='1');
      _dBtnE.addEventListener('mouseleave',()=>_dBtnE.style.opacity='.5');
      _dBtnE.addEventListener('click',ev=>{ev.stopPropagation();_deleteBlock(B.id);});
      hE.querySelector('.sech').style.display='flex';hE.querySelector('.sech').style.alignItems='center';
      hE.querySelector('.sech').appendChild(_dBtnE);
    }
    const _dropEmpty=(targetId,el)=>ev=>{ev.preventDefault();el.classList.remove('drag-over-bot','drag-over-top');let dd;try{dd=JSON.parse(ev.dataTransfer.getData('text/plain'));}catch{return;}if(dd.roundKey){ROUND_BLOCKS[dd.roundKey]=targetId;render();}else if(dd.kind==='TEAM'&&dd.teamKey){const df=TEAM_BLOCK||1;if(targetId===df){delete TEAM_BLOCKS[dd.teamKey];}else{TEAM_BLOCKS[dd.teamKey]=targetId;}render();}else if(dd.evKey){EVENT_BLOCKS[dd.evKey]=targetId;render();}else if(dd.ekey&&dd.ekey.startsWith('jj§')){JJ_BLOCK_OVERRIDES[dd.ekey]=targetId;render();}};
    hE.addEventListener('dragover',ev=>{if(!p.querySelector('.dragging'))return;ev.preventDefault();ev.dataTransfer.dropEffect='move';hE.classList.add('drag-over-bot');});
    hE.addEventListener('dragleave',()=>hE.classList.remove('drag-over-bot'));
    hE.addEventListener('drop',_dropEmpty(B.id,hE));
    p.appendChild(hE);last=String(B.id);_lastNumBlkId=B.id;
    const erE=document.createElement('div');erE.className='cronrow';erE.style.cssText='opacity:.5;justify-content:center;font-size:12px;color:var(--ink-soft);padding:12px 16px';erE.textContent='— bloque vacío: arrastrá o usá el selector en cada heat para mover heats aquí —';
    erE.addEventListener('dragover',ev=>{if(!p.querySelector('.dragging'))return;ev.preventDefault();ev.dataTransfer.dropEffect='move';erE.classList.add('drag-over-top');});
    erE.addEventListener('dragleave',()=>erE.classList.remove('drag-over-top'));
    erE.addEventListener('drop',_dropEmpty(B.id,erE));
    p.appendChild(erE);
  };
  // Mapa baseKey → {semis:[items], final:item} para aclaraciones "continúa en / viene de"
  const _bkMapCron={};
  _cronR.forEach(it=>{if(!it.baseKey||it._voided)return;_bkMapCron[it.baseKey]=_bkMapCron[it.baseKey]||{semis:[],final:null};if(it.isSemiF)_bkMapCron[it.baseKey].semis.push(it);else if(it.isFinal)_bkMapCron[it.baseKey].final=it;});
  _cronR.forEach((c,ci)=>{
    if(!cronShow[ci])return;
    if(q&&!key(c.name+' '+c.block).includes(q))return;
    const _curBlkKey=c.lblKey!=null?String(c.lblKey):String(c.blockId);
    _flushEmptyBlks(c.blkSeq);
    if(_curBlkKey!==last){
      if(last!==null){
        const bk='blk:'+last+'→blk:'+_curBlkKey;
        const hidden=HIDDEN_BREAKS.has(bk);
        if(APP_MODE==='admin'){
          const br=document.createElement('div');
          if(hidden){
            br.style.cssText='display:flex;align-items:center;gap:8px;padding:2px 12px;opacity:.45';
            br.innerHTML=`<span style="flex:1;border-top:1.5px dashed #ccc"></span><button onclick="toggleBreak('${bk}')" title="Restaurar break" style="font-size:11px;padding:1px 8px;border:1px dashed #aaa;border-radius:6px;background:var(--card);cursor:pointer;color:var(--ink-soft);white-space:nowrap">+ restaurar break</button>`;
          }else{
            br.className='cronrow';
            br.innerHTML=`<span class="hh2" style="color:var(--ink)">Break</span><span class="pista" style="background:#f6e2d0;color:var(--warn)">descanso entre bloques</span><button onclick="toggleBreak('${bk}')" title="Ocultar break" style="margin-left:auto;background:none;border:none;cursor:pointer;color:var(--ink-soft);font-size:14px;padding:2px 6px;border-radius:4px" title="Ocultar">✕</button>`;
          }
          p.appendChild(br);
        }else if(!hidden){
          const br=document.createElement('div');br.className='cronrow';br.innerHTML=`<span class="hh2" style="color:var(--ink)">Break</span><span class="pista" style="background:#f6e2d0;color:var(--warn)">descanso entre bloques</span>`;p.appendChild(br);
        }
      }
      const _blkEdCron=(APP_MODE==='admin'&&typeof c.blockId==='number');
      const _blkBaseCron=blkLabelOf(_curBlkKey,c.blockId);
      const _blkSuffixCron=c.block.includes(' · ')?c.block.slice(c.block.indexOf(' · ')):'';
      const _blkLabelHtmlCron=_blkEdCron
        ?`<input class="blk-label-inp" data-bid="${_curBlkKey}" value="${_blkBaseCron.replace(/"/g,'&quot;')}" style="font:inherit;font-weight:700;border:none;background:transparent;outline:none;padding:0;min-width:60px;max-width:560px;cursor:text;color:inherit" title="Editar nombre del bloque"><span style="font-weight:700">${_blkSuffixCron}</span>`
        :`<span>${c.block}</span>`;
      const h=document.createElement('div');h.innerHTML=`<div class="sech">${_blkLabelHtmlCron}</div><div class="rule"></div>`;
      const _blkInpCron=h.querySelector('.blk-label-inp');
      _autoSizeBlkInp(_blkInpCron);
      if(_blkInpCron)_blkInpCron.addEventListener('blur',()=>{_applyBlkRename(_curBlkKey,c.blockId,_blkInpCron);});
      if(_blkInpCron)_blkInpCron.addEventListener('keydown',ev=>{if(ev.key==='Enter')_blkInpCron.blur();});
      _addBlkTimeCtl(h.querySelector('.sech'),_curBlkKey,'b'+(c.blkSeq||c.blockId),c.blockId);
      // Botón eliminar bloque (admin, numérico, al menos 2 bloques)
      if(APP_MODE==='admin'&&typeof c.blockId==='number'&&BLOCK_COUNT>1){
        const _dBtn=document.createElement('button');
        _dBtn.title='Eliminar este bloque (heats pasan al bloque anterior)';
        _dBtn.textContent='🗑️';
        _dBtn.style.cssText='margin-left:auto;background:none;border:none;cursor:pointer;font-size:13px;padding:1px 4px;border-radius:4px;color:var(--ink-soft);opacity:.5;flex-shrink:0;';
        _dBtn.addEventListener('mouseenter',()=>_dBtn.style.opacity='1');
        _dBtn.addEventListener('mouseleave',()=>_dBtn.style.opacity='.5');
        _dBtn.addEventListener('click',ev=>{ev.stopPropagation();_deleteBlock(c.blockId);});
        h.querySelector('.sech').style.display='flex';h.querySelector('.sech').style.alignItems='center';
        h.querySelector('.sech').appendChild(_dBtn);
      }
      p.appendChild(h);last=_curBlkKey;
      // Permite soltar un heat de Equipo (Showdance/Formation) sobre el título de este bloque
      // para moverlo aquí, aunque el bloque esté vacío de otros heats de equipo para apuntar.
      if(canMoverHeats()&&c.blockId!=null){
        const hBlockId=c.blockId;
        h.addEventListener('dragover',ev=>{
          const dragging=p.querySelector('.dragging');
          if(!dragging||(dragging.dataset.kind!=='TEAM'&&dragging.dataset.movable!=='1'&&!dragging.dataset.evKey))return;
          ev.preventDefault();ev.dataTransfer.dropEffect='move';
          h.classList.add('drag-over-bot');
        });
        h.addEventListener('dragleave',()=>h.classList.remove('drag-over-bot'));
        h.addEventListener('drop',ev=>{
          ev.preventDefault();h.classList.remove('drag-over-bot');
          let data;try{data=JSON.parse(ev.dataTransfer.getData('text/plain'));}catch{return;}
          if(data.roundKey){
            ROUND_BLOCKS[data.roundKey]=hBlockId;
            render();
          } else if(data.kind==='TEAM'&&data.teamKey){
            const dflt=TEAM_BLOCK||1;
            if(hBlockId===dflt){delete TEAM_BLOCKS[data.teamKey];}else{TEAM_BLOCKS[data.teamKey]=hBlockId;}
            render();
          } else if(data.evKey){
            EVENT_BLOCKS[data.evKey]=hBlockId;
            render();
          }
        });
      }
    }
    if(c.isPrueba){
      const row=document.createElement('div');row.className='cronrow';
      const tt=(c.time!=null&&horaVisible())?`<span class="hclock-soft" style="font-size:11.5px;font-weight:600;color:var(--ink-soft);font-variant-numeric:tabular-nums;letter-spacing:.2px;white-space:nowrap">${min2hm(c.time)}–${min2hm(c.timeEnd)}</span>`:'';
      row.innerHTML=`<span class="hh2" style="color:var(--ink)">Prueba</span>${tt}<span class="pista" style="background:#e8f0fb;color:var(--blue)">Prueba de pista</span>`;
      p.appendChild(row);
    } else if(c.isSingle){
      const row=document.createElement('div');row.className='cronrow';
      const tt=(c.time!=null&&horaVisible())?`<span class="hclock-soft" style="font-size:11.5px;font-weight:600;color:var(--ink-soft);font-variant-numeric:tabular-nums;letter-spacing:.2px;white-space:nowrap">${min2hm(c.time)}–${min2hm(c.timeEnd)}</span>`:'';
      const confB=c._hasConflict?'<span class="badge b-conflict" title="Al menos un bailarín de este rango tiene un posible choque de horario — ver pestaña Orden/Tandas para el detalle">⚠ choque</span>':'';
      const voidB=c._voidedCount?`<span class="badge b-voided" title="Hay heat(s) anulado(s) dentro de este rango — ver pestaña Tandas/Orden para el detalle">${c._voidedCount===c._voidedTotal?'ANULADO':c._voidedCount+' anulado(s)'}</span>`:'';
      row.innerHTML=`<span class="hh2">Heat ${c.range}</span>${tt}<span class="pista">🎵 ${c.name}</span>${confB}${voidB}`;
      p.appendChild(row);
    } else {
      // comp heat: draggable
      const rk=c._reoKey||c.name;
      const tt=(c.time!=null&&horaVisible())?`<span class="hclock-soft" style="font-size:11.5px;font-weight:600;color:var(--ink-soft);font-variant-numeric:tabular-nums;letter-spacing:.2px;white-space:nowrap">${min2hm(c.time)}</span>`:'';
      const isTeam=c.kind==='TEAM';
      const teamKey=isTeam?(c.tipo||'Equipo')+'§'+(c.team?.name||''):'';
      const row=document.createElement('div');row.className='cronrow';
      if(canMoverHeats()){row.draggable=true;row.dataset.bkey=c.block;row.dataset.ekey=rk;if(isTeam){row.dataset.kind='TEAM';row.dataset.teamKey=teamKey;}if(c.movable)row.dataset.movable='1';if(c.key)row.dataset.evKey=c.key||'';}
      // En modo admin mostramos un select de bloque para TODOS los heats (no solo TEAM/movable).
      // Esto permite mover cualquier heat a cualquiera de los N bloques configurados.
      const _pairCount=c.n?`<span class="foll" style="margin-left:6px;font-size:11px;color:var(--ink-soft)">${c.n} ${c.n===1?'pareja':'parejas'}</span>`:'';
      let trailing='';
      if(APP_MODE==='admin'&&!c.isSingle&&!c.isPrueba&&c.kind!=='JJ'){
        const _defBlk=id=>id===1?'Smooth / Standard':id===2?'Rhythm / Latin':'Bloque '+id;
        const _dflt=parseInt(document.getElementById('teamBlock')?.value||TEAM_BLOCK||1);
        // Ronda reubicable: intermedia o final (su clave difiere de la de la competencia base)
        const _isRound=!!(c.roundKey&&c.baseKey&&c.roundKey!==c.baseKey);
        const _curBlk=_isRound?(ROUND_BLOCKS[c.roundKey]!=null?ROUND_BLOCKS[c.roundKey]:(c.blockId!=null?c.blockId:_dflt))
                     :isTeam?(TEAM_BLOCKS[teamKey]||_dflt)
                     :(EVENT_BLOCKS[c.key]!=null?EVENT_BLOCKS[c.key]:c.blockId!=null?c.blockId:_dflt);
        const _opts=Array.from({length:BLOCK_COUNT},(_x,i)=>{const id=i+1;const nm=BLOCK_LABELS[id]||_defBlk(id);return `<option value="${id}"${_curBlk===id?' selected':''}>B${id}–${nm}</option>`;}).join('');
        const _selKind=_isRound?'round':(isTeam?'team':'event');
        const _selTitle=_isRound?('Mover solo esta ronda ('+(c.isFinal?'Final':'clasificatoria')+') a otro bloque'):'Mover al bloque';
        trailing=`<span style="display:flex;align-items:center;gap:4px;margin-left:auto">${_pairCount}<select class="blk-sel-cron" data-kind="${_selKind}" data-tk="${teamKey}" data-ek="${c.key||''}" data-rok="${(c.roundKey||'').replace(/"/g,'&quot;')}" data-dflt="${_dflt}" title="${_selTitle}" style="font:inherit;font-size:11px;border:1px solid var(--line);border-radius:4px;padding:2px 4px;background:var(--bg);color:var(--ink);cursor:pointer;max-width:160px">${_opts}</select></span>`;
      } else {
        trailing=c.n?`<span class="foll" style="margin-left:auto">${c.n} ${c.n===1?'pareja':'parejas'}</span>`:'';
      }
      const confBc=c._hasConflict?'<span class="badge b-conflict" title="Posible choque de horario: mismo bailarín en heats muy próximos — ver pestaña Orden para el detalle">⚠ choque</span>':'';
      if(c._voided)row.classList.add('voided');
      const _bkAnnotCron=(()=>{if(!c.baseKey)return'';const bk=_bkMapCron[c.baseKey];if(c.isSemiF&&bk&&bk.final)return' <span style="font-size:11px;color:var(--ink-soft)">· continúa en H '+bk.final.range+'</span>';if(c.isFinal&&bk&&bk.semis.length)return' <span style="font-size:11px;color:var(--ink-soft)">· viene de H '+bk.semis.map(s=>s.range).join(', ')+'</span>';return'';})();
      row.innerHTML=`${canMoverHeats()?'<span class="drag-handle" title="Arrastrar">&#8942;&#8942;</span>':''}<span class="hh2 hh2-link" data-rk="${rk}" title="Ver en Orden General">Heat ${c.range}</span>${tt}<span>${dispName(c.name)}${_bkAnnotCron}</span>${confBc}${c._voided?'<span class="badge b-voided" title="Heat anulado: no se juzga ni cuenta para resultados">ANULADO</span>':''}${trailing}`;
      row.querySelector('.hh2-link').addEventListener('click',ev=>{ev.stopPropagation();goToHeatInOrden(rk);});
      row.querySelectorAll('.blk-sel-cron').forEach(sel=>sel.addEventListener('change',ev=>{
        ev.stopPropagation();
        const blk=parseInt(sel.value)||1;
        const dflt=parseInt(sel.dataset.dflt)||TEAM_BLOCK||1;
        if(sel.dataset.kind==='round'){
          const rok=sel.dataset.rok;
          if(rok)ROUND_BLOCKS[rok]=blk;
        }else if(sel.dataset.kind==='team'){
          const k=sel.dataset.tk;
          if(blk===dflt){delete TEAM_BLOCKS[k];}else{TEAM_BLOCKS[k]=blk;}
        }else{
          const k=sel.dataset.ek;
          if(k)EVENT_BLOCKS[k]=blk;
        }
        render();
      }));
      if(canMoverHeats()){row.addEventListener('dragstart',ev=>{
        ev.dataTransfer.setData('text/plain',JSON.stringify({bkey:c.block,ekey:rk,kind:c.kind||'',teamKey,movable:!!c.movable,evKey:c.key||'',roundKey:(c.roundKey&&c.baseKey&&c.roundKey!==c.baseKey)?c.roundKey:''}));
        ev.dataTransfer.effectAllowed='move';
        row.classList.add('dragging');
      });
      row.addEventListener('dragend',()=>row.classList.remove('dragging'));
      row.addEventListener('dragover',ev=>{
        const dragging=p.querySelector('.dragging');
        if(!dragging||dragging===row)return;
        const sameBlock=dragging.dataset.bkey===c.block;
        const draggingIsMovable=dragging.dataset.kind==='TEAM'||dragging.dataset.movable==='1';
        const draggingIsJJ=dragging.dataset.ekey&&dragging.dataset.ekey.startsWith('jj§');
        const draggingHasEvKey=!!dragging.dataset.evKey;
        if(!sameBlock&&!draggingIsMovable&&!draggingIsJJ&&!draggingHasEvKey)return;
        ev.preventDefault();ev.dataTransfer.dropEffect='move';
        const mid=row.getBoundingClientRect().top+row.getBoundingClientRect().height/2;
        row.classList.toggle('drag-over-top',ev.clientY<mid);
        row.classList.toggle('drag-over-bot',ev.clientY>=mid);
      });
      row.addEventListener('dragleave',()=>row.classList.remove('drag-over-top','drag-over-bot'));
      row.addEventListener('drop',ev=>{
        ev.preventDefault();
        row.classList.remove('drag-over-top','drag-over-bot');
        let data;try{data=JSON.parse(ev.dataTransfer.getData('text/plain'));}catch{return;}
        if(data.kind==='TEAM'&&data.bkey!==c.block){
          // soltado sobre un heat de OTRO bloque: mover el equipo a ese bloque
          if(c.blockId==null)return;
          const dflt=TEAM_BLOCK||1;
          if(c.blockId===dflt){delete TEAM_BLOCKS[data.teamKey];}else{TEAM_BLOCKS[data.teamKey]=c.blockId;}
          render();
          return;
        }
        if(data.roundKey&&data.bkey!==c.block){
          if(c.blockId==null||typeof c.blockId!=='number')return;
          ROUND_BLOCKS[data.roundKey]=c.blockId;
          render();
          return;
        }
        if(data.evKey&&data.bkey!==c.block){
          // soltado sobre un heat de OTRO bloque: mover el evento a ese bloque
          if(c.blockId==null||typeof c.blockId!=='number')return;
          EVENT_BLOCKS[data.evKey]=c.blockId;
          render();
          return;
        }
        if(data.bkey!==c.block){
          // Allow JJ heats to be moved across blocks
          if(data.ekey&&data.ekey.startsWith('jj§')){
            if(typeof c.blockId==='number'){JJ_BLOCK_OVERRIDES[data.ekey]=c.blockId;render();return;}
            if(c.blockId==='jj'){delete JJ_BLOCK_OVERRIDES[data.ekey];render();return;}
          }
          return;
        }
        const allRows=[...p.querySelectorAll(`.cronrow[data-bkey="${CSS.escape(c.block)}"]`)];
        const fromIdx=allRows.findIndex(r=>r.dataset.ekey===data.ekey);
        let toIdx=allRows.indexOf(row);
        if(fromIdx<0||fromIdx===toIdx)return;
        const mid=row.getBoundingClientRect().top+row.getBoundingClientRect().height/2;
        if(ev.clientY>=mid&&toIdx<allRows.length-1)toIdx++;
        const keys=allRows.map(r=>r.dataset.ekey);
        const[moved]=keys.splice(fromIdx,1);
        keys.splice(toIdx,0,moved);
        HEAT_REORDER[reorderBlockKey(c.block)]=keys;
        _mdreportCache=null; // invalidate so Resultados Multidance shows updated heat numbers
        render();
      });} // end if admin
      p.appendChild(row);
    }
  });
  // Bloques vacíos que quedan después del último bloque con heats
  _flushEmptyBlks(Infinity);
  return p;
}

// HEAT_REORDER se guarda con la clave del bloque (B.label). Pero buildFullSchedule (modo "Todo el
// evento") le agrega ' · '+título de competencia al label para no mezclar bloques de distintas
// competencias, mientras que buildSchedule (una sola competencia) deja el label tal cual. Sin
// normalizar, un reordenamiento guardado en un modo no se encuentra al leer en el otro modo —
// causa raíz de la inconsistencia entre Cronograma y Resultados Multidance (buildMultidanceVoteUnits
// siempre usa buildFullSchedule, pero Cronograma/Orden general usan el modo que esté activo en CUR).
function reorderBlockKey(label){return String(label||'').split(' · ')[0];}
function applyHeatReorder(SCH){
  if(!Object.keys(HEAT_REORDER).length)return;
  SCH.blocks.forEach(B=>{
    const order=HEAT_REORDER[reorderBlockKey(B.label)];
    if(!order||!B.comps.length)return;
    // asignar clave estable a cada comp
    B.comps.forEach(e=>{e._reoKey=e.shareKey||e.eventKey||e.name;});
    const byKey={};B.comps.forEach(e=>{byKey[e._reoKey]=e;});
    // reordenar: claves conocidas primero, desconocidas al final
    const reordered=[];
    order.forEach(k=>{if(byKey[k])reordered.push(byKey[k]);});
    B.comps.forEach(e=>{if(!order.includes(e._reoKey))reordered.push(e);});
    // tomar (heat,time) del orden original y reasignar al nuevo orden
    const slots=B.comps.map(e=>({heat:e.heat,time:e.time}));
    reordered.forEach((e,i)=>{e.heat=slots[i].heat;e.time=slots[i].time;});
    B.comps=reordered;
    // actualizar entradas del cron: reemplazar solo los items de comp de este bloque,
    // en su posición original, para no mezclar bloques de distintas competencias
    const compCron=reordered.map(e=>({block:B.label,blockId:B.id,lblKey:B.lblKey,blkSeq:B.blkSeq,teamKey:(e.team?((e.tipo||'Equipo')+'§'+(e.team.name||'')):null),range:''+e.heat,name:e.name,n:e.isFinal?0:(e.couples?e.couples.length:0),time:e.time,_reoKey:e._reoKey||e.shareKey||e.eventKey||e.name,kind:e.kind,style:e.style||'',team:e.team,tipo:e.tipo,movable:e.movable,key:e.key,isFinal:e.isFinal||false,isSemiF:e.isSemiF||false,baseKey:e.baseKey||null,roundKey:e.eventKey||null,_voided:isHeatVoided(compVoidKey(e))}));
    const _bk=B.lblKey!=null?B.lblKey:String(B.id);
    const _same=c=>(c.lblKey!=null?c.lblKey:String(c.blockId))===_bk;
    const isBlockComp=c=>_same(c)&&!c.isSingle&&!c.isPrueba;
    const firstPos=SCH.cron.findIndex(isBlockComp);
    if(firstPos>=0){
      // solo se sacan las entradas de ESTE bloque; el resto queda intacto
      SCH.cron=[...SCH.cron.slice(0,firstPos),...compCron,...SCH.cron.slice(firstPos).filter(c=>!isBlockComp(c))];
    }else{
      // no habia comps originales: insertar después de prueba/singles del bloque
      const lastBItem=SCH.cron.reduce((acc,c,i)=>_same(c)?i:acc,-1);
      const ins=lastBItem>=0?lastBItem+1:SCH.cron.length;
      SCH.cron=[...SCH.cron.slice(0,ins),...compCron,...SCH.cron.slice(ins)];
    }
  });
}
function paneOrden(SCH,q){
  const p=pane('orden');
  const showPistaO=(document.getElementById('pistaLabel')?.value||'show')==='show';
  const blocksDisp=getSinglesForDisplay(SCH);
  blocksDisp.forEach(B=>{
    if(!B._displaySingles.length&&!B.comps.length)return; // bloque vacío tras exclusiones
    const blkNum3=B.globalIdx||B.id;
    const _blkEditable3=(APP_MODE==='admin'&&typeof B.id==='number');
    const _lk3=B.lblKey!=null?B.lblKey:String(B.id);
    const _blkLabelHtml3=_blkEditable3?`<input class="blk-label-inp" data-bid="${_lk3}" value="${blkLabelOf(_lk3,B.id).replace(/"/g,'&quot;')}" style="font:inherit;font-weight:700;border:none;background:transparent;outline:none;padding:0;min-width:60px;max-width:560px;cursor:text;color:inherit" title="Editar nombre del bloque">`:`<span>${B.label}</span>`;
    const h=document.createElement('div');h.innerHTML=`<div class="sech">${_blkLabelHtml3}<span class="tag ${blkNum3%2===0?'b2':''}">bloque ${blkNum3}</span></div><div class="rule"></div>`;
    const _blkInp3=h.querySelector('.blk-label-inp');
    _autoSizeBlkInp(_blkInp3);
    if(_blkInp3)_blkInp3.addEventListener('blur',()=>{_renameBlkLabel(_lk3,B.id,_blkInp3);});
    if(_blkInp3)_blkInp3.addEventListener('keydown',ev=>{if(ev.key==='Enter')_blkInp3.blur();});
    p.appendChild(h);
    B._displaySingles.forEach(s=>{
      const c=heatCard(s,q);if(!c)return;
      if(canFusionarHeats()&&s._isMergedSingle){
        const unBtn=document.createElement('button');
        unBtn.className='act';unBtn.style.cssText='font-size:12px;padding:4px 12px;margin:6px 0 2px';
        unBtn.textContent='✕ Deshacer fusión';
        unBtn.dataset.mergeHeats=JSON.stringify(s._mergeGroup);
        unBtn.addEventListener('click',()=>{
          const heats=new Set(JSON.parse(unBtn.dataset.mergeHeats));
          SINGLES_MERGES=SINGLES_MERGES.filter(g=>!g.some(h=>heats.has(h)));
          render();
        });
        c.insertBefore(unBtn,c.firstChild);
      }
      if(canFusionarHeats()&&!s._isMergedSingle){
        const selDiv=document.createElement('div');selDiv.className='single-sel';
        selDiv.style.cssText='display:flex;align-items:center;gap:8px;padding:7px 16px 0;border-top:1.5px dashed var(--gold)';
        const cbId='sso-'+s.heat;
        selDiv.innerHTML=`<input type="checkbox" id="${cbId}" data-heat="${s.heat}" style="width:17px;height:17px;accent-color:var(--wine);cursor:pointer"><label for="${cbId}" style="font-size:12.5px;font-weight:600;color:var(--wine);cursor:pointer">Seleccionar para fusionar</label>`;
        selDiv.querySelector('input').addEventListener('change',updateSinglesMergeBar);
        c.appendChild(selDiv);
      }
      p.appendChild(c);
    });
    B.comps.forEach((e,ei)=>{
      const eDisp=showPistaO?e:{...e,name:e.name.replace(' · pista compartida','')};
      const c=evCard(eDisp,q);if(!c)return;
      c.open=false;
      const rk=e._reoKey||e.shareKey||e.eventKey||e.name;
      // inject handle inside <details> summary, before .name
      c.dataset.ekey=rk; // always set for cronograma hyperlink
      if(canMoverHeats()){
      c.draggable=true;
      c.dataset.bkey=B.label;
      const handle=document.createElement('span');
      handle.className='drag-handle';
      handle.innerHTML='&#8942;&#8942;';
      handle.title='Arrastrar para reordenar';
      const summary=c.querySelector('summary');
      summary.insertBefore(handle,summary.querySelector('.name')||summary.firstChild);
      // drag events on <details> itself
      c.addEventListener('dragstart',ev=>{
        ev.dataTransfer.setData('text/plain',JSON.stringify({bkey:B.label,ekey:rk}));
        ev.dataTransfer.effectAllowed='move';
        c.classList.add('dragging');
      });
      c.addEventListener('dragend',()=>{c.classList.remove('dragging');});
      c.addEventListener('dragover',ev=>{
        ev.preventDefault();ev.dataTransfer.dropEffect='move';
        const dragging=p.querySelector('.dragging');
        if(!dragging||dragging===c)return;
        const _sameBlk=(dragging.dataset.bkey===B.label);
        const _jjCross=dragging.dataset.ekey&&dragging.dataset.ekey.startsWith('jj§')&&typeof B.id==='number';
        if(!_sameBlk&&!_jjCross)return;
        const mid=c.getBoundingClientRect().top+c.getBoundingClientRect().height/2;
        c.classList.toggle('drag-over-top',ev.clientY<mid);
        c.classList.toggle('drag-over-bot',ev.clientY>=mid);
      });
      c.addEventListener('dragleave',()=>{c.classList.remove('drag-over-top','drag-over-bot');});
      c.addEventListener('drop',ev=>{
        ev.preventDefault();
        c.classList.remove('drag-over-top','drag-over-bot');
        let data;try{data=JSON.parse(ev.dataTransfer.getData('text/plain'));}catch{return;}
        if(data.bkey!==B.label){
          // Allow JJ heats to be moved across blocks
          if(data.ekey&&data.ekey.startsWith('jj§')){
            if(typeof B.id==='number'){JJ_BLOCK_OVERRIDES[data.ekey]=B.id;render();return;}
            if(B.id==='jj'){delete JJ_BLOCK_OVERRIDES[data.ekey];render();return;}
          }
          return;
        }
        const allRows=[...p.querySelectorAll(`details[data-bkey="${CSS.escape(B.label)}"]`)];
        const fromIdx=allRows.findIndex(r=>r.dataset.ekey===data.ekey);
        let toIdx=allRows.indexOf(c);
        if(fromIdx<0||fromIdx===toIdx)return;
        const mid=c.getBoundingClientRect().top+c.getBoundingClientRect().height/2;
        if(ev.clientY>=mid&&toIdx<allRows.length-1)toIdx++;
        const keys=allRows.map(r=>r.dataset.ekey);
        const[moved]=keys.splice(fromIdx,1);
        keys.splice(toIdx,0,moved);
        HEAT_REORDER[reorderBlockKey(B.label)]=keys;
        _mdreportCache=null; // invalidate so Resultados Multidance shows updated heat numbers
        render();
      });} // end if admin
      p.appendChild(c);
    });
  });
  return p;
}

/* ---------- EXPORT XLSX ---------- */

function buildInsMapData(xComps){
  const dnC=r=>r.replace(/^\([^)]*\) /,'').replace(/\[|\]/g,'');
  const MODALIDAD_STYLE={Standard:'International',Latin:'International',Smooth:'American',Rhythm:'American',SocialLatino:'Social',SocialArgentino:'Social',SocialAmericano:'Social'};
  // Reglas configurables (Configuración → "Ritmos por categoría y modalidad") — ver dancesForCategory.
  const danceSetFor=dancesForCategory;
  const _SKIP_SHEETS=new Set(['__inscripciones_web__','__inscripciones_web_aabd__','__manual_couples__']);
  const insMap={};
  xComps.forEach(comp=>{
    const M=comp.model;
    const compName=comp.title||comp.sheet||'';
    const _isExcel=!_SKIP_SHEETS.has(comp.sheet);
    M.events.forEach(e=>{
      e.couples.forEach(c=>{
        if(!c.leadId)return;
        const mk=c.leadId+'|'+(c.foll||'');
        if(!insMap[mk])insMap[mk]={dorsal:'',lead:c.lead,foll:c.foll||'',esc:c.esc||'',dni:'',follDni:'',items:[],leadId:c.leadId,_fromExcel:false};
        if(_isExcel)insMap[mk]._fromExcel=true;
        const rec=insMap[mk];
        if(!rec.dorsal){const p=M.persons[c.leadId];if(p&&p.dorsal!=='')rec.dorsal=p.dorsal;}
        if(!rec.dni){const p=M.persons[c.leadId];if(p&&p.dni)rec.dni=p.dni;}
        if(!rec.follDni&&c.follId){const pf=M.persons[c.follId];if(pf&&pf.dni)rec.follDni=pf.dni;}
        if(e.kind==='SD'||e.kind==='CHALLENGE'){
          const tipo=e.kind==='CHALLENGE'?'Challenge':'Single Dance';
          const rl=dnC(e.dances[0]||'');
          const modalidad=MODALIDAD_STYLE[e.style]||'';
          // Profesional-Amateur: solo aplica a Single Dance en pareja (no a Challenge ni a solistas)
          const pa=e.kind==='SD'&&!!c.foll&&c.proAm==='Profesional-Amateur';
          const detalle=(modalidad?`${rl} · ${modalidad}`:rl)+(pa?' · Profesional-Amateur':'');
          const contested=e.kind==='SD'?(c.contested||'Contested'):'';
          const cat=(c.cat&&c.cat!=='—')?c.cat:'';
          const age=(c.age&&c.age!=='—')?c.age:'';
          const ex=rec.items.find(i=>i.tipo===tipo&&i.detalle===detalle&&i.comp===compName&&i.contested===contested);
          if(ex)ex.count++;
          else rec.items.push({tipo,detalle,cat,age,comp:compName,count:1,contested});
        } else {
          const isSynchroOpen=e.synchro&&e.kind==='OPEN';
          const tipo=e.synchro?(isSynchroOpen?'Synchro Duo Open':'Synchro Duo'):e.kind==='OPEN'?'Open':'Letra/Medalla';
          // Para ritmos de Synchro Open, usar DANCESETS completo (no hay categoría de nivel fija)
          const ritmosCat=isSynchroOpen?(DANCESETS[e.style]||[]).join(', '):danceSetFor(e.style,c.cat).join(', ');
          // Profesional-Amateur: clave separada para no fusionar su fila con Amateur-Amateur
          const pa=!e.solo&&!e.synchro&&c.proAm==='Profesional-Amateur';
          const k2=tipo+'|'+e.style+'|'+c.cat+'|'+c.age+'|'+compName+'|'+(pa?'PA':'');
          if(!rec.items.some(i=>i._key===k2))
            rec.items.push({_key:k2,tipo,detalle:e.style+(e.solo?' · Solo':isSynchroOpen?' · Synchro Duo Open':e.synchro?' · Synchro Duo':(pa?' · Profesional-Amateur':'')),cat:isSynchroOpen?'Open':(c.cat||''),age:c.age||'',ritmos:ritmosCat,comp:compName});
        }
      });
    });
    // Equipos coreográficos (Showdance/Formation): no tienen lead/foll de pareja,
    // pero deben listarse igual en Inscripciones con su propio dorsal.
    (M.teams||[]).forEach((t,ti)=>{
      const mk='team|'+compName+'|'+ti+'|'+(t.name||'');
      insMap[mk]={dorsal:t.dorsal||'',lead:t.name||'Equipo',foll:'',esc:t.esc||'',dni:'',follDni:'',items:[{tipo:t.tipo||'Equipo',detalle:t.coreo||'',cat:'',age:t.age||'',comp:compName,ritmos:t.members||''}]};
    });
  });
  return insMap;
}

function paneInscripciones(q){
  const p=pane('inscripciones');
  const xComps=CUR==='all'?COMPS:(MODEL?[COMPS[CUR]||{model:MODEL,title:'',sheet:''}]:[]);
  if(!xComps.length){p.innerHTML='<p style="color:var(--ink-soft);padding:24px">Cargá un archivo primero.</p>';return p;}
  const insMap=buildInsMapData(xComps);
  const sorted=Object.values(insMap).sort((a,b)=>(a.dorsal-b.dorsal)||(key(a.lead)<key(b.lead)?-1:1));
  // filter by q
  const filtered=q?sorted.filter(r=>key(r.lead).includes(q)||key(r.foll).includes(q)||key(r.esc).includes(q)||key(r.dni||'').includes(q)||key(r.follDni||'').includes(q)||r.items.some(i=>key(i.detalle).includes(q)||key(i.comp).includes(q))):sorted;
  const showDni=APP_MODE==='admin';
  const showActions=APP_MODE==='admin';
  const hdrs=['Dorsal','Nombre',...(showDni?['DNI']:[]),'Follower',...(showDni?['DNI Follower']:[]),'Escuela','Competencia','Tipo','Disciplina','Cat.','Edad','Ritmos / Baile',...(showActions?['']:[] )];
  let html=`<div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse;font-size:13px">
<thead><tr>${hdrs.map(h=>`<th style="background:var(--blue);color:#fff;padding:6px 8px;text-align:left;white-space:nowrap;position:sticky;top:0">${h}</th>`).join('')}${showActions?'<th style="background:var(--blue);color:#fff;padding:6px 8px;position:sticky;top:0;width:60px"></th>':''}</tr></thead><tbody>`;
  filtered.forEach((rec,ri)=>{
    const bg=ri%2===0?'var(--bg)':'var(--card)';
    const itemsToShow=rec.items.length?rec.items:[{tipo:'',detalle:'',cat:'',age:'',comp:'',ritmos:'',count:0}];
    itemsToShow.forEach((item,ii)=>{
      const isFirst=ii===0;
      let ritmosCell=(item.tipo==='Single Dance'||item.tipo==='Challenge')?(item.count>1?item.detalle+' x'+item.count:item.detalle):(item.ritmos||'');
      if(item.tipo==='Single Dance'&&item.contested)ritmosCell+=` · <span style="font-weight:600;color:${item.contested==='Uncontested'?'#b8860b':'var(--ink-soft)'}">${item.contested}</span>`;
      const tipoCss=item.tipo==='Single Dance'?'color:#b8860b;font-weight:600':item.tipo==='Open'||item.tipo==='Synchro Duo Open'?'color:var(--ink);font-weight:600':'';
      const _safeD=(rec.dni||'').replace(/'/g,"\\'")||'',_safeN=(rec.lead||'').replace(/'/g,"\\'");const actionCell=showActions&&isFirst&&rec._fromExcel?`<td style="padding:4px 6px;white-space:nowrap"><button onclick="openExcelInscrEdit('${rec.leadId}')" title="Editar inscripción" style="background:none;border:1px solid var(--line);border-radius:6px;padding:3px 7px;cursor:pointer;font-size:12px;color:var(--ink-soft)" onmouseover="this.style.background='var(--bg)'" onmouseout="this.style.background='none'">✎</button></td>`:showActions&&isFirst?`<td style="padding:4px 6px;white-space:nowrap"><button onclick="openInscrEditByDni('${_safeD}','${_safeN}')" title="Editar inscripción" style="background:none;border:1px solid var(--line);border-radius:6px;padding:3px 7px;cursor:pointer;font-size:12px;color:var(--ink-soft)" onmouseover="this.style.background='var(--bg)'" onmouseout="this.style.background='none'">✎</button></td>`:showActions?`<td></td>`:'';
      html+=`<tr style="background:${bg}">
        <td style="padding:5px 8px;font-weight:700;color:var(--ink);text-align:center;white-space:nowrap">${isFirst?(rec.dorsal||'—'):''}</td>
        <td style="padding:5px 8px;font-weight:${isFirst?700:400}">${isFirst?rec.lead:''}</td>
        ${showDni?`<td style="padding:5px 8px;font-size:11px;color:var(--ink-soft)">${isFirst?(rec.dni||''):''}</td>`:''}
        <td style="padding:5px 8px;color:${rec.foll?'var(--ink)':'var(--ink-soft)'};font-style:${rec.foll?'normal':'italic'}">${isFirst?(rec.foll||'—'):''}</td>
        ${showDni?`<td style="padding:5px 8px;font-size:11px;color:var(--ink-soft)">${isFirst?(rec.follDni||''):''}</td>`:''}
        <td style="padding:5px 8px;font-size:11px;color:var(--ink-soft)">${isFirst?(rec.esc||''):''}</td>
        <td style="padding:5px 8px;font-size:11px;color:var(--ink-soft)">${item.comp||''}</td>
        <td style="padding:5px 8px;${tipoCss}">${item.tipo||''}</td>
        <td style="padding:5px 8px">${item.detalle||''}</td>
        <td style="padding:5px 8px;text-align:center">${item.cat||''}</td>
        <td style="padding:5px 8px;font-size:11px">${ageRegLabel(item.age)||''}</td>
        <td style="padding:5px 8px;font-size:11px;color:var(--ink-soft)">${ritmosCell}</td>
        ${actionCell}
      </tr>`;
    });
    html+=`<tr style="height:6px;background:var(--card)"><td colspan="${hdrs.length+(showActions?1:0)}"></td></tr>`;
  });
  html+='</tbody></table></div>';
  if(!filtered.length)html='<p style="color:var(--ink-soft);padding:24px">Sin resultados.</p>';

  // Sección Jack & Jill — inscripciones individuales de _JJ_INSC
  if(_JJ_INSC&&_JJ_INSC.length){
    const jjRows=[];
    _JJ_INSC.forEach(ins=>{
      (ins.rows||[]).forEach(r=>{
        const nombre=r['Nombre']||r['Nombre (leader)']||ins.resumen||'';
        const dni=r['DNI']||r['DNI del leader']||'';
        const rol=r['Rol']||'Leader';
        const nivel=r['Nivel']||r['Grupo de edad']||'—';
        const esc=r['Seleccione su escuela']||'';
        if(!q||key(nombre).includes(q)||key(dni).includes(q)||key(rol).includes(q)||key(nivel).includes(q))
          jjRows.push({nombre,dni,rol,nivel,esc,id:ins.id,created_at:ins.created_at});
      });
    });
    if(jjRows.length){
      html+=`<div style="margin-top:24px"><div class="sech">🃏 Jack & Jill<span class="tag">${jjRows.length}</span></div><div class="rule"></div>`;
      html+=`<div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse;font-size:13px">
<thead><tr>
  <th style="background:var(--blue);color:#fff;padding:6px 8px;text-align:left">Nombre</th>
  ${showDni?'<th style="background:var(--blue);color:#fff;padding:6px 8px;text-align:left">DNI</th>':''}
  <th style="background:var(--blue);color:#fff;padding:6px 8px;text-align:left">Rol</th>
  <th style="background:var(--blue);color:#fff;padding:6px 8px;text-align:left">Nivel</th>
  <th style="background:var(--blue);color:#fff;padding:6px 8px;text-align:left">Escuela</th>
</tr></thead><tbody>`;
      jjRows.forEach((r,ri)=>{
        const bg=ri%2===0?'var(--bg)':'var(--card)';
        html+=`<tr style="background:${bg}">
          <td style="padding:5px 8px;font-weight:600">${r.nombre}</td>
          ${showDni?`<td style="padding:5px 8px;font-size:11px;color:var(--ink-soft)">${r.dni}</td>`:''}
          <td style="padding:5px 8px">${r.rol}</td>
          <td style="padding:5px 8px;font-size:11px;color:var(--ink-soft)">${r.nivel}</td>
          <td style="padding:5px 8px;font-size:11px;color:var(--ink-soft)">${r.esc}</td>
        </tr>`;
      });
      html+='</tbody></table></div></div>';
    }
  }

  p.innerHTML=html;
  return p;
}
// ==================== Edición de inscripciones Excel ====================
function _excelRowsForLead(leadId){
  const SKIP=new Set(['__inscripciones_web__','__inscripciones_web_aabd__','__manual_couples__']);
  const result=[];
  COMPS.forEach((comp,ci)=>{
    if(SKIP.has(comp.sheet))return;
    const rows=comp.rows||[];
    if(!rows.length)return;
    const hdrs=[];rows.forEach(r=>{if(r)Object.keys(r).forEach(k=>{if(!hdrs.includes(k))hdrs.push(k);});});
    const cLead=findCol(hdrs,'(leader)')||'Nombre (leader)';
    const cLeadDni=findCol(hdrs,'dni del leader')||'DNI del leader';
    // Separar fila principal (multidance) de filas de singles; devolver 1 resultado por comp
    let primaryRow=null,primaryRi=-1,singlesRi=-1;
    const singles={};
    rows.forEach((row,ri)=>{
      const name=clean(row[cLead]||'');
      const dni=String(row[cLeadDni]||'');
      if(!name)return;if(idOf(name,dni)!==leadId&&idOf(name,'')!==leadId)return;
      if(row['Elegir modalidad']==='Single Dance'){
        singlesRi=ri;
        Object.keys(row).forEach(k=>{if(k.startsWith('Ritmos (')&&Number(row[k])>0)singles[k]=Number(row[k]);});
      } else if(!primaryRow){primaryRow=row;primaryRi=ri;}
    });
    if(!primaryRow&&singlesRi>=0){primaryRow=rows[singlesRi];primaryRi=singlesRi;}
    if(primaryRow)result.push({ci,ri:primaryRi,singlesRi,comp,row:primaryRow,singles});
  });
  return result;
}
function openExcelInscrEdit(leadId){
  const matches=_excelRowsForLead(leadId);
  if(!matches.length){
    // Fallback: puede ser un solo cuyo DNI en Excel no coincide con leadId name-based → buscar en Supabase
    const _M=COMPS[0]?.model;
    const _p=_M&&_M.persons?.[leadId];
    if(_p){openInscrEditByDni(_p.dni||'',_p.name||'');return;}
    alert('No se encontraron datos Excel para este inscripto.');return;
  }
  const ex=document.getElementById('excelInscrEditModal');if(ex)ex.remove();
  const firstRow=matches[0].row;
  const INP='width:100%;box-sizing:border-box;padding:8px 10px;border:1.5px solid var(--line);border-radius:8px;font-size:13px;background:var(--card);color:var(--ink)';
  const LBL='font-size:12px;font-weight:600;color:var(--ink-soft);display:block;margin-bottom:4px';
  const FLD='margin-bottom:14px';
  const CAT_LBL={NC:'Newcomer (NC)',HB:'Half Bronze (HB)',FB:'Full Bronze (FB)',SL:'Silver (SL)',GD:'Gold (GD)',F:'Half-Bronze (F)',E:'Bronze (E)',D:'Silver (D)',C:'Gold (C)',B:'B',A:'A',Open:'Open',Principiante:'Principiante',Intermedio:'Intermedio',Avanzado:'Avanzado'};
  const CATS_INT=[''].concat(REG_NIVELES_INT_PRIVADA).concat(REG_NIVELES_INT_PRIVADA.length?['Open']:[]);
  const CATS_AM=[''].concat(REG_NIVELES_AM_PRIVADA).concat(REG_NIVELES_AM_PRIVADA.length?['Open']:[]);
  const mkSocCats=nivs=>[''].concat(nivs).concat(nivs.length?['Open']:[]);
  const styles=[
    {id:'std',lbl:'Standard',col:'Standard categoria',cats:CATS_INT},
    {id:'lat',lbl:'Latin',col:'Latin categoria',cats:CATS_INT},
    {id:'sm',lbl:'Smooth',col:'Smooth categoria',cats:CATS_AM},
    {id:'rh',lbl:'Rhythm',col:'Rhythm categoria',cats:CATS_AM},
    {id:'sl',lbl:'Soc. Latino',col:'SocialLatino categoria',cats:mkSocCats(REG_NIVELES_SOCLA_PRIVADA)},
    {id:'sg',lbl:'Soc. Argentino',col:'SocialArgentino categoria',cats:mkSocCats(REG_NIVELES_SOCAR_PRIVADA)},
    {id:'sa',lbl:'Soc. Americano',col:'SocialAmericano categoria',cats:mkSocCats(REG_NIVELES_SOCAM_PRIVADA)},
  ];
  const catSel=(id,cats,val)=>`<select id="${id}" style="${INP};font-size:12px;padding:6px 8px">${cats.map(c=>`<option value="${c}"${c===(val||'')?'selected':''}>${c?(CAT_LBL[c]||c):'—'}</option>`).join('')}</select>`;
  const AGES=['','Adu','Jun','Juv','Pre','Sen','Senior 1','Senior 2','Senior 3','Senior 4','Pro'];
  const AGE_LBL={Adu:'Adulto',Jun:'Junior',Juv:'Juvenil',Pre:'Pre-juvenil',Sen:'Senior','Senior 1':'Senior 1','Senior 2':'Senior 2','Senior 3':'Senior 3','Senior 4':'Senior 4',Pro:'Profesional'};
  const ageSel=`<select id="einscr_edad" style="${INP}">${AGES.map(a=>`<option value="${a}"${a===(firstRow['Grupo de edad']||'')?'selected':''}>${a?(AGE_LBL[a]||a):'—'}</option>`).join('')}</select>`;
  // Grupos de single dances: grupo → {label, dances[]}
  const SD_GROUPS=[
    {g:'INT-ST',lbl:'Standard',dances:DANCESETS['Standard']||[]},
    {g:'INT-LT',lbl:'Latin',dances:DANCESETS['Latin']||[]},
    {g:'AM-SM',lbl:'Smooth',dances:DANCESETS['Smooth']||[]},
    {g:'AM-RH',lbl:'Rhythm',dances:DANCESETS['Rhythm']||[]},
    {g:'SOC-LA',lbl:'Soc. Latino',dances:DANCESETS['SocialLatino']||[]},
    {g:'SOC-AR',lbl:'Soc. Argentino',dances:DANCESETS['SocialArgentino']||[]},
    {g:'SOC-AM',lbl:'Soc. Americano',dances:DANCESETS['SocialAmericano']||[]},
  ];
  const compRowsHtml=matches.map((m,mi)=>{
    const compTitle=(m.comp.title||m.comp.sheet||`Archivo ${mi+1}`).replace(/</g,'&lt;');
    const cats=styles.map(s=>`<div style="flex:1;min-width:90px"><label style="font-size:10px;color:var(--ink-soft)">${s.lbl}</label>${catSel('einscr_'+mi+'_'+s.id,s.cats,m.row[s.col])}</div>`).join('');
    // Singles por ritmo: número de veces que baila cada ritmo
    const singlesHtml=SD_GROUPS.filter(sg=>sg.dances.length>0).map(sg=>{
      const inps=sg.dances.map(d=>{
        const colKey='Ritmos ('+sg.g+') ['+d+']';
        const qty=m.singles[colKey]||0;
        return `<div style="display:inline-flex;align-items:center;gap:3px;font-size:11px;white-space:nowrap"><input type="number" id="einscr_${mi}_sd_${sg.g}_${d.replace(/\s+/g,'_')}" value="${qty}" min="0" max="9" style="width:38px;text-align:center;padding:2px 4px;border:1px solid var(--line);border-radius:4px;font-size:11px;background:var(--card);color:var(--ink)"><span>${d}</span></div>`;
      }).join('');
      return `<div style="margin-bottom:6px"><div style="font-size:10px;font-weight:700;color:var(--ink-soft);margin-bottom:3px">${sg.lbl}</div><div style="display:flex;flex-wrap:wrap;gap:6px 10px">${inps}</div></div>`;
    }).join('');
    return `<div style="margin-bottom:10px;padding:10px;background:var(--bg);border-radius:8px;border:1px solid var(--line)"><div style="font-size:11px;font-weight:700;color:var(--blue);margin-bottom:8px">${compTitle}</div><div style="display:flex;flex-wrap:wrap;gap:8px;margin-bottom:10px">${cats}</div><details style="margin-top:4px"><summary style="font-size:11px;font-weight:700;color:var(--ink-soft);cursor:pointer;user-select:none">Singles por ritmo</summary><div style="margin-top:8px">${singlesHtml}</div></details></div>`;
  }).join('');
  const modal=document.createElement('div');
  modal.id='excelInscrEditModal';
  modal.style.cssText='position:fixed;inset:0;z-index:9999;background:rgba(0,0,0,.6);display:flex;align-items:center;justify-content:center;padding:16px';
  const safeLeadName=(firstRow['Nombre (leader)']||'').replace(/</g,'&lt;').replace(/"/g,'&quot;');
  const safeFoll=(firstRow['Follower (indicar nombre)']||'').replace(/</g,'&lt;').replace(/"/g,'&quot;');
  modal.innerHTML=`<div style="background:var(--card);border-radius:16px;padding:24px;max-width:580px;width:100%;max-height:92vh;overflow-y:auto;box-shadow:0 20px 60px rgba(0,0,0,.4)">
    <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:18px">
      <h3 style="margin:0;font-size:16px;font-weight:800">✎ Editar inscripción</h3>
      <button onclick="document.getElementById('excelInscrEditModal').remove()" style="background:none;border:none;font-size:22px;cursor:pointer;color:var(--ink-soft);line-height:1;padding:0 4px">×</button>
    </div>
    <div id="einscr_err" style="display:none;color:#a00;background:#fff0f0;border:1px solid #fcc;border-radius:8px;padding:8px 12px;margin-bottom:12px;font-size:13px"></div>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;${FLD}">
      <div><label style="${LBL}">Nombre Leader *</label><input id="einscr_lead" type="text" value="${safeLeadName}" style="${INP}"></div>
      <div><label style="${LBL}">DNI Leader</label><input id="einscr_leadDni" type="text" value="${(firstRow['DNI del leader']||'').replace(/"/g,'&quot;')}" style="${INP}"></div>
    </div>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;${FLD}">
      <div><label style="${LBL}">Follower</label><input id="einscr_foll" type="text" value="${safeFoll}" style="${INP}"></div>
      <div><label style="${LBL}">DNI Follower</label><input id="einscr_follDni" type="text" value="${(firstRow['DNI del follower']||'').replace(/"/g,'&quot;')}" style="${INP}"></div>
    </div>
    <div style="display:grid;grid-template-columns:1fr 1fr;gap:10px;${FLD}">
      <div><label style="${LBL}">Escuela</label><input id="einscr_esc" type="text" value="${(firstRow['Seleccione su escuela']||'').replace(/"/g,'&quot;')}" style="${INP}"></div>
      <div><label style="${LBL}">Grupo de edad</label>${ageSel}</div>
    </div>
    <div style="font-size:12px;font-weight:700;color:var(--ink-soft);text-transform:uppercase;letter-spacing:.05em;margin-bottom:10px;border-top:1px solid var(--line);padding-top:14px">Categorías por archivo</div>
    ${compRowsHtml}
    <div style="display:flex;gap:10px;margin-top:16px;border-top:1px solid var(--line);padding-top:16px">
      <button class="act solid" onclick="saveExcelInscrEdit('${leadId}')" style="flex:1;font-size:13px;padding:10px 0">✓ Guardar cambios</button>
      <button onclick="deleteExcelInscr('${leadId}','${safeLeadName.replace(/'/g,'&#39;')}')" style="border:1px solid #e3b8b0;background:var(--card);color:#a00;border-radius:10px;font-size:13px;padding:10px 14px;cursor:pointer">🗑 Eliminar</button>
    </div>
  </div>`;
  document.body.appendChild(modal);
}
function saveExcelInscrEdit(leadId){
  const get=id=>(document.getElementById(id)?.value||'').trim();
  const lead=get('einscr_lead');
  const showErr=msg=>{const e=document.getElementById('einscr_err');if(e){e.textContent=msg;e.style.display='block';}};
  if(!lead){showErr('El nombre del leader es obligatorio.');return;}
  const ld=get('einscr_leadDni'),fd=get('einscr_follDni');
  if(ld&&fd&&ld===fd){showErr('⚠ El DNI del Leader y del Follower no pueden ser iguales.');return;}
  const matches=_excelRowsForLead(leadId);
  const styles=[
    {id:'std',col:'Standard categoria'},{id:'lat',col:'Latin categoria'},
    {id:'sm',col:'Smooth categoria'},{id:'rh',col:'Rhythm categoria'},
    {id:'sl',col:'SocialLatino categoria'},{id:'sg',col:'SocialArgentino categoria'},{id:'sa',col:'SocialAmericano categoria'},
  ];
  const affectedComps=new Set();
  const SD_SAVE_GROUPS=[
    {g:'INT-ST',dances:DANCESETS['Standard']||[]},{g:'INT-LT',dances:DANCESETS['Latin']||[]},
    {g:'AM-SM',dances:DANCESETS['Smooth']||[]},{g:'AM-RH',dances:DANCESETS['Rhythm']||[]},
    {g:'SOC-LA',dances:DANCESETS['SocialLatino']||[]},{g:'SOC-AR',dances:DANCESETS['SocialArgentino']||[]},
    {g:'SOC-AM',dances:DANCESETS['SocialAmericano']||[]},
  ];
  matches.forEach((m,mi)=>{
    const row=COMPS[m.ci].rows[m.ri];
    row['Nombre (leader)']=lead;
    row['DNI del leader']=get('einscr_leadDni');
    row['Follower (indicar nombre)']=get('einscr_foll');
    row['DNI del follower']=get('einscr_follDni');
    row['Seleccione su escuela']=get('einscr_esc');
    row['Grupo de edad']=get('einscr_edad');
    styles.forEach(s=>{row[s.col]=get('einscr_'+mi+'_'+s.id);});
    // guardar singles por ritmo en la fila de singles (separada de la fila multidance)
    const newSingles={};
    SD_SAVE_GROUPS.forEach(({g,dances})=>{
      dances.forEach(d=>{
        const inp=document.getElementById('einscr_'+mi+'_sd_'+g+'_'+d.replace(/\s+/g,'_'));
        const qty=parseInt(inp?.value)||0;
        if(qty>0)newSingles['Ritmos ('+g+') ['+d+']']=qty;
      });
    });
    const hasNewSingles=Object.keys(newSingles).length>0;
    if(m.singlesRi>=0){
      // actualizar fila existente de singles
      const sRow=COMPS[m.ci].rows[m.singlesRi];
      // limpiar ritmos anteriores
      Object.keys(sRow).forEach(k=>{if(k.startsWith('Ritmos ('))sRow[k]=null;});
      if(hasNewSingles){Object.assign(sRow,newSingles);}
      else{COMPS[m.ci].rows.splice(m.singlesRi,1);}  // sin ritmos → eliminar fila
    } else if(hasNewSingles){
      // crear nueva fila de singles
      const sRow={'Nombre (leader)':lead,'Follower (indicar nombre)':get('einscr_foll'),'DNI del leader':get('einscr_leadDni'),'DNI del follower':get('einscr_follDni'),'Seleccione su escuela':get('einscr_esc'),'Elegir modalidad':'Single Dance'};
      Object.assign(sRow,newSingles);
      COMPS[m.ci].rows.push(sRow);
    }
    affectedComps.add(m.ci);
  });
  affectedComps.forEach(ci=>{
    try{COMPS[ci].model=buildModel(COMPS[ci].rows,COMPS[ci].ageMode==='AABD'?ageNormAABD:ageNorm);applyExclusions(COMPS[ci].model);if(ci===CUR)MODEL=COMPS[ci].model;}catch(e){}
  });
  document.getElementById('excelInscrEditModal')?.remove();
  render();
  scheduleAdminBackup();
}
function deleteExcelInscr(leadId,leadName){
  if(!confirm(`¿Eliminar todas las inscripciones de "${leadName}" del archivo Excel?\nEsta acción no se puede deshacer.`))return;
  const SKIP=new Set(['__inscripciones_web__','__inscripciones_web_aabd__','__manual_couples__']);
  const affectedComps=new Set();
  COMPS.forEach((comp,ci)=>{
    if(SKIP.has(comp.sheet))return;
    const before=comp.rows.length;
    comp.rows=comp.rows.filter(row=>idOf(row['Nombre (leader)']||'',row['DNI del leader']||'')!==leadId);
    if(comp.rows.length!==before)affectedComps.add(ci);
  });
  affectedComps.forEach(ci=>{
    try{COMPS[ci].model=buildModel(COMPS[ci].rows,COMPS[ci].ageMode==='AABD'?ageNormAABD:ageNorm);applyExclusions(COMPS[ci].model);if(ci===CUR)MODEL=COMPS[ci].model;}catch(e){}
  });
  document.getElementById('excelInscrEditModal')?.remove();
  render();
  scheduleAdminBackup();
}
// ===================== Solapa Pagos (admin) =====================
// Lista CADA inscripción enviada (tabla Supabase 'inscripciones', tal cual fue presentada por el
// formulario público) junto al monto que debe abonar — recalculado con el mismo motor de precios
// (regPriceBreakdown) que usa la calculadora en vivo del formulario, pero a partir de las filas
// canónicas YA GUARDADAS (regCountsFromRows), no del DOM. Es independiente del proyecto/competencia
// cargado: funciona aunque todavía no se haya importado nada.
let _PAGOS_CACHE=null,_PAGOS_LOADING=false;
async function loadPagosCache(force){
  if(_PAGOS_LOADING)return;
  if(_PAGOS_CACHE&&!force)return;
  _PAGOS_LOADING=true;
  try{
    await loadRegPricesIntoMemory();
    const {data,error}=await sb.from('inscripciones').select('id,created_at,tipo,resumen,rows,pago_estado,pago_monto').order('created_at',{ascending:true});
    if(error)throw new Error(error.message);
    _PAGOS_CACHE=data||[];
  }catch(e){
    _PAGOS_CACHE=[];
    console.error('No se pudieron cargar los pagos:',e.message);
  }
  _PAGOS_LOADING=false;
  render();
}
async function updatePago(id,patch){
  try{
    const {error}=await sb.from('inscripciones').update(patch).eq('id',id);
    if(error)throw new Error(error.message);
    const rec=(_PAGOS_CACHE||[]).find(r=>r.id===id);
    if(rec)Object.assign(rec,patch);
  }catch(e){
    alert('No se pudo guardar el estado de pago: '+e.message);
  }
  render();
}
function pagoTotalOf(rec){
  if(rec.tipo==='team')return null;
  if(rec.tipo==='jackjill'){
    return(rec.rows||[]).reduce((a,row)=>{
      const rol=(row['Rol']||'Leader');
      return a+(rol==='Follower'?REG_PRICE_BASE_JJ_FOLLOWER:REG_PRICE_BASE_JJ_LEADER);
    },0);
  }
  const {m,s,c}=regCountsFromRows(rec.rows);
  return regPriceBreakdown(m,s,c,rec.tipo==='solista').total;
}
async function pagoSetEstado(id,estado){
  const rec=(_PAGOS_CACHE||[]).find(r=>r.id===id);
  if(!rec)return;
  let monto=rec.pago_monto||0;
  if(estado==='pendiente')monto=0;
  else if(estado==='pagado'){const total=pagoTotalOf(rec);if(total!=null)monto=total;}
  await updatePago(id,{pago_estado:estado,pago_monto:monto});
}
async function pagoSetMonto(id,value){
  const monto=Math.max(0,parseFloat(value)||0);
  await updatePago(id,{pago_monto:monto});
}
let PAGOS_SORT={key:null,dir:1};
function pagoSort(k){
  if(PAGOS_SORT.key===k)PAGOS_SORT.dir*=-1;
  else{PAGOS_SORT.key=k;PAGOS_SORT.dir=1;}
  render();
}
function panePagos(q){
  const p=pane('pagos');
  if(APP_MODE!=='admin'){p.innerHTML='<p style="color:var(--ink-soft);padding:24px">Solo disponible para el admin.</p>';return p;}
  if(_PAGOS_CACHE===null){
    loadPagosCache();
    p.innerHTML='<p style="color:var(--ink-soft);padding:24px">⏳ Cargando inscripciones…</p>';
    return p;
  }
  const TIPO_LABEL={pareja:'Pareja',solista:'Solista',synchro:'Synchro Duo',team:'Equipo',singles:'Singles Dances',challenge:'Challenge',jackjill:'Jack & Jill'};
  const recs=_PAGOS_CACHE.map(r=>{
    if(r.tipo==='team')return Object.assign({},r,{m:0,s:0,c:0,items:[],total:null});
    if(r.tipo==='jackjill'){
      // precio por rol
      const rows=r.rows||[];
      const items=rows.map(row=>{
        const rol=(row['Rol']||'Leader');
        const nombre=row['Nombre']||row['Nombre (leader)']||r.resumen||'';
        const nivel=row['Nivel']||row['Grupo de edad']||'';
        const price=rol==='Follower'?REG_PRICE_BASE_JJ_FOLLOWER:REG_PRICE_BASE_JJ_LEADER;
        return{label:`${nombre}${nivel?' · '+nivel:''} (${rol})`,price};
      });
      const total=items.reduce((a,it)=>a+it.price,0);
      return Object.assign({},r,{m:0,s:0,c:0,items,total});
    }
    const {m,s,c}=regCountsFromRows(r.rows);
    const {items,total}=regPriceBreakdown(m,s,c,r.tipo==='solista');
    return Object.assign({},r,{m,s,c,items,total});
  });
  const filtered=q?recs.filter(r=>key(r.resumen||'').includes(q)||key(TIPO_LABEL[r.tipo]||r.tipo||'').includes(q)):recs;
  const PAGOS_SORT_VAL={
    fecha:r=>r.created_at||'',
    tipo:r=>TIPO_LABEL[r.tipo]||r.tipo||'',
    resumen:r=>r.resumen||'',
    email:r=>(r.rows&&r.rows[0]&&r.rows[0]['Email de contacto'])||'',
    escuela:r=>(r.rows&&r.rows[0]&&r.rows[0]['Seleccione su escuela'])||'',
    total:r=>r.total==null?-1:r.total,
    estado:r=>r.pago_estado||'pendiente',
    resta:r=>r.total==null?-1:Math.max(r.total-(r.pago_monto||0),0)
  };
  if(PAGOS_SORT.key&&PAGOS_SORT_VAL[PAGOS_SORT.key]){
    const fv=PAGOS_SORT_VAL[PAGOS_SORT.key];
    filtered.sort((a,b)=>{
      const va=fv(a),vb=fv(b);
      if(typeof va==='number'&&typeof vb==='number')return (va-vb)*PAGOS_SORT.dir;
      return String(va).localeCompare(String(vb))*PAGOS_SORT.dir;
    });
  }
  const grand=filtered.reduce((a,r)=>a+(r.total||0),0);
  const recaudado=filtered.reduce((a,r)=>a+(r.pago_monto||0),0);
  const pendienteTotal=filtered.reduce((a,r)=>a+(r.total!=null?Math.max(r.total-(r.pago_monto||0),0):0),0);
  let html=`<div style="padding:10px 14px;display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap">
    <button class="act" onclick="loadPagosCache(true)" style="font-size:12px">🔄 Actualizar</button>
    <div style="font-size:13px;display:flex;gap:14px;flex-wrap:wrap">
      <span style="font-weight:800;color:var(--wine)">Total a recaudar: ${regPriceFmt(grand)}</span>
      <span style="font-weight:700;color:#2e8b57">Cobrado: ${regPriceFmt(recaudado)}</span>
      <span style="font-weight:700;color:#b8860b">Pendiente: ${regPriceFmt(pendienteTotal)}</span>
      <span style="color:var(--ink-soft);font-size:12px">(${filtered.length} inscripción${filtered.length===1?'':'es'})</span>
    </div>
  </div>`;
  if(!filtered.length){
    html+='<p style="color:var(--ink-soft);padding:24px">Sin inscripciones.</p>';
    p.innerHTML=html;
    return p;
  }
  const HDRS=[{label:'Fecha',key:'fecha'},{label:'Tipo',key:'tipo'},{label:'Inscripción',key:'resumen'},{label:'Email',key:'email'},{label:'Escuela',key:'escuela'},{label:'Detalle de la inscripción',key:null},{label:'Desglose del monto',key:null},{label:'Total a pagar',key:'total'},{label:'Pago',key:'estado'},{label:'Resta',key:'resta'},{label:'Acciones',key:null}];
  html+=`<div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse;font-size:13px">
<thead><tr>${HDRS.map(h=>{
    const sortable=!!h.key;
    const arrow=sortable&&PAGOS_SORT.key===h.key?(PAGOS_SORT.dir===1?' ▲':' ▼'):'';
    return `<th${sortable?` onclick="pagoSort('${h.key}')"`:''} style="background:var(--blue);color:#fff;padding:6px 8px;text-align:left;white-space:nowrap;position:sticky;top:0${sortable?';cursor:pointer;user-select:none':''}">${h.label}${arrow}</th>`;
  }).join('')}</tr></thead><tbody>`;
  filtered.forEach((r,ri)=>{
    const bg=ri%2===0?'var(--bg)':'var(--card)';
    const fecha=r.created_at?new Date(r.created_at).toLocaleString('es-AR',{day:'2-digit',month:'2-digit',year:'2-digit',hour:'2-digit',minute:'2-digit'}):'';
    const resumenShort=(r.resumen||'').split(' — ')[0];
    const emailContacto=(r.rows&&r.rows[0]&&r.rows[0]['Email de contacto'])||'';
    const escuelaContacto=(r.rows&&r.rows[0]&&r.rows[0]['Seleccione su escuela'])||'';
    const detalleHTML=regRowsSummaryHTML(r.rows);
    const desgloseHTML=r.tipo==='team'?'<span style="color:var(--ink-soft)">— (no incluido en este cálculo)</span>':(r.items.length?r.items.map(it=>`<div>${it.label} — ${regPriceFmt(it.price)}</div>`).join(''):'<span style="color:var(--ink-soft)">—</span>');
    const totalCell=r.tipo==='team'?'<span style="color:var(--ink-soft)">—</span>':regPriceFmt(r.total);
    const estado=r.pago_estado||'pendiente';
    const monto=r.pago_monto||0;
    const showMontoInput=estado==='parcial'||r.total==null;
    const pagoHTML=`<select onchange="pagoSetEstado('${r.id}',this.value)" style="font-size:12px;display:block;margin-bottom:4px">
        <option value="pendiente"${estado==='pendiente'?' selected':''}>Pendiente</option>
        <option value="parcial"${estado==='parcial'?' selected':''}>Parcial</option>
        <option value="pagado"${estado==='pagado'?' selected':''}>Pagado</option>
      </select>${showMontoInput?`<input type="number" step="0.01" min="0" value="${monto}" onchange="pagoSetMonto('${r.id}',this.value)" placeholder="Monto abonado" style="width:100px;font-size:12px">`:(estado==='pagado'?`<span style="color:#2e8b57;font-size:12px">✓ ${regPriceFmt(monto)}</span>`:'<span style="color:var(--ink-soft);font-size:12px">—</span>')}`;
    const restaHTML=r.total==null?'<span style="color:var(--ink-soft)">—</span>':(estado==='pagado'?'<span style="color:#2e8b57">$0</span>':`<span style="color:#b8860b;font-weight:700">${regPriceFmt(Math.max(r.total-monto,0))}</span>`);
    html+=`<tr style="background:${bg}">
      <td style="padding:6px 8px;font-size:11px;color:var(--ink-soft);white-space:nowrap;vertical-align:top">${fecha}</td>
      <td style="padding:6px 8px;white-space:nowrap;vertical-align:top">${TIPO_LABEL[r.tipo]||r.tipo||''}</td>
      <td style="padding:6px 8px;font-weight:700;vertical-align:top">${resumenShort}</td>
      <td style="padding:6px 8px;font-size:12px;vertical-align:top;white-space:nowrap">${emailContacto?`<a href="mailto:${emailContacto}" style="color:var(--blue)">${emailContacto}</a>`:'<span style="color:var(--ink-soft)">—</span>'}</td>
      <td style="padding:6px 8px;font-size:12px;vertical-align:top;white-space:nowrap">${escuelaContacto||'<span style="color:var(--ink-soft)">—</span>'}</td>
      <td style="padding:6px 8px;font-size:12px;color:var(--ink-soft);vertical-align:top">${detalleHTML}</td>
      <td style="padding:6px 8px;font-size:12px;vertical-align:top">${desgloseHTML}</td>
      <td style="padding:6px 8px;font-weight:800;color:var(--wine);white-space:nowrap;vertical-align:top">${totalCell}</td>
      <td style="padding:6px 8px;vertical-align:top;white-space:nowrap">${pagoHTML}</td>
      <td style="padding:6px 8px;vertical-align:top;white-space:nowrap">${restaHTML}</td>
      <td style="padding:6px 8px;vertical-align:top;white-space:nowrap">
        <button onclick="copyRegEditLink('${r.id}')" title="Copiar link de edición para mandarle al bailarín" style="border:1px solid var(--line);background:var(--card);color:var(--ink-soft);border-radius:6px;padding:4px 8px;font-size:11px;cursor:pointer;margin-right:4px">🔗</button>
        <button onclick="editInscripcionAdmin('${r.id}')" title="Editar" style="border:1px solid var(--line);background:var(--card);color:var(--wine);border-radius:6px;padding:4px 8px;font-size:11px;cursor:pointer;margin-right:4px">✎</button>
        <button onclick="deleteInscripcionAdmin('${r.id}')" title="Borrar" style="border:1px solid #e3b8b0;background:var(--card);color:#a00;border-radius:6px;padding:4px 8px;font-size:11px;cursor:pointer">✕</button>
      </td>
    </tr>`;
  });
  html+='</tbody></table></div>';
  p.innerHTML=html;
  return p;
}
function exportXlsx(){
  if(!MODEL&&CUR!=='all')return;
  if(CUR==='all'&&!COMPS.length)return;
  const maxX=Math.max(2,parseInt(document.getElementById('maxper').value)||6);
  const dStart=parseInt(document.getElementById('dStart').value)||1;
  const sStartRaw=document.getElementById('sStart').value;const sStart=sStartRaw?parseInt(sStartRaw):0;
  const merge=document.getElementById('mrg').checked;
  const shareMode=document.getElementById('shareMode').value;
  const _sp2=document.getElementById('showPrueba').checked;const _dp2=_sp2?(parseFloat(document.getElementById('durPrueba').value)||5):0;
  const timing={start:hm2min(document.getElementById('hStart').value),single:parseFloat(document.getElementById('dSingle').value)||0,ronda:parseFloat(document.getElementById('dRonda').value)||0,brk:parseFloat(document.getElementById('dBreak').value)||0,prueba:_dp2};
  rebuildDorsals(dStart,sStart);applyDorsalOverrides();
  // construir schedule igual que render()
  let SCH;
  if(CUR==='all'){
    SCH=buildFullSchedule(maxX,merge,timing,shareMode);
  } else {
    let heatOffset=0;
    for(let i=0;i<CUR;i++){const s=buildSchedule(COMPS[i].model,maxX,merge,timing,shareMode,heatOffset);heatOffset=s.total;}
    const singleBlockOverrides=Array.from({length:BLOCK_COUNT},(_x,bi)=>blkTimeGet(String(bi+1),'b'+(bi+1)));
    SCH=buildSchedule(MODEL,maxX,merge,timing,shareMode,heatOffset,singleBlockOverrides);
    jjAppendScheduleEntries(SCH);
  }
  applyHeatReorder(SCH);
  const wb=XLSX.utils.book_new();

  // ── Paleta Argentina ──────────────────────────────────────────────
  const C={
    celeste:'75AADB', celesLight:'D6E8F7', celesVeryLight:'EEF6FC',
    gold:'E0A40C',    goldLight:'F2E3B4',  goldVeryLight:'FBF6EC',
    white:'FFFFFF',   ink:'1D2A33',        inkSoft:'566976',
    grey:'F3F6F9',    greyLine:'D3E4F1',   red:'C0392B'
  };

  // helper: crea celda con estilo completo
  const cs=(v,{bold=false,italic=false,color=C.ink,bg=C.white,sz=11,align='left',border=false,wrap=false}={})=>{
    const cell={v,t:typeof v==='number'?'n':'s'};
    cell.s={font:{name:'Calibri',sz,bold,italic,color:{rgb:color}},fill:{fgColor:{rgb:bg}},alignment:{horizontal:align,vertical:'center',wrapText:wrap}};
    if(border)cell.s.border={top:{style:'thin',color:{rgb:C.greyLine}},bottom:{style:'thin',color:{rgb:C.greyLine}},left:{style:'thin',color:{rgb:C.greyLine}},right:{style:'thin',color:{rgb:C.greyLine}}};
    return cell;
  };

  // helper: fila de encabezado celeste
  const hdrRow=(cols)=>cols.map(v=>cs(v,{bold:true,bg:C.celeste,color:C.white,sz:10,border:true,align:'center'}));
  // helper: fila de título de sección (bloque/heat)
  const titleRow=(v,ncols,bg=C.celesLight)=>[cs(v,{bold:true,bg,color:C.ink,sz:11,border:true}),...Array(ncols-1).fill(cs('',{bg,border:true}))];
  // helper: fila zebra
  const dataRow=(cols,odd=false,opts={})=>cols.map((v,i)=>cs(v,{bg:odd?C.grey:C.white,border:true,...(opts[i]||{})}));
  // helper: fila de sub-separador (break, tanda)
  const sepRow=(v,ncols)=>[cs(v,{bold:true,italic:true,bg:C.goldVeryLight,color:C.gold,sz:10}),...Array(ncols-1).fill(cs('',{bg:C.goldVeryLight}))];

  // helper: agrega hoja con datos ya formateados como array de filas de celdas
  // merges: array de {s:{r,c},e:{r,c}} para combinar celdas
  const addFormatted=(name,rows,cols,merges=[])=>{
    const ws={};let maxR=0,maxC=0;
    rows.forEach((row,r)=>{
      row.forEach((cell,c)=>{
        const ref=XLSX.utils.encode_cell({r,c});
        ws[ref]=cell;maxC=Math.max(maxC,c);
      });
      maxR=r;
    });
    ws['!ref']=XLSX.utils.encode_range({s:{r:0,c:0},e:{r:maxR,c:maxC}});
    if(cols)ws['!cols']=cols;
    if(merges.length)ws['!merges']=merges;
    XLSX.utils.book_append_sheet(wb,ws,name.slice(0,31));
  };

  // ── Hoja INFO ────────────────────────────────────────────────────
  {
    const rows=[];
    rows.push([cs('RC · BAILE DEPORTIVO',{bold:true,sz:18,color:C.celeste,bg:C.white}),cs('',{bg:C.white}),cs('',{bg:C.white})]);
    rows.push([cs('',{bg:C.goldLight}),cs('',{bg:C.goldLight}),cs('',{bg:C.goldLight})]);
    if(CUR==='all'){
      rows.push([cs('Evento completo',{bold:true,sz:13,color:C.ink}),cs(''),cs('')]);
      rows.push([cs(''),cs(''),cs('')]);
      rows.push(hdrRow(['Archivo','Título','Fecha']));
      COMPS.forEach((c,i)=>rows.push(dataRow([c.sheet,c.title||c.sheet,fmtDate(c.date)||''],i%2===0)));
    } else {
      const COMP=COMPS[CUR]||{title:'',date:''};
      rows.push([cs('Competencia',{bold:true,color:C.inkSoft,sz:10}),cs(COMP.title||'',{bold:true,sz:13,color:C.ink}),cs('')]);
      rows.push([cs('Fecha',{bold:true,color:C.inkSoft,sz:10}),cs(fmtDate(COMP.date)||'—',{sz:11}),cs('')]);
    }
    rows.push([cs(''),cs(''),cs('')]);
    rows.push([cs('Generado',{bold:true,color:C.inkSoft,sz:10}),cs(new Date().toLocaleString('es-AR'),{sz:10,italic:true,color:C.inkSoft}),cs('')]);
    addFormatted('Info',rows,[{wch:18},{wch:34},{wch:16}]);
  }

  // ── Hoja DORSALES ────────────────────────────────────────────────
  {
    const xModels=CUR==='all'?COMPS.map(c=>c.model):(MODEL?[MODEL]:[]);
    const folls={};
    xModels.forEach(M=>M.events.forEach(e=>e.couples.forEach(c=>{if(!c.leadId)return;const fn=c.foll||'';if(!folls[c.leadId])folls[c.leadId]=[];if(fn&&!folls[c.leadId].some(x=>key(x)===key(fn)))folls[c.leadId].push(fn);})));
    const seen=new Set(),dr=[];
    xModels.forEach(M=>M.order.forEach(id=>{if(seen.has(id))return;seen.add(id);const pe=M.persons[id];if(pe.dorsal==='')return;const fl=folls[id]||[];if(!fl.length)dr.push([pe.dorsal,pe.name,'(solo)']);else fl.forEach(f=>dr.push([pe.dorsal,pe.name,f]));}));
    dr.sort((a,b)=>(a[0]-b[0])||(key(a[1])<key(b[1])?-1:1));
    const rows=[hdrRow(['Dorsal','Leader / Solista','Follower'])];
    let prev='',odd=false;
    dr.forEach(r=>{if(r[1]!==prev){prev=r[1];odd=!odd;}
      rows.push([cs(r[0],{bold:true,bg:odd?C.celesVeryLight:C.white,color:C.celeste,align:'center',border:true,sz:12}),cs(r[1],{bold:true,bg:odd?C.celesVeryLight:C.white,border:true}),cs(r[2]==='(solo)'?'— solo —':r[2],{italic:r[2]==='(solo)',color:r[2]==='(solo)'?C.inkSoft:C.ink,bg:odd?C.celesVeryLight:C.white,border:true})]);
    });
    addFormatted('Dorsales',rows,[{wch:9},{wch:32},{wch:32}]);
  }

  // ── Hoja CRONOGRAMA ──────────────────────────────────────────────
  {
    const rows=[hdrRow(['Bloque','Hora','Heat','Prueba','Parejas'])];
    const merges=[];
    let lastBlk=null,blkOdd=false;
    SCH.cron.forEach(c=>{
      if(c.block!==lastBlk){
        if(lastBlk!==null){rows.push(sepRow('— Break entre bloques —',5));merges.push({s:{r:rows.length-1,c:0},e:{r:rows.length-1,c:4}});}
        rows.push(titleRow('⬛ '+c.block,5,C.celesLight));
        merges.push({s:{r:rows.length-1,c:0},e:{r:rows.length-1,c:4}});
        lastBlk=c.block;blkOdd=false;
      }
      blkOdd=!blkOdd;
      const hora=(c.isSingle||c.isPrueba)?(c.time!=null?min2hm(c.time)+'–'+min2hm(c.timeEnd):''):(c.time!=null?min2hm(c.time):'');
      const bg=c.isSingle?C.goldVeryLight:c.isPrueba?C.celesVeryLight:(blkOdd?C.grey:C.white);
      const xlsxName=c.isPrueba?'Prueba de pista':c.isSingle?('🎵 '+c.name):c.name;
      rows.push([cs(c.block,{bg,color:C.inkSoft,sz:9,border:true}),cs(hora,{bg,bold:true,align:'center',border:true}),cs(c.range,{bg,bold:true,align:'center',color:C.celeste,border:true}),cs(xlsxName,{bg,bold:c.isSingle||c.isPrueba,color:c.isPrueba?C.celeste:C.ink,border:true}),cs(c.n||'',{bg,align:'center',border:true})]);
    });
    addFormatted('Cronograma',rows,[{wch:22},{wch:14},{wch:12},{wch:38},{wch:9}],merges);
  }

  // ── Hoja ORDEN GENERAL ───────────────────────────────────────────
  {
    // Una sola columna "Ritmos" al final — no más N columnas por categoría
    const ritmosDe=dancesForCategory;
    const NCOLS=6; // Hora | Heat | Dorsal | Pareja | Cat·Edad | Ritmos
    const rows=[hdrRow(['Hora','Heat','Dorsal','Pareja / Detalle','Cat · Edad','Ritmos'])];
    const merges=[];
    // helper: texto de ritmos compacto para una categoría
    const rtmTxt=(style,cat,kind,age)=>{const rr=ritmosDe(style,kind==='OPEN'?'':cat);return rr.map((d,i)=>(i+1)+'. '+d).join('  ');};
    SCH.blocks.forEach((B,bi)=>{
      if(bi>0){const sr=sepRow('— Break entre bloques —',NCOLS);rows.push(sr);merges.push({s:{r:rows.length-1,c:0},e:{r:rows.length-1,c:NCOLS-1}});}
      rows.push(titleRow('Bloque '+(B.globalIdx||B.id)+' · '+B.label,NCOLS,C.celesLight));
      merges.push({s:{r:rows.length-1,c:0},e:{r:rows.length-1,c:NCOLS-1}});
      let odd=false;
      B.singles.forEach(s=>{
        odd=!odd;
        const bg=odd?C.goldVeryLight:C.white;
        const rlClean=s.rl.replace(/\([^)]+\) /,'').replace(/\[|\]/g,'');
        s.couples.forEach(c=>rows.push([cs(min2hm(s.time),{bg,align:'center',border:true}),cs('Heat '+s.heat,{bg,bold:true,color:C.celeste,align:'center',border:true}),cs(dorsalOf(c),{bg,bold:true,align:'center',border:true}),cs(c.lead+(c.foll?' – '+c.foll:''),{bg,border:true}),cs(rlClean,{bg,sz:9,color:C.inkSoft,border:true}),cs('',{bg,border:true})]));
        rows.push([...Array(NCOLS).fill(cs('',{bg:C.white}))]);
      });
      B.comps.forEach(e=>{
        rows.push(titleRow('  HEAT '+e.heat+' · '+e.name+(e.time!=null?' · '+min2hm(e.time):''),NCOLS,C.goldLight));
        merges.push({s:{r:rows.length-1,c:0},e:{r:rows.length-1,c:NCOLS-1}});
        odd=false;
        if(e.tandas&&e.tandas.length>1){
          // Multi-tanda
          const categories=e.shared?(e.buckets||[]):[{cat:e.cat,age:e.age,kind:e.kind}];
          const rtxtAll=categories.map(b=>'('+(b.kind==='OPEN'?'Open':b.cat)+' '+ageAbbr(b.age||'')+') '+rtmTxt(e.style,b.cat,b.kind,b.age)).join('  |  ');
          rows.push([cs('  Ritmos: '+rtxtAll,{bg:C.goldVeryLight,sz:9,italic:true,color:C.inkSoft,border:true}),...Array(NCOLS-1).fill(cs('',{bg:C.goldVeryLight,border:true}))]);
          merges.push({s:{r:rows.length-1,c:0},e:{r:rows.length-1,c:NCOLS-1}});
          e.tandas.forEach((tnd,ti)=>{
            const sr2=sepRow('  Tanda '+(ti+1),NCOLS);rows.push(sr2);
            merges.push({s:{r:rows.length-1,c:0},e:{r:rows.length-1,c:NCOLS-1}});
            tnd.forEach(c=>{odd=!odd;const bg=odd?C.grey:C.white;
              const cRtm=rtmTxt(e.style,c.cat,e.kind,c.age);
              rows.push([cs('',{bg,border:true}),cs(e.heat,{bg,align:'center',border:true}),cs(dorsalOf(c),{bold:true,bg,align:'center',border:true}),cs(c.lead+(c.foll?' – '+c.foll:''),{bg,border:true}),cs((c.cat||'')+' '+ageAbbr(c.age),{bg,sz:9,color:C.inkSoft,border:true}),cs(cRtm,{bg,sz:9,color:C.inkSoft,border:true,wrap:true})]);
            });
          });
        } else if(e.shared&&e.buckets&&e.buckets.length>0){
          // Pista compartida: agrupar por bucket ordenado por catRank
          const sortedBkts=[...e.buckets].sort((a,b)=>catRank(a.cat)-catRank(b.cat));
          sortedBkts.forEach(bkt=>{
            const bktRhythms=ritmosDe(e.style,bkt.kind==='OPEN'?'':bkt.cat);
            const isAlone=bkt.couples.length<2;
            const bktCatLabel=(bkt.kind==='OPEN'?'Open':bkt.cat)+' '+ageRegLabel(bkt.age);
            const bktStatus=isAlone?' · Contra el puesto':' · compiten entre sí ('+bkt.couples.length+' parejas)';
            const bktRtmTxt=bktRhythms.map((d,i)=>(i+1)+'. '+d).join('  ');
            const subBg=isAlone?C.goldVeryLight:C.celesVeryLight;
            const subColor=isAlone?C.gold:C.celeste;
            // Sub-header con ritmos en la última columna
            rows.push([cs('  '+bktCatLabel+bktStatus,{bold:true,bg:subBg,color:subColor,sz:9,italic:isAlone,border:true}),...Array(NCOLS-2).fill(cs('',{bg:subBg,border:true})),cs(bktRtmTxt,{bg:subBg,color:subColor,sz:9,italic:true,border:true})]);
            merges.push({s:{r:rows.length-1,c:0},e:{r:rows.length-1,c:NCOLS-2}});
            bkt.couples.forEach(c=>{
              odd=!odd;const bg=odd?C.grey:C.white;
              rows.push([
                cs(min2hm(e.time),{bg,align:'center',border:true}),
                cs(e.heat,{bg,align:'center',color:C.celeste,bold:true,border:true}),
                cs(dorsalOf(c),{bold:true,bg,align:'center',border:true}),
                cs(c.lead+(c.foll?' – '+c.foll:''),{bg,border:true}),
                cs((bkt.kind==='OPEN'?'Open':c.cat)+' · '+ageAbbr(c.age),{bg,sz:9,color:C.inkSoft,border:true}),
                cs('',{bg,border:true})
              ]);
            });
          });
        } else {
          // Heat simple: ordenar por catRank
          const sortedCouples=[...e.couples].sort((a,b)=>catRank(a.cat)-catRank(b.cat));
          const cRtmTxt=c=>rtmTxt(e.style,c.cat,e.kind,c.age);
          // Una fila de ritmos al principio (igual para todos si misma categoría)
          const allRtm=ritmosDe(e.style,e.kind==='OPEN'?'':e.cat);
          const rtmHeader=allRtm.map((d,i)=>(i+1)+'. '+d).join('  ');
          if(rtmHeader){rows.push([cs('  Ritmos: '+rtmHeader,{bg:C.goldVeryLight,sz:9,italic:true,color:C.inkSoft,border:true}),...Array(NCOLS-1).fill(cs('',{bg:C.goldVeryLight,border:true}))]);merges.push({s:{r:rows.length-1,c:0},e:{r:rows.length-1,c:NCOLS-1}});}
          sortedCouples.forEach(c=>{
            odd=!odd;const bg=odd?C.grey:C.white;
            rows.push([
              cs(min2hm(e.time),{bg,align:'center',border:true}),
              cs(e.heat,{bg,align:'center',color:C.celeste,bold:true,border:true}),
              cs(dorsalOf(c),{bold:true,bg,align:'center',border:true}),
              cs(c.lead+(c.foll?' – '+c.foll:''),{bg,border:true}),
              cs((e.kind==='OPEN'?'Open':c.cat)+' · '+ageAbbr(c.age),{bg,sz:9,color:C.inkSoft,border:true}),
              cs('',{bg,border:true})
            ]);
          });
        }
        rows.push([...Array(NCOLS).fill(cs('',{bg:C.white}))]);
      });
    });
    addFormatted('ORDEN GENERAL',rows,[{wch:11},{wch:10},{wch:9},{wch:38},{wch:14},{wch:40}],merges);
  }

  // ── Hojas SINGLES ────────────────────────────────────────────────
  SCH.blocks.forEach(B=>{
    if(!B.singles.length)return;
    const rows=[hdrRow(['Hora','Heat','Dorsal','Pareja','Ritmo'])];
    let odd=false,lastH=-1;
    B.singles.forEach(s=>{
      if(s.heat!==lastH){lastH=s.heat;odd=!odd;rows.push(titleRow('Heat '+s.heat+' · '+s.rl.replace(/\([^)]+\) /,'').replace(/\[|\]/g,''),5,odd?C.goldLight:C.goldVeryLight));}
      s.couples.forEach(c=>rows.push([cs(min2hm(s.time),{bg:C.white,align:'center',border:true}),cs(s.heat,{bg:C.white,align:'center',color:C.celeste,bold:true,border:true}),cs(dorsalOf(c),{bold:true,align:'center',border:true}),cs(c.lead+(c.foll?' – '+c.foll:''),{border:true}),cs(s.rl.replace(/\([^)]+\) /,'').replace(/\[|\]/g,''),{sz:9,color:C.inkSoft,border:true})]));
    });
    const sheetName=CUR==='all'?('Singles B'+(B.globalIdx||B.id)).slice(0,31):('Singles '+(B.id===1?'SM-ST':'RH-LT'));
    addFormatted(sheetName,rows,[{wch:11},{wch:8},{wch:9},{wch:36},{wch:22}]);
  });

  // ── Hoja COMPETENCIAS ────────────────────────────────────────────
  {
    const NCOLS_C=9;
    const rows=[hdrRow(['Heat','Prueba','Tipo','Cat.','Edad','Compite contra','Dorsal','Pareja','Escuela'])];
    let lastH=-1,hOdd=false;
    const coupleRow=(e,c,r,odd)=>{const bg=odd?C.grey:C.white;return[cs(e.heat,{bg,align:'center',color:C.celeste,bold:true,border:true}),cs(e.name,{bg,sz:9,border:true}),cs(e.kind==='OPEN'?'Open':'L/M',{bg,align:'center',border:true}),cs(e.kind==='OPEN'?'Open':(c.cat||''),{bg,align:'center',bold:true,border:true}),cs(ageRegLabel(c.age),{bg,align:'center',sz:9,border:true}),cs(r===1?'Contra el puesto':(e.abmerge?'A+B '+ageRegLabel(c.age):'su cat.+edad'),{bg,italic:r===1,color:r===1?C.gold:C.ink,border:true}),cs(dorsalOf(c),{bg,bold:true,align:'center',color:C.celeste,border:true}),cs(c.lead+(c.foll?' – '+c.foll:''),{bg,bold:true,border:true}),cs(c.esc||'',{bg,sz:9,color:C.inkSoft,border:true})];};
    SCH.blocks.forEach(B=>B.comps.forEach(e=>{
      if(e.heat!==lastH){lastH=e.heat;hOdd=!hOdd;rows.push(titleRow('Heat '+e.heat+' · '+e.name,NCOLS_C,hOdd?C.celesLight:C.celesVeryLight));}
      let odd=false;
      if(e.shared&&e.buckets&&e.buckets.length>0){
        // Agrupar por bucket (quienes compiten entre sí), ordenados por catRank
        const sortedBkts=[...e.buckets].sort((a,b)=>catRank(a.cat)-catRank(b.cat));
        sortedBkts.forEach(bkt=>{
          const r=bkt.couples.length;
          const isAlone=r<2;
          const bktLabel=(bkt.kind==='OPEN'?'Open':bkt.cat)+' · '+ageRegLabel(bkt.age)+(isAlone?' — Contra el puesto':' — compiten entre sí ('+r+')');
          const subBg=isAlone?C.goldVeryLight:C.celesVeryLight;
          const subColor=isAlone?C.gold:C.celeste;
          rows.push([cs('  '+bktLabel,{bold:true,italic:isAlone,bg:subBg,color:subColor,sz:9,border:true}),...Array(NCOLS_C-1).fill(cs('',{bg:subBg,border:true}))]);
          bkt.couples.forEach(c=>{odd=!odd;rows.push(coupleRow(e,c,r,odd));});
        });
      } else {
        e.couples.forEach(c=>{odd=!odd;const r=e.couples.length;rows.push(coupleRow(e,c,r,odd));});
      }
      rows.push([...Array(NCOLS_C).fill(cs('',{bg:C.white}))]);
    }));
    addFormatted('Competencias',rows,[{wch:6},{wch:30},{wch:6},{wch:7},{wch:10},{wch:16},{wch:8},{wch:34},{wch:24}]);
  }

  // ── Hojas POR HEAT (solo Contra el puesto — parejas que compiten entre sí NO generan planilla) ──
  {const cp=collectCP(SCH).map(x=>Object.assign({},x,{cpMode:true}));
   const J=judgeNames();
   const byHeat=new Map();
   cp.forEach(x=>{if(!byHeat.has(x.heat))byHeat.set(x.heat,[]);byHeat.get(x.heat).push(x);});
   [...byHeat.keys()].sort((a,b)=>a-b).forEach(heatNum=>{
     const items=byHeat.get(heatNum);
     const nj=J.length;
     const rows=[];
     items.forEach((x,i)=>{
       const dz=(x.dances||[]).map(dnClean);
       rows.push([cs('HEAT '+x.heat,{bold:true,sz:13,bg:C.celeste,color:C.white,border:true}),cs(x.style.toUpperCase(),{bold:true,sz:11,bg:C.celeste,color:C.white,border:true}),...Array(nj-1).fill(cs('',{bg:C.celeste,border:true})),cs((i+1)+'/'+items.length,{bold:true,sz:12,bg:C.gold,color:C.white,align:'center',border:true})]);
       rows.push([cs(x.cat+' · '+ageRegLabel(x.age),{bold:true,bg:C.celesLight,border:true}),cs('Dorsal: '+dorsalOf(x.couple),{bg:C.celesLight,border:true}),cs(x.couple.lead+(x.couple.foll?' – '+x.couple.foll:''),{bold:true,bg:C.celesLight,border:true}),...Array(Math.max(nj-2,0)).fill(cs('',{bg:C.celesLight,border:true})),cs(x.cpMode?'Contra el puesto':'',{italic:true,color:C.gold,bg:C.celesLight,border:true})]);
       rows.push([cs('Ritmo',{bold:true,bg:C.goldLight,border:true,align:'center'}),...J.map((n,k)=>cs(n||'Juez '+(k+1),{bold:true,bg:C.goldLight,align:'center',border:true})),cs('Pos.',{bold:true,bg:C.goldLight,align:'center',border:true})]);
       dz.forEach((d,di)=>{const odd=di%2===0;rows.push([cs((di+1)+'- '+d,{bg:odd?C.grey:C.white,border:true}),...J.map(()=>cs('',{bg:odd?C.grey:C.white,border:true})),cs('',{bg:odd?C.grey:C.white,border:true})]);});
       rows.push([...Array(nj+2).fill(cs('',{bg:C.white}))]);
     });
     addFormatted(('Heat '+heatNum),rows,[{wch:24},...J.map(()=>({wch:13})),{wch:8}]);
   });}

  // ── Hoja INSCRIPCIONES ──────────────────────────────────────────
  {
    const xComps=CUR==='all'?COMPS:(MODEL?[COMPS[CUR]||{model:MODEL,title:'',sheet:''}]:[]);
    const insMap=buildInsMapData(xComps);
    const rows=[hdrRow(['Dorsal','Nombre','Follower','Escuela','Competencia','Tipo','Disciplina','Cat.','Edad','Ritmos / Baile'])];
    Object.values(insMap)
      .sort((a,b)=>(a.dorsal-b.dorsal)||(key(a.lead)<key(b.lead)?-1:1)||(key(a.foll)<key(b.foll)?-1:1))
      .forEach((rec,ri)=>{
        const bg=ri%2===0?C.celesVeryLight:C.white;
        rec.items.forEach((item,ii)=>{
          const isFirst=ii===0;
          let ritmosCell=item.tipo==='Single Dance'
            ?(item.count>1?item.detalle+' x'+item.count:item.detalle)
            :(item.ritmos||'');
          if(item.tipo==='Single Dance'&&item.contested)ritmosCell+=' · '+item.contested;
          rows.push([
            cs(isFirst?rec.dorsal:'',{bold:true,bg,color:C.celeste,align:'center',border:true,sz:12}),
            cs(isFirst?rec.lead:'',{bold:isFirst,bg,border:true}),
            cs(isFirst?(rec.foll||'—'):'',{bg,color:rec.foll?C.ink:C.inkSoft,italic:!rec.foll,border:true}),
            cs(isFirst?(rec.esc||''):'',{bg,sz:9,color:C.inkSoft,border:true}),
            cs(item.comp||'',{bg,sz:9,color:C.inkSoft,border:true}),
            cs(item.tipo,{bg,border:true,color:item.tipo==='Single Dance'?C.gold:(item.tipo==='Open'||item.tipo==='Synchro Duo Open')?C.celeste:C.ink,bold:(item.tipo==='Open'||item.tipo==='Synchro Duo Open')}),
            cs(item.detalle,{bg,border:true}),
            cs(item.cat||'—',{bg,align:'center',border:true}),
            cs(ageRegLabel(item.age)||'—',{bg,sz:9,border:true}),
            cs(ritmosCell,{bg,sz:9,color:C.inkSoft,border:true,wrap:true}),
          ]);
        });
        if(!rec.items.length){
          rows.push([cs(rec.dorsal,{bold:true,bg,color:C.celeste,align:'center',border:true}),cs(rec.lead,{bg,border:true}),cs(rec.foll||'—',{bg,border:true}),cs(rec.esc||'',{bg,border:true}),cs('',{bg,border:true}),cs('',{bg,border:true}),cs('',{bg,border:true}),cs('',{bg,border:true}),cs('',{bg,border:true}),cs('',{bg,border:true})]);
        }
        rows.push([...Array(10).fill(cs('',{bg:C.white}))]);
      });
    addFormatted('Inscripciones',rows,[{wch:8},{wch:26},{wch:26},{wch:22},{wch:20},{wch:15},{wch:18},{wch:7},{wch:12},{wch:32}]);
  }

  const fn=CUR==='all'
    ?('evento-completo '+new Date().toLocaleDateString('es-AR').replace(/\//g,'-')+'.xlsx')
    :(((COMPS[CUR]?.title||'armado').replace(/[^\w\sáéíóúñ-]/gi,'').trim()||'armado')+(COMPS[CUR]?.date?' '+COMPS[CUR].date:'')+'.xlsx');
  XLSX.writeFile(wb,fn);
}

/* ---------- FILE / UI ---------- */
let COMPS=[],CUR=0;
const fmtDate=s=>{const m=/^(\d{4})-(\d{2})-(\d{2})$/.exec(s||'');return m?`${m[3]}/${m[2]}/${m[1]}`:'';};
function buildCompSel(){
  const sel=document.getElementById('cSel');
  const cur=sel.value;
  const _dispN=(c,i)=>(i===0&&COMP_DISPLAY_NAME)?COMP_DISPLAY_NAME:(c.title||c.sheet);
  sel.innerHTML=`<option value="all">— Todo el evento —</option>`+COMPS.map((c,i)=>`<option value="${i}">${_dispN(c,i)}</option>`).join('');
  sel.value=(cur==='all'||cur==='')?'all':String(CUR);
}
function syncCompInputs(){
  const sel=document.getElementById('cSel');
  const isAll=CUR==='all';
  if(sel)sel.value=isAll?'all':String(CUR);
  document.getElementById('cDate').value=(!isAll&&COMPS[CUR])?COMPS[CUR].date||'':'';
}
function updateCompHeader(){
  const el=document.getElementById('comptitle');
  const hasLogos=Object.keys(COMP_LOGOS).some(k=>COMP_LOGOS[k]);
  el.classList.toggle('has-logos',hasLogos);
  const logoImg=(idx)=>COMP_LOGOS[idx]?`<img class="ct-logo" src="${COMP_LOGOS[idx]}" alt="">`: '';
  if(CUR==='all'){
    // For multi-comp: logos on left (first comp) and right (rest), text in center
    const leftLogo=logoImg(0);
    const rightLogos=COMPS.slice(1).map((_,i)=>logoImg(i+1)).filter(Boolean).join('');
    el.style.display='flex';
    el.innerHTML=(leftLogo?`<div class="ct-logos">${leftLogo}</div>`:'')
      +`<div class="ct-center"><span class="ct-name">Todo el evento</span><span class="ct-date" style="font-size:13px;color:var(--ink-soft)">${COMPS.length} competencias · ${COMPS.map((c,i)=>(i===0&&COMP_DISPLAY_NAME)?COMP_DISPLAY_NAME:(c.title||c.sheet)).join(', ')}</span></div>`
      +(rightLogos?`<div class="ct-logos">${rightLogos}</div>`:'');
    return;
  }
  const c=COMPS[CUR];
  if(!c){el.style.display='none';el.innerHTML='';return;}
  const d=fmtDate(c.date);
  const logo=logoImg(CUR);
  el.style.display='flex';
  const _cName=(COMP_DISPLAY_NAME||c.title||c.sheet||'Competencia');
  el.innerHTML=(logo?`<div class="ct-logos">${logo}</div>`:'')+`<div class="ct-center"><span class="ct-name">${_cName}</span>${d?`<span class="ct-date">📅 ${d}</span>`:''}</div>`;
}
function renderBlocksConfig(){
  const panel=document.getElementById('blocksConfigPanel');
  if(!panel)return;
  const _defBlkLabel=id=>id===1?'Smooth / Standard':id===2?'Rhythm / Latin':'Bloque '+id;
  // Rebuild only when block count changed to avoid losing focus on re-renders
  const existing=panel.dataset.blockCount;
  const needRebuild=existing!==String(BLOCK_COUNT);
  if(needRebuild){
    let html=`<div class="ctl edit-only"><label>Cantidad de bloques</label><input type="number" id="blockCountInp" value="${BLOCK_COUNT}" min="1" max="8" step="1" style="width:52px"></div>`;
    for(let i=1;i<=BLOCK_COUNT;i++){
      html+=`<div class="ctl edit-only"><label>Bloque ${i}</label><input type="text" class="blk-cfg-name" data-bid="${i}" value="${(BLOCK_LABELS[i]||_defBlkLabel(i)).replace(/"/g,'&quot;')}" placeholder="${_defBlkLabel(i)}" style="width:140px"></div>`;
    }
    panel.innerHTML=html;
    panel.dataset.blockCount=String(BLOCK_COUNT);
    const countInp=panel.querySelector('#blockCountInp');
    if(countInp){
      countInp.addEventListener('change',()=>{
        const n=Math.max(1,Math.min(8,parseInt(countInp.value)||2));
        // al reducir, traer los overrides que apuntaban a bloques que ya no existen
        if(n<BLOCK_COUNT){
          [EVENT_BLOCKS,TEAM_BLOCKS,JJ_BLOCK_OVERRIDES,ROUND_BLOCKS].forEach(map=>{
            Object.keys(map).forEach(k=>{if(typeof map[k]==='number'&&map[k]>n)map[k]=n;});
          });
          if(typeof TEAM_BLOCK==='number'&&TEAM_BLOCK>n)TEAM_BLOCK=n;
        }
        BLOCK_COUNT=n;countInp.value=n;render();
      });
    }
    panel.querySelectorAll('.blk-cfg-name').forEach(inp=>{
      inp.addEventListener('blur',()=>{
        const bid=parseInt(inp.dataset.bid);
        const v=inp.value.trim();
        if(v)BLOCK_LABELS[bid]=v; else delete BLOCK_LABELS[bid];
        const _shown=blkLabelOf(String(bid),bid);inp.value=_shown;
        document.querySelectorAll(`.blk-label-inp[data-bid="${bid}"]`).forEach(el=>{el.value=_shown;});
        render();
      });
      inp.addEventListener('keydown',ev=>{if(ev.key==='Enter')inp.blur();});
    });
  } else {
    // Just sync values without rebuilding DOM
    panel.querySelectorAll('.blk-cfg-name').forEach(inp=>{
      const bid=parseInt(inp.dataset.bid);
      if(document.activeElement!==inp)inp.value=BLOCK_LABELS[bid]||_defBlkLabel(bid);
    });
    const ci=panel.querySelector('#blockCountInp');
    if(ci&&document.activeElement!==ci)ci.value=BLOCK_COUNT;
  }
  // Update teamBlock select options dynamically
  const tbEl=document.getElementById('teamBlock');
  if(tbEl){
    const curVal=parseInt(tbEl.value)||TEAM_BLOCK||1;
    tbEl.innerHTML=Array.from({length:BLOCK_COUNT},(_,i)=>{
      const id=i+1;const name=BLOCK_LABELS[id]||_defBlkLabel(id);
      return `<option value="${id}"${curVal===id?' selected':''}>Bloque ${id} (${name})</option>`;
    }).join('');
  }
}
function renderLogoPanel(){
  const panel=document.getElementById('logoPanel');
  if(!panel)return;
  if(!COMPS.length){panel.style.display='none';panel.innerHTML='';return;}
  panel.style.display='block';
  panel.innerHTML='<div style="font-size:11px;font-weight:700;color:var(--ink-soft);letter-spacing:.05em;margin-bottom:8px;text-transform:uppercase">Logos</div>';
  COMPS.forEach((c,i)=>{
    const src=COMP_LOGOS[i];
    const row=document.createElement('div');
    row.style.cssText='display:flex;align-items:center;gap:9px;margin-bottom:8px';
    const thumb=src
      ?`<img src="${src}" style="height:40px;width:auto;max-width:64px;object-fit:contain;border-radius:5px;border:1px solid var(--line);flex-shrink:0">`
      :`<div style="width:40px;height:40px;border:1.5px dashed var(--line);border-radius:5px;display:flex;align-items:center;justify-content:center;font-size:18px;flex-shrink:0;color:var(--ink-soft)">🖼</div>`;
    row.innerHTML=`${thumb}<div style="flex:1;min-width:0">
      <div style="font-size:11px;font-weight:600;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:var(--ink)">${c.title||c.sheet}</div>
      <div style="display:flex;gap:5px;margin-top:3px">
        <button data-logo-idx="${i}" style="font-size:11px;padding:2px 8px;border:1px solid var(--line);border-radius:5px;background:var(--card);cursor:pointer">${src?'Cambiar':'+ Subir logo'}</button>
        ${src?`<button data-logo-del="${i}" style="font-size:11px;padding:2px 7px;border:1px solid #ddd;border-radius:5px;background:var(--card);cursor:pointer;color:#c0392b">✕</button>`:''}
      </div>
    </div>`;
    panel.appendChild(row);
  });
  panel.querySelectorAll('[data-logo-idx]').forEach(btn=>{
    btn.addEventListener('click',()=>{
      const idx=parseInt(btn.dataset.logoIdx);
      const inp=document.createElement('input');inp.type='file';inp.accept='image/*';
      inp.addEventListener('change',()=>{
        const file=inp.files[0];if(!file)return;
        const reader=new FileReader();
        reader.onload=ev=>{COMP_LOGOS[idx]=ev.target.result;renderLogoPanel();updateCompHeader();};
        reader.readAsDataURL(file);
      });
      inp.click();
    });
  });
  panel.querySelectorAll('[data-logo-del]').forEach(btn=>{
    btn.addEventListener('click',()=>{
      delete COMP_LOGOS[parseInt(btn.dataset.logoDel)];
      renderLogoPanel();updateCompHeader();
    });
  });
}
function uniqTitle(base){let t=base||'Sesión',i=2;const names=new Set(COMPS.map(c=>c.title));while(names.has(t)){t=(base||'Sesión')+' ('+i+')';i++;}return t;}
function handleFile(file){
  const err=document.getElementById('err');err.style.display='none';
  const reader=new FileReader();
  reader.onload=async ev=>{try{
    const wb=XLSX.read(new Uint8Array(ev.target.result),{type:'array'});
    const nuevas=[];
    wb.SheetNames.forEach(name=>{
      const raw=XLSX.utils.sheet_to_json(wb.Sheets[name],{defval:null});
      if(!raw.length)return;
      let rows;try{rows=adaptRows(raw);}catch(e){return;}
      if(!rows||!rows.length)return;
      let m;try{m=buildModel(rows);}catch(e){return;}
      if(!m.events.length&&!m.teams.length)return;
      m.dorsalOf=cp=>{const p=m.persons[cp.leadId];return p&&p.dorsal!==''?p.dorsal:'';};
      nuevas.push({sheet:name,title:uniqTitle(name),date:'',rows,model:m});
    });
    if(!nuevas.length)throw new Error('No se reconocieron inscripciones en el archivo. ¿Es el archivo de respuestas del formulario?');
    nuevas.forEach(c=>COMPS.push(c));
    // si hay más de una comp, pasar a modo "todo el evento"; si es la primera, mostrarla individual
    if(COMPS.length>1){CUR='all';MODEL=null;}
    else{CUR=0;MODEL=COMPS[0].model;}
    const dStart=parseInt(document.getElementById('dStart').value)||1;
    const sStartRaw=document.getElementById('sStart').value;const sStart=sStartRaw?parseInt(sStartRaw):0;
    await loadDorsalOverrides();rebuildDorsals(dStart,sStart);applyDorsalOverrides(); // registro único + overrides manuales
    _jreportCache=null;_mdreportCache=null;_mdVoteFilesCache=null; // los heats/singles cambiaron: refrescar "Resultados Singles"
    document.getElementById('controls').classList.add('show');
    document.getElementById('stats').classList.add('show');
    document.getElementById('tabs').classList.add('show');
    document.getElementById('drop').style.display='none';
    document.getElementById('empty').style.display='none';
    document.getElementById('fileInfo').style.display='block';
    document.getElementById('fileInfo').textContent=COMPS.length+(COMPS.length===1?' sesión cargada':' sesiones cargadas')+' · '+Object.keys(EVENT_DORSALS).length+' competidores con dorsal';
    buildCompSel();syncCompInputs();updateCompHeader();renderLogoPanel();render();
  }catch(e){err.textContent='⚠ '+e.message;err.style.display='block';console.error(e);}
  finally{document.getElementById('file').value='';}};
  reader.readAsArrayBuffer(file);
}
const drop=document.getElementById('drop'),fileInput=document.getElementById('file');
fileInput.addEventListener('change',e=>{if(e.target.files[0])handleFile(e.target.files[0]);});
document.getElementById('addFile').addEventListener('click',()=>fileInput.click());
['dragenter','dragover'].forEach(ev=>drop.addEventListener(ev,e=>{e.preventDefault();drop.classList.add('over');}));
['dragleave','drop'].forEach(ev=>drop.addEventListener(ev,e=>{e.preventDefault();drop.classList.remove('over');}));
drop.addEventListener('drop',e=>{
  const file=e.dataTransfer.files[0];if(!file)return;
  if(file.name.endsWith('.rcdance')||file.name.endsWith('.json')){
    // abrir como proyecto
    const si=document.getElementById('saveInfo');
    const reader=new FileReader();
    reader.onload=ev=>{try{const data=JSON.parse(ev.target.result);loadProjectData(data);si.style.display='block';si.textContent='✓ Proyecto cargado: '+file.name;setTimeout(()=>si.style.display='none',4000);}catch(err){si.style.display='block';si.textContent='⚠ Error al abrir proyecto: '+err.message;}};
    reader.readAsText(file);
  } else {
    handleFile(file);
  }
});
