/* ---------- FUSIÓN MANUAL DE HEATS ---------- */
function getSelectedKeys(){
  // Expande keys separadas por ';' (usadas para heats compartidos con múltiples buckets)
  return [...document.querySelectorAll('.ev-sel input[type=checkbox]:checked')]
    .flatMap(cb=>(cb.dataset.ekey||'').split(';').filter(Boolean));
}
function getDirectKeys(){
  // Una key representativa por heat (para fusión sin modificar)
  return [...document.querySelectorAll('.ev-sel input[type=checkbox]:checked')]
    .map(cb=>cb.dataset.dkey).filter(Boolean);
}
function updateMergeBar(){
  const checked=[...document.querySelectorAll('.ev-sel input[type=checkbox]:checked')];
  const bar=document.getElementById('mergeBar');
  const cnt=document.getElementById('mergeCount');
  if(checked.length>=2){bar.classList.add('show');cnt.textContent=checked.length+' heats seleccionados';}
  else{bar.classList.remove('show');}
}
function getCouplesForKeys(keys){
  // Devuelve {leads:Set, follows:Set} con los IDs de personas en los heats indicados
  const leads=new Set(),follows=new Set();
  if(!LAST_SCH)return{leads,follows};
  for(const B of LAST_SCH.blocks){
    for(const e of B.comps){
      const ek=e.shareKey||e.eventKey||('h:'+e.heat);
      if(!keys.includes(ek))continue;
      (e.couples||[]).forEach(cp=>{
        if(cp.leadId)leads.add(cp.leadId);
        if(cp.follId)follows.add(cp.follId);
      });
      // también buckets (pista compartida directa)
      (e.buckets||[]).forEach(b=>(b.couples||[]).forEach(cp=>{
        if(cp.leadId)leads.add(cp.leadId);
        if(cp.follId)follows.add(cp.follId);
      }));
    }
  }
  return{leads,follows};
}
function hasMergeDuplicates(keys){
  // Devuelve array de nombres duplicados, o [] si ok
  const allLeads=[],allFollows=[];
  if(!LAST_SCH)return[];
  for(const B of LAST_SCH.blocks){
    for(const e of B.comps){
      const ek=e.shareKey||e.eventKey||('h:'+e.heat);
      if(!keys.includes(ek))continue;
      (e.couples||[]).forEach(cp=>{
        if(cp.leadId)allLeads.push({id:cp.leadId,name:cp.lead||cp.leadId});
        if(cp.follId)allFollows.push({id:cp.follId,name:cp.foll||cp.follId});
      });
      (e.buckets||[]).forEach(b=>(b.couples||[]).forEach(cp=>{
        if(cp.leadId)allLeads.push({id:cp.leadId,name:cp.lead||cp.leadId});
        if(cp.follId)allFollows.push({id:cp.follId,name:cp.foll||cp.follId});
      }));
    }
  }
  const dupes=[];
  const seen=new Set();
  [...allLeads,...allFollows].forEach(({id,name})=>{
    if(seen.has(id))dupes.push(name);
    else seen.add(id);
  });
  return[...new Set(dupes)];
}
function showMergeError(names){
  // popup flotante de error
  let el=document.getElementById('merge-err-popup');
  if(!el){el=document.createElement('div');el.id='merge-err-popup';
    el.style.cssText='position:fixed;bottom:90px;left:50%;transform:translateX(-50%);background:#c0392b;color:#fff;padding:12px 22px;border-radius:12px;font-size:14px;font-weight:600;z-index:1001;box-shadow:0 4px 20px rgba(0,0,0,.3);text-align:center;max-width:420px';
    document.body.appendChild(el);}
  el.innerHTML='⚠ No se puede fusionar: <b>'+names.join(', ')+'</b> se repite'+(names.length>1?'n':'')+' en más de un heat.';
  el.style.display='block';
  clearTimeout(el._t);el._t=setTimeout(()=>el.style.display='none',4000);
}
document.getElementById('mergeBtn').addEventListener('click',()=>{
  const mode=document.getElementById('mergeType').value;
  if(mode==='direct'){
    // Fusión sin modificar: usa keys representativas (1 por heat), combina heats ya construidos
    const dkeys=getDirectKeys();
    if(dkeys.length<2)return;
    const dupesDirect=hasMergeDuplicates(dkeys);
    if(dupesDirect.length){showMergeError(dupesDirect);return;}
    let merged=false;
    for(const m of DIRECT_MERGES){
      if(dkeys.some(k=>m.includes(k))){
        dkeys.forEach(k=>{if(!m.includes(k))m.push(k);});
        merged=true;break;
      }
    }
    if(!merged)DIRECT_MERGES.push([...dkeys]);
  } else {
    // Fusión con reagrupamiento interno (reagrupa desde raw)
    const sel=getSelectedKeys();
    if(sel.length<2)return;
    const dupesRe=hasMergeDuplicates(sel);
    if(dupesRe.length){showMergeError(dupesRe);return;}
    let merged=false;
    for(const m of MANUAL_MERGES){
      if(sel.some(k=>m.includes(k))){
        sel.forEach(k=>{if(!m.includes(k))m.push(k);});
        merged=true;break;
      }
    }
    if(!merged)MANUAL_MERGES.push([...sel]);
  }
  document.getElementById('mergeBar').classList.remove('show');
  render();
});
document.getElementById('mergeClear').addEventListener('click',()=>{
  // deseleccionar todos
  document.querySelectorAll('.ev-sel input[type=checkbox]:checked').forEach(cb=>cb.checked=false);
  document.getElementById('mergeBar').classList.remove('show');
});
document.getElementById('printCP').addEventListener('click',()=>{
  document.body.classList.add('print-cp');
  window.print();
  document.body.classList.remove('print-cp');
});
document.getElementById('xlsx').addEventListener('click',exportXlsx);
