const SAVE_KEY='rc-baile-state-v1';

const TEAM_CFG_IDS=['teamCompCount','teamCompLabel1','teamCompLabel2','teamCompLabel3','teamCompLabel4','teamCompLabel5','teamScoreMin','teamScoreMax','teamScoreStep'];
// Tamaños de letra (Configuración → Tamaños de letra): un input por combinación audiencia×categoría,
// mapeado 1 a 1 a las 9 variables CSS --fsd-* definidas en :root (ver applyFontSizeConfig).
const FONT_CFG_IDS=['fsAdminTitle','fsAdminHeat','fsAdminGrid','fsJuecesTitle','fsJuecesHeat','fsJuecesGrid','fsLocutorTitle','fsLocutorHeat','fsLocutorGrid'];
function getControls(){
  const ids=['maxper','dStart','sStart','hStart','dSingle','dRonda','dBreak','nJudges','judges','organizadorNombre','dipLogoSize','shareMode','durPrueba','pistaLabel','minGapHeats',...TEAM_CFG_IDS,...FONT_CFG_IDS];
  const out={mrg:document.getElementById('mrg').checked,showPrueba:document.getElementById('showPrueba').checked,hideConflicts:document.getElementById('hideConflicts').checked,hideHoraPublic:document.getElementById('hideHoraPublic').checked,hideConsultaPublic:document.getElementById('hideConsultaPublic').checked,hideCronogramaPublic:document.getElementById('hideCronogramaPublic').checked,judgeSinglesEnabled:_judgeSinglesEnabled,mdRequireAllVotes:document.getElementById('mdRequireAllVotes').checked,dipHideEventName:document.getElementById('dipHideEventName').checked};
  ids.forEach(id=>{const el=document.getElementById(id);if(el)out[id]=el.value;});
  return out;
}
function setControls(cfg){
  if(!cfg)return;
  if(cfg.mrg!=null)document.getElementById('mrg').checked=cfg.mrg;
  if(cfg.showPrueba!=null)document.getElementById('showPrueba').checked=cfg.showPrueba;
  if(cfg.hideConflicts!=null)document.getElementById('hideConflicts').checked=cfg.hideConflicts;
  if(cfg.hideHoraPublic!=null){_HIDE_HORA_PUBLIC=!!cfg.hideHoraPublic;const el=document.getElementById('hideHoraPublic');if(el)el.checked=cfg.hideHoraPublic;}
  if(cfg.hideConsultaPublic!=null)document.getElementById('hideConsultaPublic').checked=cfg.hideConsultaPublic;
  if(cfg.hideCronogramaPublic!=null)document.getElementById('hideCronogramaPublic').checked=cfg.hideCronogramaPublic;
  _judgeSinglesEnabled=cfg.judgeSinglesEnabled!=null?cfg.judgeSinglesEnabled:true; // default ON si nunca se guardó
  _updateJudgeSinglesBtn();
  document.getElementById('mdRequireAllVotes').checked=cfg.mdRequireAllVotes!=null?cfg.mdRequireAllVotes:false; // default OFF si nunca se guardó (compat)
  document.getElementById('dipHideEventName').checked=cfg.dipHideEventName!=null?cfg.dipHideEventName:false; // default OFF (muestra el nombre) si nunca se guardó
  ['maxper','dStart','sStart','hStart','dSingle','dRonda','dBreak','nJudges','judges','organizadorNombre','dipLogoSize','shareMode','durPrueba','pistaLabel','minGapHeats',...TEAM_CFG_IDS,...FONT_CFG_IDS].forEach(id=>{
    if(cfg[id]!=null){const el=document.getElementById(id);if(el)el.value=cfg[id];}
  });
  updateTeamCompExtraVisibility();
  applyFontSizeConfig();
  // localStorage override: estos dos toggles se guardan localmente para sobrevivir refreshes
  // sin depender del timing del admin-backup (que tiene delay de 1.5s).
  const _hc=localStorage.getItem('rc_hide_consulta');
  if(_hc!==null){const el=document.getElementById('hideConsultaPublic');if(el)el.checked=_hc==='1';}
  const _hcr=localStorage.getItem('rc_hide_cronograma');
  if(_hcr!==null){const el=document.getElementById('hideCronogramaPublic');if(el)el.checked=_hcr==='1';}
  applyConsultaLinkVisibility();
  applyCronogramaLinkVisibility();
}
// Aplica los 9 deltas de Tamaños de letra como variables CSS en vivo (oninput/onchange de cada input
// y al cargar/restaurar Configuración). Cada variable CSS ya tiene default 0px en :root, así que un
// input vacío o en blanco simplemente no cambia nada.
const FONT_CFG_VARS={fsAdminTitle:'--fsd-admin-title',fsAdminHeat:'--fsd-admin-heat',fsAdminGrid:'--fsd-admin-grid',fsJuecesTitle:'--fsd-jueces-title',fsJuecesHeat:'--fsd-jueces-heat',fsJuecesGrid:'--fsd-jueces-grid',fsLocutorTitle:'--fsd-locutor-title',fsLocutorHeat:'--fsd-locutor-heat',fsLocutorGrid:'--fsd-locutor-grid'};
function applyFontSizeConfig(){
  FONT_CFG_IDS.forEach(id=>{
    const el=document.getElementById(id);
    const v=parseFloat(el&&el.value)||0;
    document.documentElement.style.setProperty(FONT_CFG_VARS[id],v+'px');
  });
}
// Muestra/oculta los inputs de nombre del componente 4 y 5 según teamCompCount (3 ó 5).
function updateTeamCompExtraVisibility(){
  const extra=document.getElementById('teamCompExtra');
  if(!extra)return;
  const n=parseInt(document.getElementById('teamCompCount')?.value)||3;
  extra.style.display=(n>=5)?'flex':'none';
}
// Config de puntaje de Equipos (Showdance/Formation), leída en vivo de Configuración: cantidad y
// nombres de componentes, rango de puntaje y paso (medios=0.5 / cuartos=0.25). 'keys' son claves de
// almacenamiento fijas (c1..c5), independientes del nombre visible, para que renombrar un componente
// no pierda los votos ya cargados con el nombre anterior.
const TEAM_COMP_KEYS=['c1','c2','c3','c4','c5'];
function getTeamScoringConfig(){
  let n=parseInt(document.getElementById('teamCompCount')?.value)||3;
  if(n!==3&&n!==5)n=3;
  const keys=TEAM_COMP_KEYS.slice(0,n);
  const labels=keys.map((k,i)=>{
    const v=(document.getElementById('teamCompLabel'+(i+1))?.value||'').trim();
    return v||('C'+(i+1));
  });
  let min=parseFloat(document.getElementById('teamScoreMin')?.value);
  let max=parseFloat(document.getElementById('teamScoreMax')?.value);
  if(isNaN(min))min=1;
  if(isNaN(max)||max<=min)max=min+4;
  let step=parseFloat(document.getElementById('teamScoreStep')?.value);
  if(step!==0.5&&step!==0.25)step=0.25;
  return {n,keys,labels,min,max,step};
}

function buildProjectPayload(){
  return JSON.stringify({
    version:2,
    saved:new Date().toISOString(),
    controls:getControls(),
    cur:CUR,
    shareOverrides:SHARE_OVERRIDES,
    heatReorder:HEAT_REORDER,
    singlesMerges:SINGLES_MERGES,
    manualMerges:MANUAL_MERGES,
    directMerges:DIRECT_MERGES,
    blockTimes:BLOCK_TIMES,
    hiddenBreaks:[...HIDDEN_BREAKS],
    voidedHeats:[...VOIDED_HEATS],
    voidedCouples:[...VOIDED_COUPLES],
    logos:COMP_LOGOS,
    teamBlock:TEAM_BLOCK,
    teamBlocks:TEAM_BLOCKS,
    eventBlocks:EVENT_BLOCKS,
    blockLabels:BLOCK_LABELS,
    jjBlockOverrides:JJ_BLOCK_OVERRIDES,
    roundBlocks:ROUND_BLOCKS,
    cronNote:CRON_NOTE,
    blockCount:BLOCK_COUNT,
    comps:COMPS.map(c=>({sheet:c.sheet,title:c.title,date:c.date,rows:c.rows,ageMode:c.ageMode||undefined}))
  });
}

function saveState(){
  const si=document.getElementById('saveInfo');
  if(!COMPS.length){si.style.display='block';si.textContent='⚠ No hay datos para guardar.';setTimeout(()=>si.style.display='none',3000);return;}
  try{
    const payload=buildProjectPayload();
    const blob=new Blob([payload],{type:'application/json'});
    const url=URL.createObjectURL(blob);
    const a=document.createElement('a');
    const name=(COMPS.map(c=>c.title||c.sheet).join('-')||'evento').replace(/[^\w\sáéíóúñ-]/gi,'').trim();
    a.href=url;a.download=name+'.rcdance';
    document.body.appendChild(a);a.click();
    setTimeout(()=>{URL.revokeObjectURL(url);document.body.removeChild(a);},1000);
    si.style.display='block';si.textContent='✓ Proyecto descargado: '+name+'.rcdance';
    setTimeout(()=>si.style.display='none',4000);
  }catch(e){
    si.style.display='block';si.textContent='⚠ Error al guardar: '+e.message;
  }
}

// Escribe un "archivo lógico" en Supabase. path se mapea a una fila de kv_store (key=path sin .json)
// o, para votos de jueces ('votes/judge-N.json'), a una fila de judge_votes (judge_index=N).
// Postgres resuelve los upsert concurrentes a nivel de fila — ya no hace falta cola ni reintentos por SHA.
function dbUpload(payload,silent=false,path='published-data.json'){
  return _dbUploadAttempt(payload,silent,path);
}
async function _dbUploadAttempt(payload,silent,path){
  const si=document.getElementById('saveInfo');
  try{
    const value=JSON.parse(payload);
    let error;
    const m=path.match(/^votes\/judge-(\d+)\.json$/);
    const mm=path.match(/^votes\/judge-(\d+)-multi\.json$/);
    // IMPORTANTE: tanto para votos de Single Dances (tabla judge_votes) como de Multidance (kv_store,
    // clave 'votes/judge-N-multi') el payload que se sube es un SOBRE {judgeIdx,judgeName,votes,updatedAt}
    // (ver syncJudgeVotes/syncJudgeMultiVotes), pero lo que hay que GUARDAR es solo value.votes (el mapa
    // real de votos), nunca el sobre completo. Guardar el sobre entero produce un bug de anidamiento
    // infinito: la próxima vez que se lee con dbGetFile, pullJudge(Multi)VotesFromSupabase guarda ESE
    // sobre completo como si fuera el mapa de votos, y el siguiente upload lo vuelve a envolver una
    // vez más — los votos reales quedan enterrados cada vez más hondo y la UI los ve como "vacíos"
    // (por eso desaparecían al refrescar la pantalla, sin llegar nunca al Locutor).
    if(m){
      ({error}=await sb.from('judge_votes').upsert({judge_index:parseInt(m[1]),votes:value.votes||{},updated_at:new Date().toISOString()}));
    }else if(mm){
      ({error}=await sb.from('judge_votes_multi').upsert({judge_index:parseInt(mm[1]),votes:value.votes||{},updated_at:new Date().toISOString()}));
    }else{
      const key=path.replace(/\.json$/,'');
      ({error}=await sb.from('kv_store').upsert({key,value,updated_at:new Date().toISOString()}));
    }
    if(error)throw new Error(error.message);
    if(!silent&&si){
      si.style.display='block';si.style.background='#e7eee8';si.style.borderColor='#b8d4bb';si.style.color='#3f6b4a';
      si.textContent='✓ Publicado en Supabase — los demás dispositivos ya lo ven.';
      setTimeout(()=>si.style.display='none',5000);
    }
    return{ok:true};
  }catch(e){
    if(!silent&&si){si.style.display='block';si.style.background='';si.style.borderColor='';si.style.color='';si.textContent='⚠ Error Supabase: '+e.message;}
    return{ok:false,msg:e.message};
  }
}
// Lee un "archivo lógico" desde Supabase (para reportes/votos/restauración). Devuelve null si no existe.
async function dbGetFile(path){
  try{
    const m=path.match(/^votes\/judge-(\d+)\.json$/);
    if(m){
      const {data,error}=await sb.from('judge_votes').select('votes').eq('judge_index',parseInt(m[1])).maybeSingle();
      if(error||!data)return null;
      return JSON.stringify(data.votes);
    }
    const mm2=path.match(/^votes\/judge-(\d+)-multi\.json$/);
    if(mm2){
      const {data,error}=await sb.from('judge_votes_multi').select('votes').eq('judge_index',parseInt(mm2[1])).maybeSingle();
      if(!error&&data)return JSON.stringify(data.votes);
      // Fallback: browser cache puede estar corriendo versión anterior que escribe a kv_store
      const kvKey='votes/judge-'+mm2[1]+'-multi';
      const {data:kvd}=await sb.from('kv_store').select('value').eq('key',kvKey).maybeSingle();
      if(kvd){const v=kvd.value;return JSON.stringify((v&&v.votes)?v.votes:v);}
      return null;
    }
    const key=path.replace(/\.json$/,'');
    const {data,error}=await sb.from('kv_store').select('value').eq('key',key).maybeSingle();
    if(error||!data)return null;
    return JSON.stringify(data.value);
  }catch(e){return null;}
}
/* ---------- EDICIONES (archivado histórico de competencias) -----------------------
   Cada fila de la tabla 'ediciones' es una competencia completa: 'activa' es la de hoy
   (en la que se sigue editando/votando en vivo), 'archivada' es una ya cerrada cuyo
   resultado final quedó congelado en la columna snapshot (jsonb). Tanto el admin como
   la vista pública pueden abrir una edición archivada en modo solo-lectura sin afectar
   nunca los datos en vivo de la edición activa. */
function _escEd(s){return String(s==null?'':s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
async function fetchEdicionActiva(){
  try{
    const {data,error}=await sb.from('ediciones').select('*').eq('estado','activa').order('creada_at',{ascending:false}).limit(1).maybeSingle();
    if(error||!data)return null;
    return data;
  }catch(e){return null;}
}
async function listEdicionesArchivadas(){
  try{
    const {data,error}=await sb.from('ediciones').select('id,nombre,fecha,cerrada_at').eq('estado','archivada').order('fecha',{ascending:false});
    if(error||!data)return [];
    return data;
  }catch(e){return [];}
}
async function initEdicionActual(){
  EDICION_ACTUAL=await fetchEdicionActiva();
  if(!MODO_HISTORICO)EDICION_VISTA=EDICION_ACTUAL;
  renderEdicionBadge();
}
function renderEdicionBadge(){
  const b=document.getElementById('edicionBadge');
  if(!b)return;
  if(MODO_HISTORICO&&EDICION_VISTA){
    b.style.display='block';
    b.innerHTML=`<div style="background:#fdf3d9;border:1.5px solid #e3c878;color:#8a6d1a;padding:10px 16px;border-radius:10px;font-size:13px;font-weight:700;display:flex;align-items:center;gap:10px;flex-wrap:wrap">
      <span>📦 Viendo edición archivada: ${_escEd(EDICION_VISTA.nombre||'')} (${_escEd(EDICION_VISTA.fecha||'')}) — Solo lectura</span>
      <button class="act" style="font-size:12px;padding:4px 12px" onclick="volverAEdicionActiva()">Volver a la edición activa</button>
    </div>`;
  }else{
    b.style.display='none';b.innerHTML='';
  }
}
async function abrirSelectorEdiciones(){
  document.getElementById('edicion-modal').style.display='flex';
  const cont=document.getElementById('edicionListBody');
  if(cont)cont.innerHTML='<div class="note">Cargando...</div>';
  const list=await listEdicionesArchivadas();
  if(!cont)return;
  if(!list.length){
    cont.innerHTML='<div class="note">Todavía no hay ediciones archivadas. Cuando cierres una competencia desde "📦 Cerrar y archivar competencia", va a aparecer acá.</div>';
    return;
  }
  cont.innerHTML=list.map(e=>`<div style="display:flex;justify-content:space-between;align-items:center;gap:10px;padding:10px 12px;border:1px solid var(--line,#eee);border-radius:8px;margin-bottom:8px">
    <div><b>${_escEd(e.nombre||'Competencia')}</b><br><span style="font-size:12px;color:var(--ink-soft)">${_escEd(e.fecha||'')}</span></div>
    <div style="display:flex;gap:6px">
      <button class="act" onclick="cargarEdicionHistorica('${e.id}')">Ver resultados</button>
      <button class="act" style="background:#c0392b;border-color:#c0392b" onclick="eliminarEdicionArchivada('${e.id}','${_escEd(e.nombre||'Competencia')}')">🗑 Eliminar</button>
    </div>
  </div>`).join('');
}
function cerrarSelectorEdiciones(){const m=document.getElementById('edicion-modal');if(m)m.style.display='none';}
async function eliminarEdicionArchivada(id,nombre){
  if(!confirm(`¿Eliminar la edición "${nombre}"?\n\nEsta acción no se puede deshacer.`))return;
  try{
    const {error}=await sb.from('ediciones').delete().eq('id',id);
    if(error)throw new Error(error.message);
    await abrirSelectorEdiciones();
  }catch(e){alert('Error al eliminar: '+e.message);}
}
async function cargarEdicionHistorica(id){
  try{
    const {data,error}=await sb.from('ediciones').select('*').eq('id',id).maybeSingle();
    if(error||!data||!data.snapshot||!data.snapshot.adminBackup){alert('No se pudo cargar esa edición.');return;}
    cerrarSelectorEdiciones();
    MODO_HISTORICO=true;EDICION_VISTA=data;_edicionHistSnapshot=data.snapshot;_jreportCache=null;_mdreportCache=null;_mdVoteFilesCache=null;
    document.body.classList.add('historico-mode');
    document.getElementById('tabs').innerHTML=''; // forzar reconstrucción con el set de tabs histórico (habilita "Resultados Singles")
    renderEdicionBadge();
    loadProjectData(data.snapshot.adminBackup);
  }catch(e){alert('Error al cargar la edición: '+e.message);}
}
async function volverAEdicionActiva(){
  MODO_HISTORICO=false;EDICION_VISTA=EDICION_ACTUAL;_edicionHistSnapshot=null;_jreportCache=null;_mdreportCache=null;_mdVoteFilesCache=null;
  document.body.classList.remove('historico-mode');
  document.getElementById('tabs').innerHTML='';
  renderEdicionBadge();
  if(APP_MODE==='admin'){
    try{
      const raw=await dbGetFile('admin-backup.json');
      if(raw){const data=JSON.parse(raw);if(data&&data.comps&&data.comps.length){loadProjectData(data);return;}}
    }catch(e){}
    clearLocalProjectState();render();
  }else{
    loadPublished();
  }
}
/* ---------- TEMA (claro/oscuro, controlado desde el admin para todos) ---------- */
// Aplica el tema en este dispositivo (clase en <body> + cache local para evitar parpadeos al recargar).
const THEME_MODES=['light','dark','chile','mexico'];
function applyTheme(mode){
  if(!THEME_MODES.includes(mode))mode='light';
  document.body.classList.toggle('dark',mode==='dark');
  document.body.classList.toggle('chile',mode==='chile');
  document.body.classList.toggle('mexico',mode==='mexico');
  try{localStorage.setItem('rc_theme',mode);}catch(e){}
  const sel=document.getElementById('themeSelect');
  if(sel&&sel.value!==mode)sel.value=mode;
}
// Aplica al instante el último tema visto en este dispositivo (sin esperar la red), y después
// loadTheme() confirma/corrige contra Supabase, que es la fuente de verdad real.
function applyLocalThemeFast(){
  try{const t=localStorage.getItem('rc_theme');if(t)applyTheme(t);}catch(e){}
}
// Lee el tema publicado en Supabase y lo aplica. Se llama al cargar cualquier vista (admin, jueces,
// locutor, viewer, inscripción pública) y en cada polling, para que el cambio del admin llegue a todos.
async function loadTheme(){
  try{
    const raw=await dbGetFile('site-theme.json');
    if(raw){
      const parsed=JSON.parse(raw);
      if(parsed&&parsed.mode)applyTheme(parsed.mode);
    }
  }catch(e){}
}
// Solo se llama desde el admin (toggle en el sidebar): aplica el tema local y lo publica para todos.
async function setTheme(mode){
  applyTheme(mode);
  await dbUpload(JSON.stringify({mode}),true,'site-theme.json');
}
function toggleTheme(){
  setTheme(document.body.classList.contains('dark')?'light':'dark');
}
// Selector de tema en Configuración → Datos del evento (reemplaza al toggle del sidebar).
function onThemeSelectChange(){
  const sel=document.getElementById('themeSelect');
  if(sel)setTheme(sel.value);
}
// Payload publicado: sin logos (se mantienen livianos para que la vista pública cargue rápido)
function buildGHPayload(){
  const d=JSON.parse(buildProjectPayload());
  delete d.logos;
  return JSON.stringify(d);
}
function buildLocutorItems(){
  const maxX=Math.max(2,parseInt(document.getElementById('maxper').value)||6);
  const merge=document.getElementById('mrg').checked;
  const timing={start:null,single:parseInt(document.getElementById('dSingle').value)||0,ronda:parseInt(document.getElementById('dRonda').value)||0,brk:parseInt(document.getElementById('dBreak').value)||0,prueba:parseInt(document.getElementById('durPrueba').value)||0};
  const shareMode=document.getElementById('shareMode').value;
  let SCH;
  if(CUR==='all'){SCH=buildFullSchedule(maxX,merge,timing,shareMode);}
  else{const heatOff=COMPS.slice(0,Math.max(0,CUR)).reduce((acc,c)=>{const s=buildSchedule(c.model,maxX,merge,timing,shareMode,acc);return s.total;},0);SCH=buildSchedule(MODEL,maxX,merge,timing,shareMode,heatOff);}
  applyHeatReorder(SCH);
  prepareSCHDisplay(SCH); // updates _DISPLAY_BLOCKS and comp._displayHeat
  const blocksDisp=_DISPLAY_BLOCKS;
  // Igual criterio que buildJudgeVoteUnits: heats/parejas anulados no aparecen en el checklist
  // del locutor (no hay que anunciarlos ni marcarlos como pendientes).
  const items=[];
  blocksDisp.forEach(B=>{
    B._displaySingles.forEach(s=>{
      const parts=s._mergedParts||null;
      if(parts){
        const liveParts=parts
          .filter(part=>!isHeatVoided(singleVoidKey(part.heat)))
          .map(part=>({...part,couples:(part.couples||[]).filter(c=>!isCoupleVoided(singleVoidKey(part.heat),c))}))
          .filter(part=>part.couples.length>0);
        if(!liveParts.length)return;
        items.push({heat:s._displayHeat??s.heat,name:s.rl,couples:liveParts.flatMap(p=>p.couples),block:B.label,parts:liveParts});
      }else{
        const hKey=singleVoidKey(s.heat);
        if(isHeatVoided(hKey))return;
        const liveCouples=(s.couples||[]).filter(c=>!isCoupleVoided(hKey,c));
        if(!liveCouples.length)return;
        items.push({heat:s._displayHeat??s.heat,name:s.rl,couples:liveCouples,block:B.label,parts:null});
      }
    });
    B.comps.forEach(e=>{
      const hKey=compVoidKey(e);
      if(isHeatVoided(hKey))return;
      const liveCouples=(e.couples||[]).filter(c=>!isCoupleVoided(hKey,c));
      if(!liveCouples.length)return;
      items.push({heat:(e._displayHeat??e.heat),name:e.name.replace(' · pista compartida',''),couples:liveCouples,block:B.label,dances:(e.dances||[]).map(d=>d.replace(/^\([^)]*\) /,'').replace(/\[|\]/g,'').trim()),eventKey:e.eventKey||null});
    });
  });
  return items;
}
// Cache del estado de la cartelera para el Locutor (heat actual + modo sync). TTL 20 s para no
// llamar a Supabase en cada re-render del checklist (que ocurre tras cada click del Locutor).
let _locCartelera={heat:null,syncLocutor:false};
let _locCarteleraTs=0;
async function _ensureLocCartelera(force){
  if(!force&&Date.now()-_locCarteleraTs<20000)return;
  try{const s=await carteleraLoadState();_locCartelera={heat:(s&&s.heat>0?s.heat:null),syncLocutor:!!(s&&s.syncLocutor)};}catch(e){}
  _locCarteleraTs=Date.now();
}
// Devuelve los nombres de los jueces asignados a un item del Locutor.
// Singles: JUDGE_ASSIGN.single indexado por display-heat (el mismo key que usa buildJudgeVoteUnits).
// Multi/comp (item.dances presente): JUDGE_ASSIGN.multi indexado por gkey (formato "heat:sufijo");
//   buscamos todos los gkeys que arrancan con el heat del item para cubrir heats compartidos.
// Sin asignación explícita → todos los jueces con nombre.
function _locutorJudges(item){
  const names=judgeNames();
  const filled=names.filter(Boolean);
  if(!filled.length)return [];
  if(item.dances){
    const pre=String(item.heat)+':';
    const ma=JUDGE_ASSIGN.multi||{};
    let idxs=null;
    for(const[k,v]of Object.entries(ma)){
      if(k.startsWith(pre)&&v&&v.length){
        if(idxs===null)idxs=new Set(v);
        else v.forEach(i=>idxs.add(i));
      }
    }
    if(idxs===null)return filled;
    return[...idxs].sort((a,b)=>a-b).map(i=>names[i]).filter(Boolean);
  }else{
    const assign=(JUDGE_ASSIGN.single||{})[item.heat];
    if(assign===undefined)return filled;
    return assign.map(i=>names[i]).filter(Boolean);
  }
}
let LOCUTOR_VIEW_MODE='checklist';
function locutorSetMode(m){if(LOCUTOR_VIEW_MODE===m)return;LOCUTOR_VIEW_MODE=m;renderLocutor();}
async function renderLocutor(){
  document.getElementById('app-layout').style.display='none';
  const lv=document.getElementById('locutor-view');
  lv.style.display='block';
  if(!COMPS||!COMPS.length){
    lv.innerHTML='<div style="padding:40px;text-align:center;color:var(--ink-soft);font-size:15px">⏳ Esperando datos del evento...</div>';
    return;
  }
  if(LOCUTOR_VIEW_MODE==='premios'){await renderPremiosScreen(lv,'locutor');return;}
  await _ensureLocCartelera();
  await loadJudgeAssign(); // necesario para _locutorJudges(); se cachea con _judgeAssignLoaded
  const items=buildLocutorItems();
  let done=[];try{done=JSON.parse(localStorage.getItem('rc_locutor_done')||'[]');}catch{}
  const doneSet=new Set(done);
  let doneDancesMap={};try{doneDancesMap=JSON.parse(localStorage.getItem('rc_locutor_dances')||'{}');}catch{}
  const isItemDone=(item,idx)=>doneSet.has(idx)||(item.dances&&item.dances.length>0&&(doneDancesMap[idx]||[]).length>=item.dances.length);
  const doneCnt=items.filter((it,i)=>isItemDone(it,i)).length;
  const total=items.length;
  const pct=total?Math.round(doneCnt/total*100):0;
  const nextIdx=items.findIndex((it,i)=>!isItemDone(it,i));
  const nextItem=nextIdx>=0?items[nextIdx]:null;
  let html=`<div class="loc-hdr"><span style="font-size:26px;line-height:1">🎤</span><div style="flex:1;min-width:0"><div style="font-weight:700;font-size:17px;color:var(--ink)">Modo Locutor</div><div style="font-size:12px;color:var(--ink-soft);overflow:hidden;text-overflow:ellipsis;white-space:nowrap">${COMPS[0]?.title||'Evento'}</div></div><div style="display:flex;flex-direction:column;align-items:flex-end;gap:6px"><div style="text-align:right;font-size:20px;font-weight:800;color:var(--ink);white-space:nowrap">${doneCnt}<span style="font-size:13px;font-weight:400;color:var(--ink-soft)">/${total}</span></div><button onclick="locutorLogout()" style="font-size:11px;padding:3px 10px;border:1px solid var(--line);border-radius:7px;background:var(--card);cursor:pointer;color:var(--ink-soft);white-space:nowrap">↩ Cambiar usuario</button></div></div>`;
  html+=`<div class="loc-prog-wrap"><div class="loc-prog-fill" style="width:${pct}%"></div></div>`;
  if(_locCartelera.syncLocutor){html+=`<div style="padding:6px 14px 2px;font-size:11px;color:#2e7d6e;font-weight:600;display:flex;align-items:center;gap:6px">📺 Sync con cartelera activo<span style="font-weight:400;color:var(--ink-soft)"> — el heat verde se muestra en pantalla automáticamente</span></div>`;}
  if(nextItem){html+=`<div class="loc-banner">▶&nbsp;&nbsp;<strong>Heat ${nextItem.heat}</strong>&nbsp;·&nbsp;${nextItem.name}</div>`;}
  else if(total>0){html+=`<div class="loc-banner" style="background:#2e7d4f">✅&nbsp;¡Evento completado!</div>`;}
  html+=`<div style="padding:6px 14px 2px;display:flex;justify-content:flex-end;gap:8px"><button onclick="locutorSetMode('premios')" style="font-size:12px;padding:4px 14px;border:1px solid #ddd;border-radius:8px;background:var(--card);cursor:pointer;color:var(--ink-soft)">🏆 Resultados premios</button><button onclick="resetLocutor()" style="font-size:12px;padding:4px 14px;border:1px solid #ddd;border-radius:8px;background:var(--card);cursor:pointer;color:var(--ink-soft)">🔄 Reiniciar</button></div>`;
  html+=`<div class="loc-list">`;
  let lastBlock='';
  items.forEach((item,idx)=>{
    const isDone=isItemDone(item,idx);
    const isNext=idx===nextIdx;
    if(item.block!==lastBlock){html+=`<div class="loc-blk">${item.block}</div>`;lastBlock=item.block;}
    html+=`<div class="loc-item${isDone?' lc-done':''}${isNext?' lc-next':''}" onclick="toggleLocutor(${idx})">`;
    let danceTags='';
    if(item.dances&&item.dances.length){
      const dArr=doneDancesMap[idx]||[];
      const tags=item.dances.map((d,di)=>{
        const dd=dArr.includes(di);
        return `<span onclick="event.stopPropagation();toggleLocutorDance(${idx},${di})" style="font-size:11px;${dd?'background:#d0d0d0;color:#999;text-decoration:line-through':'background:#e8f0fe;color:#3a5cbf'};border-radius:5px;padding:2px 8px;font-weight:500;cursor:pointer;transition:all .15s">${d}</span>`;
      }).join('');
      danceTags=`<span style="display:flex;flex-wrap:wrap;gap:4px;margin-top:4px;margin-left:28px">${tags}</span>`;
    }
    const syncIcon=(_locCartelera.syncLocutor&&isNext)?'<span style="margin-left:auto;flex-shrink:0;font-size:12px;color:#2e7d6e" title="En pantalla cartelera">📺</span>':'';
    html+=`<div class="loc-top"><span class="loc-icon">${isDone?'✓':isNext?'▶':'○'}</span><span class="loc-hn">Heat ${item.heat}</span><span class="loc-nm" style="${_locCartelera.syncLocutor&&isNext?'flex:1':''}">${item.name}</span>${syncIcon}</div>${danceTags}`;
    if(!isDone){
      const jTxt=_locutorJudges(item).join(' · ');
      if(jTxt)html+=`<div style="font-size:11px;color:#5a7a70;padding:1px 14px 4px 42px">⚖ ${jTxt}</div>`;
      let coupleRows='';
      if(item.parts){
        coupleRows=item.parts.map(part=>{
          const pRows=part.couples.map(c=>`<div class="loc-pair"><span class="loc-dor">${dorsalOf(c)}${checkinBadge(dorsalOf(c))}</span><span class="loc-pname">${coupleTxt(c)}</span></div>`).join('');
          return `<div style="font-size:11px;font-weight:700;color:var(--wine,#2e6da8);padding:4px 12px 1px;border-top:1px dashed #e0d0c0;margin-top:2px">${part.rl}</div>${pRows}`;
        }).join('');
      }else if(item.eventKey&&_HEAT_TANDAS&&_HEAT_TANDAS[item.eventKey]){
        const _htd=_HEAT_TANDAS[item.eventKey];
        coupleRows=(item.dances||[]).map(dance=>{
          const _grps=_htd[dance];
          const _dHeader=`<div style="font-size:11px;font-weight:700;color:var(--wine);padding:4px 12px 1px;border-top:1px dashed #e0d0c0;margin-top:2px">🎵 ${dance}</div>`;
          if(!_grps||!_grps.length)return _dHeader+item.couples.map(c=>`<div class="loc-pair"><span class="loc-dor">${dorsalOf(c)}${checkinBadge(dorsalOf(c))}</span><span class="loc-pname">${coupleTxt(c)}</span></div>`).join('');
          return _dHeader+_grps.map((_g,_gi)=>
            `<div style="font-size:10.5px;font-weight:700;color:var(--ink-soft);padding:1px 12px 1px 16px">Tanda ${_gi+1} · ${_g.length} ${_g.length===1?'pareja':'parejas'}</div>`+
            _g.map(c=>`<div class="loc-pair" style="padding-left:24px"><span class="loc-dor">${dorsalOf(c)}${checkinBadge(dorsalOf(c))}</span><span class="loc-pname">${coupleTxt(c)}</span></div>`).join('')
          ).join('');
        }).join('');
      }else{
        coupleRows=item.couples.map(c=>`<div class="loc-pair"><span class="loc-dor">${dorsalOf(c)}${checkinBadge(dorsalOf(c))}</span><span class="loc-pname">${coupleTxt(c)}</span></div>`).join('');
      }
      html+=`<div class="loc-pairs">${coupleRows}</div>`;
    }
    html+=`</div>`;
  });
  html+=`</div>`;
  lv.innerHTML=html;
  if(nextIdx>=0){setTimeout(()=>{const el=lv.querySelector('.lc-next');if(el)el.scrollIntoView({behavior:'smooth',block:'nearest'});},250);}
}
async function toggleLocutor(idx){
  let done=[];try{done=JSON.parse(localStorage.getItem('rc_locutor_done')||'[]');}catch{}
  const s=new Set(done);if(s.has(idx))s.delete(idx);else s.add(idx);
  localStorage.setItem('rc_locutor_done',JSON.stringify([...s]));
  // Cuando sync activo: enviar automáticamente el próximo heat pendiente a la cartelera.
  if(_locCartelera.syncLocutor){
    try{
      const items=buildLocutorItems();
      let doneDancesMap={};try{doneDancesMap=JSON.parse(localStorage.getItem('rc_locutor_dances')||'{}');}catch{}
      const isItemDone=(it,i)=>s.has(i)||(it.dances&&it.dances.length>0&&(doneDancesMap[i]||[]).length>=it.dances.length);
      const nextIdx=items.findIndex((it,i)=>!isItemDone(it,i));
      if(nextIdx>=0){
        const heatNum=items[nextIdx].heat;
        await dbUpload(JSON.stringify({heat:heatNum,syncLocutor:true,updatedAt:new Date().toISOString()}),true,'cartelera-heat.json');
        _locCartelera={heat:heatNum,syncLocutor:true};_locCarteleraTs=Date.now();
      }
    }catch(e){}
  }
  renderLocutor();
}
async function toggleLocutorDance(heatIdx,danceIdx){
  let doneDancesMap={};try{doneDancesMap=JSON.parse(localStorage.getItem('rc_locutor_dances')||'{}');}catch{}
  let arr=doneDancesMap[heatIdx]||[];
  if(arr.includes(danceIdx)){arr=arr.filter(d=>d!==danceIdx);}else{arr=[...arr,danceIdx];}
  doneDancesMap[heatIdx]=arr;
  localStorage.setItem('rc_locutor_dances',JSON.stringify(doneDancesMap));
  // Cuando sync activo: avanzar cartelera solo si el heat quedó completamente terminado.
  if(_locCartelera.syncLocutor){
    try{
      const items=buildLocutorItems();
      let done=[];try{done=JSON.parse(localStorage.getItem('rc_locutor_done')||'[]');}catch{}
      const doneSet=new Set(done);
      const isItemDone=(it,i)=>doneSet.has(i)||(it.dances&&it.dances.length>0&&(doneDancesMap[i]||[]).length>=it.dances.length);
      const thisItem=items[heatIdx];
      if(thisItem&&isItemDone(thisItem,heatIdx)){
        const nextIdx=items.findIndex((it,i)=>!isItemDone(it,i));
        if(nextIdx>=0){
          const heatNum=items[nextIdx].heat;
          await dbUpload(JSON.stringify({heat:heatNum,syncLocutor:true,updatedAt:new Date().toISOString()}),true,'cartelera-heat.json');
          _locCartelera={heat:heatNum,syncLocutor:true};_locCarteleraTs=Date.now();
        }
      }
    }catch(e){}
  }
  renderLocutor();
}
function resetLocutor(){
  if(!confirm('¿Reiniciar el progreso del locutor? Se borrarán todos los heats marcados.'))return;
  localStorage.removeItem('rc_locutor_done');
  localStorage.removeItem('rc_locutor_dances');
  renderLocutor();
}
function locutorLogout(){
  sessionStorage.removeItem('appMode');
  APP_MODE=null;
  document.body.classList.remove('locutor-mode');
  document.getElementById('locutor-view').style.display='none';
  document.getElementById('app-layout').style.display='';
  const po=document.getElementById('pin-overlay');
  po.style.display='flex';
  document.getElementById('pinInput').value='';
  document.getElementById('pinErr').textContent='';
}
/* ---------- MODO JUEZ ---------- */
