function singlesToRows(d){
  const rows=[];
  if(!d.singles||!Object.keys(d.singles).length)return rows;
  const row=mkCanonRow();
  row['Nombre (leader)']=d.lead;row['DNI del leader']=d.leadDni||null;
  row['Follower (indicar nombre)']=d.foll||null;row['DNI del follower']=d.follDni||null;
  row['Seleccione su escuela']=d.esc||null;
  row['Grupo de edad']=d.edad||null;
  row['Elegir modalidad']='Single Dance';
  row['Contested']=d.contested||'Uncontested';
  row['Tipo de Pareja']=d.proAm||'Amateur-Amateur';
  // Nivel por estilo (Standard/Latin/Smooth/.../SocialAmericano): se elige en el propio formulario
  // de Singles Dances (no hay inscripción "principal" de la que heredarlo, a diferencia de
  // Pareja/Solista/Synchro) — ver C.std/C.lat/etc. en buildModel.
  Object.keys(d.cats||{}).forEach(style=>{row[style+' categoria']=d.cats[style];});
  Object.keys(d.singles).forEach(k=>{row[k]=d.singles[k];});
  rows.push(row);
  return rows;
}
