  if(niv('reg_si_slCat'))cats.SocialLatino=niv('reg_si_slCat');
  if(niv('reg_si_sgCat'))cats.SocialArgentino=niv('reg_si_sgCat');
  if(niv('reg_si_saCat'))cats.SocialAmericano=niv('reg_si_saCat');
  const proAm=pareja?regProAmVal('si'):'Amateur-Amateur';
  const baseD={lead,leadDni,foll,follDni,esc,singles,cats,contested:regContestedVal('si'),proAm};
