// Lista canónica de pares (grupo,ritmo) posibles para Challenge. NO se dedupica por nombre de baile:
// "Viennese Waltz" existe en Standard (INT-ST) y en Smooth (AM-SM), "Rumba" en Latin (INT-LT) y en
// Rhythm (AM-RH); se mantienen ambas entradas para que el admin pueda habilitarlas por separado y el
// público elija explícitamente la modalidad (International/American) en la que quiere bailarlo.
// Tanto el checklist de configuración admin como regRitmoOptions() usan esta misma lista para
// que coincidan exactamente las opciones que el admin puede habilitar con las que puede ver el público.
function challengeRitmoList(){
  const out=[];
  ['INT-ST','INT-LT','AM-SM','AM-RH'].forEach(g=>{
    DANCESETS[GROUP2STYLE[g]].forEach(dn=>{
      out.push({group:g,dance:dn,val:g+'|'+dn});
    });
  });
  return out;
}
// allowed: array opcional de valores "grupo|ritmo" habilitados por el admin (ver challenge-config.json
// en kv_store). Si es null/undefined/vacío, se muestran todos los ritmos (comportamiento original).
// El <select> se agrupa por modalidad (International / American) con <optgroup> para que se distingan
// claramente los ritmos que existen en ambas modalidades (Viennese Waltz, Rumba).
function regRitmoOptions(allowed){
  const list=challengeRitmoList().filter(r=>!allowed||!allowed.length||allowed.includes(r.val));
  const byMod={};
  list.forEach(r=>{const m=r.group.startsWith('INT')?'International':'American';(byMod[m]=byMod[m]||[]).push(r);});
  return ['International','American'].filter(m=>byMod[m]&&byMod[m].length).map(m=>{
    const opts=byMod[m].map(r=>`<option value="${r.val}">${r.dance}</option>`).join('');
    return `<optgroup label="${m}">${opts}</optgroup>`;
  }).join('');
}
// Checklist de ritmos para Challenge (reemplaza el <select> de un solo ritmo): el bailarín puede
// elegir VARIOS ritmos, pero a diferencia de Singles Dances la cantidad por ritmo es siempre 1
// (cada ritmo elegido es un Challenge independiente, no tiene sentido repetirlo). Mismo prefix+id
// que challengeRitmoList()/regReadChallengeChecklist()/regFillChallengeChecklist() para que coincidan.
function regChallengeChecklistHTML(prefix,allowed){
  const list=challengeRitmoList().filter(r=>!allowed||!allowed.length||allowed.includes(r.val));
  const byMod={};
  list.forEach(r=>{const m=r.group.startsWith('INT')?'International':'American';(byMod[m]=byMod[m]||[]).push(r);});
  let html=(!allowed||!allowed.length||allowed.includes('RANDOM'))?`<label style="display:flex;align-items:center;gap:8px;padding:5px 2px;font-size:13.5px;border-bottom:1px solid var(--line)">
    <input type="checkbox" id="${prefix}_RANDOM">
    <span style="flex:1">🎲 Ritmo Random (lo elige el organizador el día de la competencia)</span>
  </label>`:'';
  ['International','American'].forEach(m=>{
    if(!byMod[m]||!byMod[m].length)return;
    html+=`<div style="font-size:11px;font-weight:700;color:var(--ink-soft);text-transform:uppercase;letter-spacing:.04em;margin:8px 0 2px">${m}</div>`;
    byMod[m].forEach(r=>{
      const fid=prefix+'_'+r.group+'_'+r.dance.replace(/[^a-zA-Z0-9]/g,'');
      html+=`<label style="display:flex;align-items:center;gap:8px;padding:5px 2px;font-size:13.5px;border-bottom:1px solid var(--line)">
        <input type="checkbox" id="${fid}">
        <span style="flex:1">${r.dance}</span>
      </label>`;
    });
  });
  return html;
}
// Lee el checklist de Challenge: devuelve el mismo formato {'Ritmos (grupo) [ritmo]':1, ...} que
// usa challengeToRows()/mkCanonRow(), uno por cada ritmo tildado (cantidad siempre 1).
function regReadChallengeChecklist(prefix){
  const out={};
  const rnd=document.getElementById(prefix+'_RANDOM');
  if(rnd&&rnd.checked)out['Ritmos (RANDOM) [Ritmo Random]']=1;
  challengeRitmoList().forEach(r=>{
    const fid=prefix+'_'+r.group+'_'+r.dance.replace(/[^a-zA-Z0-9]/g,'');
    const chk=document.getElementById(fid);
    if(chk&&chk.checked)out['Ritmos ('+r.group+') ['+r.dance+']']=1;
  });
  return out;
}
function regClearChallengeChecklist(prefix){
  const list=document.getElementById(prefix+'_list');
  if(list)list.querySelectorAll('input[type=checkbox]').forEach(c=>c.checked=false);
}
// Reverse-populate (modo edición): tilda los checkboxes correspondientes a las columnas
// "Ritmos (...)" presentes en la fila canónica 'Challenge'.
function regFillChallengeChecklist(row,prefix){
  const rnd=document.getElementById(prefix+'_RANDOM');
  if(rnd)rnd.checked=!!row['Ritmos (RANDOM) [Ritmo Random]'];
  challengeRitmoList().forEach(r=>{
    const fid=prefix+'_'+r.group+'_'+r.dance.replace(/[^a-zA-Z0-9]/g,'');
    const chk=document.getElementById(fid);
    if(chk)chk.checked=!!row['Ritmos ('+r.group+') ['+r.dance+']'];
  });
}
function regChallengeTipoChange(){
  const pareja=document.querySelector('input[name="reg_ch_tipo"][value="pareja"]').checked;
  document.getElementById('reg-ch-foll-box').style.display=pareja?'block':'none';
}
function challengeToRows(d){
  const rows=[];
  const ritmos=d.ritmos||{};
  if(!Object.keys(ritmos).length)return rows;
  const row=mkCanonRow();
  row['Nombre (leader)']=d.lead;row['DNI del leader']=d.leadDni||null;
  row['Follower (indicar nombre)']=d.foll||null;row['DNI del follower']=d.follDni||null;
  row['Seleccione su escuela']=d.esc||null;
  row['Grupo de edad']=d.edad||null;
  row['Elegir modalidad']='Challenge';
  // Se puede elegir más de un ritmo: cada uno es un Challenge independiente (todos contra todos
  // por ritmo), pero entran en UNA sola fila canónica con varias columnas "Ritmos (...)" — mismo
  // esquema que usan los Single Dances — para que buildModel() genere un evento Challenge por
  // ritmo. "Ritmo Random" no es un ritmo real: el organizador lo resuelve el día de la competencia.
  Object.assign(row,ritmos);
  rows.push(row);
  return rows;
}
function regSubmitChallenge(){
  // Challenge no existe en AABD: siempre se tagea como Privada (no hay checkbox que elegir aquí;
  // la pestaña entera se oculta cuando "Privada" no está tildada, ver regUpdateCompVisibility()).
  const {privada}=regCompTags();
  if(!privada){regSetStatus('⚠ Challenge no existe en la Federación. Tildá "Privada" arriba para inscribirte.',true);return;}
  const v=id=>document.getElementById(id).value.trim();
  const pareja=document.querySelector('input[name="reg_ch_tipo"][value="pareja"]').checked;
  const lead=v('reg_ch_lead'),leadDni=v('reg_ch_leadDni');
  if(!lead){regSetStatus('⚠ Ingresá el nombre.',true);return;}
  const foll=pareja?v('reg_ch_foll'):'',follDni=pareja?v('reg_ch_follDni'):'';
  const esc=v('reg_ch_esc'),edad=document.getElementById('reg_ch_edad').value;
  const ritmos=regReadChallengeChecklist('reg_ch_chal');
  if(!Object.keys(ritmos).length){regSetStatus('⚠ Elegí al menos un ritmo.',true);return;}
  const d={lead,leadDni,foll,follDni,esc,edad,ritmos};
  const rows=challengeToRows(d);
  if(!rows.length){regSetStatus('⚠ Elegí al menos un ritmo.',true);return;}
  rows.forEach(r=>{r['Competencia']='Privada';});
  const n=Object.keys(ritmos).length;
  const resumen=`${lead}${foll?' & '+foll:''} — Challenge (${n} ritmo${n>1?'s':''})`;
  submitInscripcionRows('challenge',rows,resumen,regClearChallenge);
}
function regClearChallenge(){
  ['reg_ch_lead','reg_ch_leadDni','reg_ch_foll','reg_ch_follDni','reg_ch_esc'].forEach(id=>document.getElementById(id).value='');
  document.getElementById('reg_ch_edad').value='';
  regClearChallengeChecklist('reg_ch_chal');
  document.querySelector('input[name="reg_ch_tipo"][value="solo"]').checked=true;
  document.getElementById('reg-ch-foll-box').style.display='none';
}
// ----- Calculadora de precios en vivo (formulario público) -----
// Precios base: Multidance (nivel u Open, cada estilo cuenta por separado) $100.000, Single Dance
// $17.000, Challenge $35.000.
// Combos: son "escalones" fijos, no una búsqueda de mínimo costo. Se elige el escalón de multidance
// más alto que la persona alcanza (1/2/4, o 5+1 Challenge), se cobra ese precio plano UNA sola vez
// (incluye hasta 10 Single Dances sin cargo extra), y el resto se cobra a precio base:
//  - Multidance que sobre del escalón elegido: $100.000 c/u.
//  - Single Dances que excedan las 10 incluidas en el escalón: $17.000 c/u extra.
// El escalón de multidance SOLO se aplica si la persona se inscribió en al menos 1 Single Dance
// (si no eligió ninguno, no tiene sentido cobrarle el combo "+10 Singles" que no usa).
// Si no hay multidance (m=0), se usa la escalera de combos de Singles sueltos (10/20/30) y, si no
// ========= JACK & JILL =========
let _HEAT_TANDAS={};
let _JJ_ROUNDS={groups:[]};
let _JJ_INSC=[]; // cache de inscripciones tipo='jackjill'

async function loadHeatTandas(){
  try{const r=await dbGetFile('heat-tandas.json');if(r)_HEAT_TANDAS=JSON.parse(r)||{};}catch(e){_HEAT_TANDAS={};}
}
async function saveHeatTandas(){
  try{await dbUpload(JSON.stringify(_HEAT_TANDAS),true,'heat-tandas.json');}catch(e){}
}
async function generateTandasForHeat(eventKey){
  if(!LAST_SCH)return;
  let heat=null;
  for(const B of(LAST_SCH.blocks||[])){
    for(const e of(B.comps||[])){if(e.eventKey===eventKey){heat=e;break;}}
    if(heat)break;
  }
  if(!heat||!heat.dances||!heat.couples.length)return;
  const maxX=Math.max(2,parseInt(document.getElementById('maxper').value)||6);
  if(heat.couples.length<=maxX){delete _HEAT_TANDAS[eventKey];await saveHeatTandas();render();return;}
  const tandas={};
  const dances=heat.dances.map(d=>d.replace(/^\([^)]*\) /,'').replace(/\[|\]/g,'').trim());
  dances.forEach(dance=>{
    const shuffled=[...heat.couples].sort(()=>Math.random()-0.5);
    const groups=[];
    for(let i=0;i<shuffled.length;i+=maxX)groups.push(shuffled.slice(i,i+maxX));
    tandas[dance]=groups;
  });
  _HEAT_TANDAS[eventKey]=tandas;
  await saveHeatTandas();
  render();
}
function getEventKeyForHeat(heatNum){
  if(!LAST_SCH)return null;
  for(const B of(LAST_SCH.blocks||[])){
    for(const e of(B.comps||[])){if(e.heat===heatNum)return e.eventKey;}
  }
  return null;
}
async function loadJJRoundsFromDB(){
  try{
    const raw=await dbGetFile('jj-rounds.json');
    _JJ_ROUNDS=raw?JSON.parse(raw):{groups:[]};
    if(!_JJ_ROUNDS.groups)_JJ_ROUNDS.groups=[];
    // retrocompatibilidad: reconstruir participantNames desde los pares si no existe
    _JJ_ROUNDS.groups.forEach(g=>{
      if(!g.participantNames)g.participantNames={};
      g.phases.forEach(ph=>(ph.pairs||[]).forEach(p=>{
        ['lead','foll'].forEach(role=>{
          const n=p[role];if(!n)return;
          const k=nameKey(n);if(k)g.participantNames[k]=n;
        });
      }));
    });
  }catch(e){_JJ_ROUNDS={groups:[]};}
}

async function loadJJInscFromDB(){
  try{
    const {data}=FEAT_JACKJILL?(await sb.from('inscripciones').select('id,created_at,resumen,rows').eq('tipo','jackjill').order('created_at',{ascending:true})):{data:[]};
    _JJ_INSC=data||[];
  }catch(e){_JJ_INSC=[];}
}

async function saveJJRoundsDB(){
  await dbUpload(JSON.stringify(_JJ_ROUNDS),true,'jj-rounds.json');
}

// Checkboxes de "quién avanza", con el dorsal adelante. Ordena por dorsal
// (los que todavía no tienen dorsal van al final, por nombre).
function _jjAdvList(names,g,cls,nivelKey,checked){
  const dorOf=n=>{const d=(g&&g.dorsals&&g.dorsals[nameKey(n)]);return typeof d==='number'?d:null;};
  return names.slice().sort((a,b)=>{
    const da=dorOf(a),db=dorOf(b);
    if(da!=null&&db!=null)return da-db;
    if(da!=null)return -1;
    if(db!=null)return 1;
    return a.localeCompare(b,'es');
  }).map(n=>{
    const d=dorOf(n);
    const dorHtml=d!=null
      ? `<b style="min-width:22px;display:inline-block;text-align:right;color:var(--wine)">${d}</b>`
      : `<span style="min-width:22px;display:inline-block;text-align:right;color:var(--ink-soft)">—</span>`;
    return `<label style="display:flex;align-items:center;gap:6px;font-size:12px;margin-bottom:2px"><input type="checkbox" class="${cls}" data-level="${nivelKey}" data-name="${n.replace(/"/g,'&quot;')}" ${checked.includes(n)?'checked':''}>${dorHtml} ${n}</label>`;
  }).join('');
}
function jjGetGroup(level){
  let g=_JJ_ROUNDS.groups.find(x=>x.level===level);
  if(!g){g={level,phases:[]};_JJ_ROUNDS.groups.push(g);}
  return g;
}

function jjCurrentPhase(level){
  const g=jjGetGroup(level);
  return g.phases.find(p=>p.status==='open')||null;
}

function jjShufflePairs(leads,folls){
  const l=[...leads],f=[...folls];
  for(let i=f.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[f[i],f[j]]=[f[j],f[i]];}
  return l.map((lead,i)=>({lead:lead.nombre,leadDni:lead.dni||'',foll:(f[i]||{nombre:'?',dni:''}).nombre,follDni:(f[i]||{}).dni||''}));
}

// Asigna dorsales secuenciales a participantes J&J nuevos (no tienen uno aún).
// Guarda en group.dorsals = {nameKey(nombre): number}
function jjAssignDorsals(group, allParticipants){
  if(!group.dorsals)group.dorsals={};
  if(!group.participantNames)group.participantNames={};
  let next=_JJ_ROUNDS.dorsalStart||1;
  // encontrar el máximo dorsal ya asignado para este grupo
  const existing=Object.values(group.dorsals).filter(v=>typeof v==='number');
  if(existing.length)next=Math.max(...existing)+1;
  allParticipants.forEach(p=>{
    const nombre=p.nombre||p;
    const k=nameKey(nombre);
    if(!k)return;
    if(!(k in group.dorsals))group.dorsals[k]=next++;
    group.participantNames[k]=nombre; // guardar nombre original para tab Dorsales
  });
}

function jjAppendScheduleEntries(out){
  const maxper=parseInt(document.getElementById('maxper')?.value)||6;
  const heatSize=(_JJ_ROUNDS&&_JJ_ROUNDS.heatSize)||maxper;
  let n=0;
  const jjBlockComps=[];

  // Construir byLevel desde inscripciones (igual que jjRenderPane)
  const byLevel={};
  (_JJ_INSC||[]).forEach(ins=>{
    (ins.rows||[]).forEach(r=>{
      const nivel=r['Nivel']||r['Grupo de edad']||'Sin nivel';
      const rol=r['Rol']||'Leader';
      if(!byLevel[nivel])byLevel[nivel]={leaders:[],followers:[]};
      const persona={nombre:r['Nombre']||r['Nombre (leader)']||ins.resumen,dni:r['DNI']||''};
      if(rol==='Follower')byLevel[nivel].followers.push(persona);
      else byLevel[nivel].leaders.push(persona);
    });
  });

  // Niveles con sorteo ya hecho → usar pares reales
  const levelsWithPhases=new Set();
  if(_JJ_ROUNDS&&_JJ_ROUNDS.groups){
    _JJ_ROUNDS.groups.forEach(group=>{
      if(!group.phases||!group.phases.length)return;
      levelsWithPhases.add(group.level);
      group.phases.forEach(phase=>{
        const pairs=phase.pairs||[];
        if(!pairs.length)return;
        const _gDors=group.dorsals||{};
        // Fase final: mostrar solo placeholder en el cronograma
        // (los finalistas se definen durante el evento, al cerrar la semifinal)
        if(phase.isFinal){
          n++;
          const couples=Array.from({length:pairs.length},(_,j)=>({
            lead:'Finalista '+(j+1),
            foll:'(final pendiente)',
            leadId:'__jjfin_'+group.level+'_'+j,
            follId:'',
            _jjPlaceholder:true
          }));
          jjBlockComps.push({
            heat:out.total+n,
            name:'🃏 J&J '+group.level+' · '+phase.label,
            block:'jj',couples,dances:[],
            eventKey:'jj§'+group.level+'§'+phase.id+'§0',
            time:null,_phaseId:phase.id,_level:group.level,kind:'JJ',_isFinal:true,_jjPlaceholder:true
          });
          return;
        }
        for(let i=0;i<pairs.length;i+=heatSize){
          n++;
          const slice=pairs.slice(i,i+heatSize);
          const couples=slice.map(p=>({
            lead:p.lead,foll:p.foll,
            leadId:'jj_l_'+nameKey(p.lead),
            follId:'jj_f_'+nameKey(p.foll),
            _jjLeadDorsal:_gDors[nameKey(p.lead)]||'',
            _jjFollDorsal:_gDors[nameKey(p.foll)]||''
          }));
          jjBlockComps.push({
            heat:out.total+n,
            name:'🃏 J&J '+group.level+' · '+phase.label+(pairs.length>heatSize?' (heat '+(Math.floor(i/heatSize)+1)+')':''),
            block:'jj',couples,dances:[],
            eventKey:'jj§'+group.level+'§'+phase.id+'§'+Math.floor(i/heatSize),
            time:null,_phaseId:phase.id,_level:group.level,kind:'JJ',_isFinal:phase.isFinal||false
          });
        }
      });
    });
  }

  // Niveles SIN sorteo → generar heats placeholder desde inscripciones
  Object.entries(byLevel).forEach(([nivel,{leaders,followers}])=>{
    if(levelsWithPhases.has(nivel))return; // ya tiene sorteo, cubierto arriba
    const totalPairs=Math.min(leaders.length,followers.length);
    if(!totalPairs)return;
    // Placeholder sin sorteo: un solo heat con todas las parejas
    // (el sorteo real definirá cuántos heats y la distribución final)
    n++;
    const couples=Array.from({length:totalPairs},(_,j)=>({
      lead:'Pareja '+(j+1),
      foll:'(sin sortear)',
      leadId:'__jjph_'+nivel+'_'+n+'_'+j,
      follId:'',
      _jjPlaceholder:true
    }));
    jjBlockComps.push({
      heat:out.total+n,
      name:'🃏 J&J '+nivel+' · Fase 1',
      block:'jj',couples,dances:[],
      eventKey:'jj§'+nivel+'§fase1§0',
      time:null,_level:nivel,kind:'JJ',_jjPlaceholder:true
    });
  });

  // Duración de ronda / break, para poder darle horario a los heats de J&J
  const _dRonda=parseFloat(document.getElementById('dRonda')?.value)||0;
  const _dBreak=parseFloat(document.getElementById('dBreak')?.value)||0;

  // Split: overridden JJ heats go to regular blocks; the rest stay in JJ block
  const _jjOwn=[];
  jjBlockComps.forEach(e=>{
    const _ovId=JJ_BLOCK_OVERRIDES[e.eventKey];
    if(_ovId!=null){
      const _tgt=out.blocks.find(b=>b.id===_ovId);
      if(_tgt){
        // continúa desde el final del bloque destino
        if(_tgt.blockEnd!=null){e.time=_tgt.blockEnd;_tgt.blockEnd+=_dRonda;}
        _tgt.comps.push(e);
        out.cron.push({block:_tgt.label,blockId:_tgt.id,lblKey:_tgt.lblKey,blkSeq:_tgt.blkSeq,ekey:e.eventKey,range:''+e.heat,name:e.name,n:e.couples.length,time:e.time,_reoKey:e.eventKey,kind:'JJ'});
      }
      else _jjOwn.push(e); // fallback: target block missing, keep in JJ
    }else{_jjOwn.push(e);}
  });
  out.total+=n;
  if(!_jjOwn.length)return;
  // El bloque Jack & Jill arranca después del último bloque + break
  const _ends=(out.blocks||[]).map(b=>b.blockEnd).filter(v=>v!=null);
  let _jjClock=_ends.length?Math.max(..._ends)+_dBreak:null;
  const _jjStart=_jjClock;
  if(_jjClock!=null)_jjOwn.forEach(e=>{e.time=_jjClock;_jjClock+=_dRonda;});
  out.blocks.push({id:'jj',lblKey:'jj',blkSeq:9999,label:'🃏 Jack & Jill',comps:_jjOwn,singles:[],blockStart:_jjStart,blockEnd:_jjClock});
  _jjOwn.forEach(e=>out.cron.push({block:'🃏 Jack & Jill',blockId:'jj',lblKey:'jj',blkSeq:9999,ekey:e.eventKey,range:''+e.heat,name:e.name,n:e.couples.length,time:e.time,_reoKey:e.eventKey,kind:'JJ'}));
  out.totalBlocks=(out.totalBlocks||0)+1;
}

function paneJJ(){
  const d=document.createElement('div');
  d.className='pane';
  d.dataset.p='jj';
  return d;
}

async function _paneJJLoad(){
  let d=document.querySelector('.pane[data-p="jj"]');
  if(!d)return;
  d.innerHTML='<div style="padding:24px;text-align:center;color:var(--ink-soft)">⏳ Cargando...</div>';
  await loadJJRoundsFromDB();
  try{
    const {data}=FEAT_JACKJILL?(await sb.from('inscripciones').select('id,created_at,resumen,rows').eq('tipo','jackjill').order('created_at',{ascending:true})):{data:[]};
    _JJ_INSC=data||[];
  }catch(e){_JJ_INSC=[];}
  d=document.querySelector('.pane[data-p="jj"]');
  if(!d)return;
  jjRenderPane(d);
}

function jjRenderPane(d){
  const isAdmin=(APP_MODE==='admin'||ROLE==='admin');
  const byLevel={};
  _JJ_INSC.forEach(ins=>{
    const rows=ins.rows||[];
    rows.forEach(r=>{
      const nivel=r['Nivel']||r['Grupo de edad']||'Sin nivel';
      const rol=r['Rol']||'Leader';
      if(!byLevel[nivel])byLevel[nivel]={leaders:[],followers:[]};
      const persona={nombre:r['Nombre']||r['Nombre (leader)']||ins.resumen,dni:r['DNI']||r['DNI del leader']||'',escuela:r['Seleccione su escuela']||''};
      if(rol==='Follower')byLevel[nivel].followers.push(persona);
      else byLevel[nivel].leaders.push(persona);
    });
  });

  let html=`<div style="padding:16px 20px">
    <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:16px;flex-wrap:wrap;gap:8px">
      <h2 style="margin:0;font-size:18px;font-weight:800">🃏 Jack & Jill</h2>
      ${isAdmin?`<div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap">
        <label style="font-size:12px;display:flex;align-items:center;gap:4px">Parejas/heat:
          <input type="number" id="jj-heat-size" value="${_JJ_ROUNDS.heatSize||6}" min="2" max="20"
            style="width:50px;padding:4px 6px;border:1px solid var(--line);border-radius:6px;font-size:12px;background:var(--bg);color:var(--ink)"
            onchange="jjSaveHeatConfig()">
        </label>
        <label style="font-size:12px;display:flex;align-items:center;gap:4px">Dorsal inicial:
          <input type="number" id="jj-dorsal-start" value="${_JJ_ROUNDS.dorsalStart||1}" min="1"
            style="width:58px;padding:4px 6px;border:1px solid var(--line);border-radius:6px;font-size:12px;background:var(--bg);color:var(--ink)"
            onchange="jjSaveHeatConfig()">
        </label>
        <button onclick="_paneJJLoad()" style="padding:6px 14px;border:1px solid var(--line);border-radius:8px;background:var(--strip);color:var(--ink);cursor:pointer;font-size:13px">🔄 Actualizar</button>
      </div>`:''}
    </div>`;

  if(!Object.keys(byLevel).length){
    html+='<div style="color:var(--ink-soft);font-size:14px">No hay inscriptos en Jack & Jill todavía.</div>';
  }

  Object.entries(byLevel).forEach(([nivel,{leaders,followers}])=>{
    const g=jjGetGroup(nivel);
    const phases=g.phases||[];
    const openPhase=phases.find(p=>p.status==='open');

    html+=`<div style="background:var(--card);border:1px solid var(--line);border-radius:14px;padding:16px;margin-bottom:16px">
      <div style="font-size:15px;font-weight:700;margin-bottom:12px">📐 ${nivel}</div>
      <div style="display:flex;gap:16px;margin-bottom:12px;flex-wrap:wrap">
        <div style="flex:1;min-width:140px">
          <div style="font-size:11px;font-weight:700;color:var(--ink-soft);text-transform:uppercase;letter-spacing:.05em;margin-bottom:6px">🕺 Líderes (${leaders.length})</div>
          ${leaders.map(l=>{const dk=nameKey(l.nombre);const dor=(g.dorsals&&g.dorsals[dk])||'';return`<div style="font-size:12px;padding:3px 0;border-bottom:1px solid var(--strip)">${dor?`<b style="min-width:24px;display:inline-block">${dor}</b> `:''} ${l.nombre}${l.dni?` <span style="color:var(--ink-soft)">(DNI ${l.dni})</span>`:''}</div>`;}).join('')||'<div style="font-size:12px;color:var(--ink-soft)">Ninguno</div>'}
        </div>
        <div style="flex:1;min-width:140px">
          <div style="font-size:11px;font-weight:700;color:var(--ink-soft);text-transform:uppercase;letter-spacing:.05em;margin-bottom:6px">💃 Followers (${followers.length})</div>
          ${followers.map(f=>{const dk=nameKey(f.nombre);const dor=(g.dorsals&&g.dorsals[dk])||'';return`<div style="font-size:12px;padding:3px 0;border-bottom:1px solid var(--strip)">${dor?`<b style="min-width:24px;display:inline-block">${dor}</b> `:''} ${f.nombre}${f.dni?` <span style="color:var(--ink-soft)">(DNI ${f.dni})</span>`:''}</div>`;}).join('')||'<div style="font-size:12px;color:var(--ink-soft)">Ninguna</div>'}
        </div>
      </div>`;

    phases.filter(p=>p.status==='closed').forEach(p=>{
      html+=`<div style="background:var(--strip);border-radius:8px;padding:10px 12px;margin-bottom:8px;opacity:0.7">
        <div style="font-size:12px;font-weight:700;margin-bottom:4px">✅ ${p.label} (cerrada)</div>
        <div style="font-size:11px;color:var(--ink-soft)">${(p.pairs||[]).length} parejas · Pasan: ${(p.advancedLeads||[]).length} líderes, ${(p.advancedFolls||[]).length} followers</div>
        ${isAdmin&&p.advancedLeads?`<div style="margin-top:6px">
          <div style="font-size:11px;font-weight:600;margin-bottom:2px">Líderes que avanzan:</div>
          ${(p.advancedLeads||[]).map(n=>`<div style="font-size:11px">${n}</div>`).join('')}
          <div style="font-size:11px;font-weight:600;margin:4px 0 2px">Followers que avanzan:</div>
          ${(p.advancedFolls||[]).map(n=>`<div style="font-size:11px">${n}</div>`).join('')}
        </div>`:''}
      </div>`;
    });

    if(openPhase){
      html+=`<div style="background:var(--strip);border-radius:8px;padding:12px;margin-bottom:8px">
        <div style="font-size:13px;font-weight:700;margin-bottom:8px">🟢 ${openPhase.label} — ${(openPhase.pairs||[]).length} parejas</div>
        <table style="width:100%;border-collapse:collapse;font-size:12px;margin-bottom:10px">
          <thead><tr style="border-bottom:1px solid var(--line)">
            <th style="text-align:left;padding:3px 4px;color:var(--ink-soft)">#</th>
            <th style="text-align:center;padding:3px 4px;color:var(--ink-soft)">Dor.</th>
            <th style="text-align:left;padding:3px 6px;color:var(--ink-soft)">🕺 Líder</th>
            <th style="text-align:center;padding:3px 4px;color:var(--ink-soft)">Dor.</th>
            <th style="text-align:left;padding:3px 6px;color:var(--ink-soft)">💃 Follower</th>
          </tr></thead>
          <tbody>${(openPhase.pairs||[]).map((p,i)=>{const ld=(g.dorsals&&g.dorsals[nameKey(p.lead)])||'—';const fd=(g.dorsals&&g.dorsals[nameKey(p.foll)])||'—';return`<tr style="border-bottom:1px solid var(--strip)"><td style="padding:3px 4px;color:var(--ink-soft)">${i+1}</td><td style="padding:3px 4px;text-align:center;font-weight:700">${ld}</td><td style="padding:3px 6px">${p.lead}</td><td style="padding:3px 4px;text-align:center;font-weight:700">${fd}</td><td style="padding:3px 6px">${p.foll}</td></tr>`;}).join('')}</tbody>
        </table>`;
      if(isAdmin){
        const nivelKey=nivel.replace(/"/g,'&quot;');
        html+=`<div style="margin:10px 0 4px;display:flex;align-items:center;gap:8px;flex-wrap:wrap">
          <button onclick="jjLoadAndShowResults('${nivelKey}','${openPhase.id}',this)"
            style="padding:6px 14px;background:var(--wine);color:#fff;border:none;border-radius:8px;font-size:12px;cursor:pointer;font-weight:600">
            🏆 Obtener resultados
          </button>
          <span style="font-size:11px;color:var(--ink-soft)">Suma de posiciones por juez — menor = mejor</span>
        </div>
        <div id="jj-res-${openPhase.id}" style="margin-bottom:10px"></div>`;
        html+=`<div style="margin-top:8px">
          <div style="font-size:12px;font-weight:700;margin-bottom:6px">Seleccioná quién avanza a la siguiente fase:</div>
          <div style="display:flex;gap:12px;flex-wrap:wrap">
            <div>
              <div style="font-size:11px;font-weight:600;margin-bottom:4px">🕺 Líderes:</div>
              ${_jjAdvList([...new Set((openPhase.pairs||[]).map(p=>p.lead))],g,'jj-adv-lead',nivelKey,openPhase.advancedLeads||[])}
            </div>
            <div>
              <div style="font-size:11px;font-weight:600;margin-bottom:4px">💃 Followers:</div>
              ${_jjAdvList([...new Set((openPhase.pairs||[]).map(p=>p.foll))],g,'jj-adv-foll',nivelKey,openPhase.advancedFolls||[])}
            </div>
          </div>
          <div style="display:flex;gap:8px;margin-top:10px">
            <button onclick="jjSaveAdvanced('${nivelKey}')" style="padding:7px 14px;background:var(--wine);color:#fff;border:none;border-radius:8px;font-size:13px;cursor:pointer;font-weight:600">💾 Guardar selección</button>
            <label style="font-size:12px;display:flex;align-items:center;gap:4px;cursor:pointer"><input type="checkbox" id="jj-is-final-${nivel.replace(/\s/g,'_')}"> La siguiente fase es la <strong>FINAL</strong></label>
            <button onclick="jjClosePhaseAndSorteo('${nivelKey}')" style="padding:7px 14px;background:var(--strip);border:1px solid var(--line);color:var(--ink);border-radius:8px;font-size:13px;cursor:pointer;font-weight:600">✅ Cerrar fase y sortear siguiente</button>
          </div>
          <div id="jj-status-${nivelKey}" style="font-size:12px;color:var(--ink-soft);margin-top:6px"></div>
        </div>`;
      }
      html+='</div>';
    } else if(isAdmin){
      const lastPhase=phases[phases.length-1];
      const leadsPool=lastPhase?(lastPhase.advancedLeads||[]).map(n=>({nombre:n,dni:''})):leaders;
      const follsPool=lastPhase?(lastPhase.advancedFolls||[]).map(n=>({nombre:n,dni:''})):followers;
      const phaseLabel='Fase '+(phases.length+1);
      const nivelKey=nivel.replace(/"/g,'&quot;');
      if(leadsPool.length&&follsPool.length){
        html+=`<div style="margin-top:8px">
          <div style="font-size:12px;color:var(--ink-soft);margin-bottom:8px">${leadsPool.length} líderes y ${follsPool.length} followers listos para sortear.</div>
          <div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap">
            <label style="font-size:12px">Nombre de la fase: <input id="jj-phase-label-${nivel.replace(/\s/g,'_')}" value="${phaseLabel}" style="padding:4px 8px;border:1px solid var(--line);border-radius:6px;font-size:12px;background:var(--bg);color:var(--ink);width:120px"></label>
            <button onclick="jjStartSorteo('${nivelKey}')" style="padding:7px 16px;background:var(--wine);color:#fff;border:none;border-radius:8px;font-size:13px;cursor:pointer;font-weight:600">🔀 Sortear ${phaseLabel}</button>
          </div>
          <div id="jj-status-${nivelKey}" style="font-size:12px;color:var(--ink-soft);margin-top:6px"></div>
        </div>`;
      } else {
        html+=`<div style="font-size:12px;color:var(--ink-soft);margin-top:8px">Faltan líderes o followers para hacer el sorteo.</div>`;
      }
    }

    if(isAdmin&&phases.length){
      const nivelKey=nivel.replace(/"/g,'&quot;');
      html+=`<div style="margin-top:8px"><button onclick="jjDeleteLastPhase('${nivelKey}')" style="font-size:11px;padding:4px 10px;background:transparent;border:1px solid #e3b8b0;color:#a00;border-radius:6px;cursor:pointer">✕ Borrar última fase de ${nivel}</button></div>`;
    }

    html+='</div>';
  });

  html+='</div>';
  d.innerHTML=html;
}

async function jjStartSorteo(nivel,_isFinalPhase){
  const st=document.getElementById('jj-status-'+nivel);
  if(st)st.textContent='⏳ Sorteando...';
  const g=jjGetGroup(nivel);
  const lastPhase=g.phases[g.phases.length-1];
  let leadsPool,follsPool;
  if(lastPhase){
    leadsPool=(lastPhase.advancedLeads||[]).map(n=>({nombre:n,dni:''}));
    follsPool=(lastPhase.advancedFolls||[]).map(n=>({nombre:n,dni:''}));
  } else {
    const byLevel={};
    _JJ_INSC.forEach(ins=>{
      (ins.rows||[]).forEach(r=>{
        const niv=r['Nivel']||r['Grupo de edad']||'Sin nivel';
        if(niv!==nivel)return;
        const rol=r['Rol']||'Leader';
        if(!byLevel[niv])byLevel[niv]={leaders:[],followers:[]};
        const p={nombre:r['Nombre']||r['Nombre (leader)']||ins.resumen,dni:r['DNI']||r['DNI del leader']||''};
        if(rol==='Follower')byLevel[niv].followers.push(p);
        else byLevel[niv].leaders.push(p);
      });
    });
    const grp=byLevel[nivel]||{leaders:[],followers:[]};
    leadsPool=grp.leaders;follsPool=grp.followers;
  }
  if(!leadsPool.length||!follsPool.length){if(st)st.textContent='⚠ Faltan líderes o followers.';return;}
  const labelEl=document.getElementById('jj-phase-label-'+nivel.replace(/\s/g,'_'));
  const phaseLabel=labelEl?labelEl.value.trim()||('Fase '+(g.phases.length+1)):('Fase '+(g.phases.length+1));
  const phaseId=nivel.replace(/\s/g,'_')+'_p'+(g.phases.length+1)+'_'+Date.now();
  const pairs=jjShufflePairs(leadsPool,follsPool);
  const phase={id:phaseId,label:phaseLabel,pairs,status:'open',advancedLeads:[],advancedFolls:[],isFinal:_isFinalPhase||false};
  g.phases.push(phase);
  // Asignar dorsales a todos los participantes de esta fase
  const allParts=[...leadsPool,...follsPool];
  jjAssignDorsals(g,allParts);
  await saveJJRoundsDB();
  if(typeof LAST_SCH!=='undefined')LAST_SCH=null;
  render();
  _paneJJLoad();
}

async function jjSaveHeatConfig(){
  const sz=parseInt(document.getElementById('jj-heat-size')?.value)||6;
  const ds=parseInt(document.getElementById('jj-dorsal-start')?.value)||1;
  _JJ_ROUNDS.heatSize=sz;
  _JJ_ROUNDS.dorsalStart=ds;
  await saveJJRoundsDB();
}

async function jjLoadAndShowResults(nivel,phaseId,btn){
  if(btn){btn.disabled=true;btn.textContent='⏳ Cargando votos...';}
  try{
    const names=judgeNames();
    const allVotes={};
    for(let i=0;i<names.length;i++){
      try{const raw=await dbGetFile('votes/judge-'+i+'.json');if(raw){const v=JSON.parse(raw)||{};allVotes[i]=v;}}catch(e){}
    }
    const nJudges=Object.keys(allVotes).length;
    const g=jjGetGroup(nivel);
    const phase=(g.phases||[]).find(p=>p.id===phaseId);
    if(!phase){if(btn){btn.disabled=false;btn.textContent='🏆 Obtener resultados';}return;}
    const isFinal=!!phase.isFinal;
    const leads=[...new Set((phase.pairs||[]).map(p=>p.lead))];
    const folls=[...new Set((phase.pairs||[]).map(p=>p.foll))];
    const sums={};const cnt={};
    Object.values(allVotes).forEach(jvMap=>{
      Object.values(jvMap).forEach(hv=>{
        if(typeof hv!=='object'||!hv)return;
        Object.entries(hv).forEach(([pid,val])=>{
          if(isFinal){
            // Final: posición 1-N; menor suma = mejor
            if(val>=1){sums[pid]=(sums[pid]||0)+val;cnt[pid]=(cnt[pid]||0)+1;}
          }else{
            // Clasificatoria: val=10(Sí), -1(No→0pts), 4.x(Alt); mayor suma = mejor
            if(typeof val==='number'){
              const pts=val===-1?0:val;
              sums[pid]=(sums[pid]||0)+pts;cnt[pid]=(cnt[pid]||0)+1;
            }
          }
        });
      });
    });
    const thStyle='padding:3px 6px;color:var(--ink-soft);font-weight:600;font-size:11px;text-align:left;border-bottom:1px solid var(--line)';
    const tdStyle='padding:3px 6px;font-size:12px;border-bottom:1px solid var(--strip)';
    const tdCStyle='padding:3px 6px;font-size:12px;text-align:center;border-bottom:1px solid var(--strip)';
    const mkTable=(rows,sumLabel,ascending)=>{
      const sorted=[...rows].sort((a,b)=>ascending?(a.sum??9999)-(b.sum??9999):(b.sum??-9999)-(a.sum??-9999));
      let t=`<table style="width:100%;border-collapse:collapse"><thead><tr><th style="${thStyle}">#</th><th style="${thStyle}">Dor.</th><th style="${thStyle}">Nombre</th><th style="${thStyle}">${sumLabel}</th><th style="${thStyle}">Prom.</th></tr></thead><tbody>`;
      sorted.forEach((r,i)=>{
        const hasVote=r.sum!=null;
        const medal=i===0?'🥇':i===1?'🥈':i===2?'🥉':'';
        const bg=hasVote?(i<3?'background:var(--strip)':''):'opacity:0.5';
        t+=`<tr style="${bg}"><td style="${tdCStyle}">${medal||String(i+1)}</td><td style="${tdCStyle};font-weight:700">${r.dor||'—'}</td><td style="${tdStyle}">${r.nombre}</td><td style="${tdCStyle}">${hasVote?r.sum:'—'}</td><td style="${tdCStyle}">${hasVote&&r.cnt>0?(r.sum/r.cnt).toFixed(1):'—'}</td></tr>`;
      });
      t+=`</tbody></table>`;return t;
    };
    const div=document.getElementById('jj-res-'+phaseId);
    if(div){
      if(isFinal){
        // Final: mostrar parejas, menor suma posiciones = mejor
        const pairRows=leads.map(n=>{
          const pid='jj_l_'+nameKey(n);
          const pair=(phase.pairs||[]).find(p=>p.lead===n);
          const s=sums[pid],c=cnt[pid]||0;
          return{nombre:n+(pair?' + '+pair.foll:''),dor:(g.dorsals&&g.dorsals[nameKey(n)])||'',sum:s!=null?s:null,cnt:c};
        });
        div.innerHTML=`<div style="margin:8px 0;padding:10px 12px;background:var(--card);border:1px solid var(--line);border-radius:10px"><div style="font-size:11px;font-weight:700;color:var(--ink-soft);margin-bottom:8px">📊 Ranking FINAL — ${nJudges} juez${nJudges!==1?'ces':''} · Skating (menor Σ posiciones = mejor)</div>${mkTable(pairRows,'Σ pos.',true)}</div>`;
      }else{
        // Clasificatoria: líderes y followers por separado, mayor suma puntos = mejor
        const mkQualRank=(ns,prefix)=>ns.map(n=>({nombre:n,dor:(g.dorsals&&g.dorsals[nameKey(n)])||'',sum:sums[prefix+nameKey(n)]!=null?sums[prefix+nameKey(n)]:null,cnt:cnt[prefix+nameKey(n)]||0}));
        const rankLeads=mkQualRank(leads,'jj_l_');
        const rankFolls=mkQualRank(folls,'jj_f_');
        div.innerHTML=`<div style="margin:8px 0;padding:10px 12px;background:var(--card);border:1px solid var(--line);border-radius:10px"><div style="font-size:11px;font-weight:700;color:var(--ink-soft);margin-bottom:8px">📊 Ranking Clasificatoria — ${nJudges} juez${nJudges!==1?'ces':''} · Σ puntos (mayor = mejor)</div><div style="display:flex;gap:16px;flex-wrap:wrap"><div style="flex:1;min-width:180px"><div style="font-size:11px;font-weight:700;color:var(--wine);margin-bottom:4px">🕺 Líderes</div>${mkTable(rankLeads,'Σ pts.',false)}</div><div style="flex:1;min-width:180px"><div style="font-size:11px;font-weight:700;color:var(--wine);margin-bottom:4px">💃 Followers</div>${mkTable(rankFolls,'Σ pts.',false)}</div></div></div>`;
      }
    }
    if(btn){btn.disabled=false;btn.textContent='🔄 Actualizar resultados';}
  }catch(e){
    if(btn){btn.disabled=false;btn.textContent='🏆 Obtener resultados';}
    alert('Error al obtener resultados: '+e.message);
  }
}
async function jjSaveAdvanced(nivel){
  const g=jjGetGroup(nivel);
  const phase=g.phases.find(p=>p.status==='open');
  if(!phase)return;
  const leads=[...document.querySelectorAll('.jj-adv-lead[data-level="'+nivel+'"]:checked')].map(el=>el.dataset.name);
  const folls=[...document.querySelectorAll('.jj-adv-foll[data-level="'+nivel+'"]:checked')].map(el=>el.dataset.name);
  phase.advancedLeads=leads;
  phase.advancedFolls=folls;
  await saveJJRoundsDB();
  const st=document.getElementById('jj-status-'+nivel);
  if(st)st.textContent='✓ Guardado. '+leads.length+' líderes y '+folls.length+' followers avanzan.';
}

async function jjClosePhaseAndSorteo(nivel){
  await jjSaveAdvanced(nivel);
  const g=jjGetGroup(nivel);
  const phase=g.phases.find(p=>p.status==='open');
  if(!phase)return;
  if(!phase.advancedLeads.length&&!phase.advancedFolls.length){
    const st=document.getElementById('jj-status-'+nivel);
    if(st)st.textContent='⚠ Seleccioná quién avanza antes de cerrar la fase.';
    return;
  }
  const isFinalCb=document.getElementById('jj-is-final-'+nivel.replace(/\s/g,'_'));
  const nextIsFinal=!!(isFinalCb&&isFinalCb.checked);
  phase.status='closed';
  await saveJJRoundsDB();
  await jjStartSorteo(nivel,nextIsFinal);
}

async function jjDeleteLastPhase(nivel){
  if(!confirm('¿Borrar la última fase de '+nivel+'? Esta acción no se puede deshacer.'))return;
  const g=jjGetGroup(nivel);
  if(!g.phases.length)return;
  g.phases.pop();
  await saveJJRoundsDB();
  if(typeof LAST_SCH!=='undefined')LAST_SCH=null;
  render();
  _paneJJLoad();
}

