function regUpdateJJPrice(){
  const rol=document.querySelector('input[name="reg_jj_rol"]:checked');
  const price=rol&&rol.value==='Follower'?REG_PRICE_BASE_JJ_FOLLOWER:REG_PRICE_BASE_JJ_LEADER;
  const el=document.getElementById('jj-price-display');
  if(el)el.textContent='Total: '+regPriceFmt(price);
}

async function regSubmitJackJill(){
  const v=id=>(document.getElementById(id)||{}).value?.trim()||'';
  const ctEmail=(document.getElementById('reg_contact_email')||{}).value?.trim()||'';
  const ctTel=(document.getElementById('reg_contact_tel')||{}).value?.trim()||'';
  if(!ctEmail||!ctTel){regSetStatus('⚠ Completá mail y teléfono de contacto.',true);return;}
  const nombre=v('reg_jj_nombre');
  if(!nombre){regSetStatus('⚠ Ingresá tu nombre.',true);return;}
  const nivel=v('reg_jj_nivel');
  if(!nivel){regSetStatus('⚠ Elegí tu nivel.',true);return;}
  const rolEl=document.querySelector('input[name="reg_jj_rol"]:checked');
  const rol=rolEl?rolEl.value:'Leader';
  const row={
    'Nombre':nombre,
    'DNI':v('reg_jj_dni')||null,
    'Seleccione su escuela':v('reg_jj_esc')||null,
    'Rol':rol,
    'Nivel':nivel,
    'Email de contacto':ctEmail,
    'Teléfono de contacto':ctTel
  };
  const resumen=nombre+' — J&J '+rol+' '+nivel;
  regSetStatus('⏳ Enviando...',false);
  try{
    const pin=genRegPin();
    const{error}=await sb.from('inscripciones').insert({tipo:'jackjill',resumen,rows:[row],pin});
    if(error)throw new Error(error.message);
    regShowPinBanner(pin);
    regSendConfirmationEmail(ctEmail,'jackjill',resumen,[row],pin);
    regSetStatus('',false);
    regClearJackJill();
  }catch(e){regSetStatus('⚠ No se pudo enviar: '+e.message,true);}
}

function regClearJackJill(){
  ['reg_jj_nombre','reg_jj_dni','reg_jj_esc'].forEach(id=>{const el=document.getElementById(id);if(el)el.value='';});
  const nivel=document.getElementById('reg_jj_nivel');if(nivel)nivel.value='';
  const leaderRol=document.getElementById('reg_jj_rol_leader');if(leaderRol)leaderRol.checked=true;
}
// ========= FIN JACK & JILL =========

// llega a 10, precio base. Los Challenge sueltos usan su propio escalón (2 Challenge) + resto a base.
// NOTA: estos valores son los de DEFAULT (los históricos). Son mutables (let, no const) porque el
// admin puede sobreescribirlos en runtime desde el panel "Configuración → Inscripciones online →
// Precios de inscripción" (ver REG_PRICE_DEFAULTS / applyRegPricesCfg / loadRegPricesIntoMemory más
// abajo, que leen/escriben 'reg-prices.json' en kv_store).
let REG_PRICE_BASE_M=100000,REG_PRICE_BASE_S=17000,REG_PRICE_BASE_C=35000;
// Excepción Solista: un Multidance inscripto desde la solapa "Solista" (una sola persona, no
// pareja) sale más barato que el de Pareja. Sólo afecta el precio base del Multidance — Single
// Dance y Challenge de Solista siguen cobrándose igual que el resto (REG_PRICE_BASE_S/C). Además,
// los Multidance de Solista NUNCA entran en los escalones de combo (REG_PRICE_MD_TIERS: esos
// combos están pensados/tarifados para 2 personas) — ver regPriceBreakdown(...,soloMD).
let REG_PRICE_BASE_M_SOLO=70000;
let REG_PRICE_BASE_WEST=50000;
let REG_PRICE_BASE_JJ_LEADER=30000,REG_PRICE_BASE_JJ_FOLLOWER=30000;
// Escalones de multidance, del más alto/específico al más bajo (orden de prioridad de búsqueda).
let REG_PRICE_MD_TIERS=[
  {m:5,c:1,price:650000,freeS:10,label:'5 Multidance + 1 Challenge + 10 Single Dances (combo)'},
  {m:4,c:0,price:500000,freeS:10,label:'4 Multidance + 10 Single Dances (combo)'},
  {m:2,c:0,price:280000,freeS:10,label:'2 Multidance + 10 Single Dances (combo)'},
  {m:1,c:0,price:200000,freeS:10,label:'1 Multidance + 10 Single Dances (combo)'},
];
// Escalones de Single Dances sueltos (solo se usan cuando no hay multidance), del más alto al más bajo.
let REG_PRICE_S_TIERS=[
  {s:30,price:350000,label:'30 Single Dances (combo)'},
  {s:20,price:260000,label:'20 Single Dances (combo)'},
  {s:10,price:130000,label:'10 Single Dances (combo)'},
];
// Escalón de Challenges sueltos.
let REG_PRICE_C_TIERS=[
  {c:2,price:40000,label:'2 Challenge (combo)'},
];
// Snapshot congelado de los valores de arriba ANTES de que cualquier config guardada los pise —
// permite el botón "Restaurar valores por defecto" en el panel admin sin tener que hardcodear los
// números dos veces.
const REG_PRICE_DEFAULTS={
  baseM:REG_PRICE_BASE_M,baseS:REG_PRICE_BASE_S,baseC:REG_PRICE_BASE_C,baseMSolo:REG_PRICE_BASE_M_SOLO,baseWest:REG_PRICE_BASE_WEST,jjLeader:REG_PRICE_BASE_JJ_LEADER,jjFollower:REG_PRICE_BASE_JJ_FOLLOWER,
  mdTiers:REG_PRICE_MD_TIERS.map(t=>t.price),
  sTiers:REG_PRICE_S_TIERS.map(t=>t.price),
  cTiers:REG_PRICE_C_TIERS.map(t=>t.price)
};
function regPriceFmt(n){return '$'+Math.round(n).toLocaleString('es-AR');}
// Calcula el desglose determinístico (escalones fijos, no búsqueda de mínimo costo).
function regPriceBreakdown(m,s,c,soloMD){
  let mm=m,ss=s,cc=c;
  const items=[];
  // 1) Escalón de multidance (+Challenge si aplica): el más alto que alcanza. Sólo aplica si
  // además se llega a la cantidad de Singles que ese escalón incluye gratis (freeS) — si hay
  // menos Singles que eso, no corresponde el combo (p.ej. 4 Multidance + 5 Singles NO debe
  // tomar el combo "4 Multidance + 10 Singles", esos 5 Singles van a precio suelto).
  // Excepción Solista (soloMD=true): nunca entra en estos escalones — están tarifados para 2
  // personas (pareja). El Multidance de Solista se cobra siempre suelto, a REG_PRICE_BASE_M_SOLO.
  const mdTier=(!soloMD&&ss>0)?REG_PRICE_MD_TIERS.find(t=>mm>=t.m&&cc>=t.c&&ss>=t.freeS):null;
  let freeS=0;
  if(mdTier){
    items.push({label:mdTier.label,price:mdTier.price});
    mm-=mdTier.m;cc-=mdTier.c;
    freeS=mdTier.freeS;
  }
  // 2) Si no se aplicó escalón de multidance, probar escalera de Singles sueltos. Esta sí aplica
  // igual para Solista: es un descuento por cantidad de Single Dances, no depende de si hay pareja.
  if(!mdTier){
    const sTier=REG_PRICE_S_TIERS.find(t=>ss>=t.s);
    if(sTier){items.push({label:sTier.label,price:sTier.price});ss-=sTier.s;}
  }else{
    ss-=Math.min(ss,freeS);
  }
  // 3) Escalón de Challenges sueltos sobre lo que quede de cc (también igual para Solista).
  const cTier=REG_PRICE_C_TIERS.find(t=>cc>=t.c);
  if(cTier){items.push({label:cTier.label,price:cTier.price});cc-=cTier.c;}
  // 4) Resto a precio base. El Multidance de Solista usa su propia base (más barata).
  if(mm>0)items.push({label:mm+' Multidance'+(mm>1?'s':'')+(soloMD?' (Solista)':''),price:mm*(soloMD?REG_PRICE_BASE_M_SOLO:REG_PRICE_BASE_M)});
  if(ss>0)items.push({label:ss+' Single Dance'+(ss>1?'s':''),price:ss*REG_PRICE_BASE_S});
  if(cc>0)items.push({label:cc+' Challenge'+(cc>1?'s':''),price:cc*REG_PRICE_BASE_C});
  const total=items.reduce((a,it)=>a+it.price,0);
  return {items,total};
}
function regPriceBoxHTML(m,s,c,soloMD){
  if(m<=0&&s<=0&&c<=0)return `<div style="background:rgba(0,0,0,.025);border:1px dashed var(--line);border-radius:10px;padding:12px 14px;margin:14px 0;font-size:12.5px;color:var(--ink-soft)">Elegí un nivel/Open, Single Dance o Challenge para ver el monto a abonar.</div>`;
  const {items,total}=regPriceBreakdown(m,s,c,soloMD);
  const rows=items.map(it=>`<div style="display:flex;justify-content:space-between;gap:10px;font-size:13px;padding:3px 0"><span>${it.label}</span><span style="white-space:nowrap">${regPriceFmt(it.price)}</span></div>`).join('');
  return `<div style="background:rgba(0,0,0,.025);border:1px solid var(--line);border-radius:10px;padding:14px;margin:14px 0">
    <div style="font-size:12px;font-weight:700;color:var(--ink-soft);text-transform:uppercase;letter-spacing:.05em;margin-bottom:6px">Monto a abonar</div>
    ${rows}
    <div style="display:flex;justify-content:space-between;font-size:15px;font-weight:800;color:var(--wine);border-top:1px solid var(--line);margin-top:6px;padding-top:6px"><span>Total</span><span>${regPriceFmt(total)}</span></div>
  </div>`;
}
// ----- Precios configurables por el admin (ver 'reg-prices.json' en kv_store, panel admin
// "Configuración → Inscripciones online → Precios de inscripción") -----
// Sólo los MONTOS son editables: la estructura de los combos (qué cantidades incluyen) queda fija
// en REG_PRICE_MD_TIERS/S_TIERS/C_TIERS (mismo orden/longitud siempre), así que el cfg guardado es
// simplemente un array paralelo de precios por escalón + los 3 precios base.
function applyRegPricesCfg(cfg){
  if(!cfg)return;
  const okNum=v=>typeof v==='number'&&isFinite(v)&&v>=0;
  if(okNum(cfg.baseM))REG_PRICE_BASE_M=cfg.baseM;
  if(okNum(cfg.baseS))REG_PRICE_BASE_S=cfg.baseS;
  if(okNum(cfg.baseC))REG_PRICE_BASE_C=cfg.baseC;
  if(okNum(cfg.baseMSolo))REG_PRICE_BASE_M_SOLO=cfg.baseMSolo;
  if(okNum(cfg.baseWest))REG_PRICE_BASE_WEST=cfg.baseWest;
  if(okNum(cfg.jjLeader))REG_PRICE_BASE_JJ_LEADER=cfg.jjLeader;
  if(okNum(cfg.jjFollower))REG_PRICE_BASE_JJ_FOLLOWER=cfg.jjFollower;
  if(Array.isArray(cfg.mdTiers))cfg.mdTiers.forEach((p,i)=>{if(REG_PRICE_MD_TIERS[i]&&okNum(p))REG_PRICE_MD_TIERS[i].price=p;});
  if(Array.isArray(cfg.sTiers))cfg.sTiers.forEach((p,i)=>{if(REG_PRICE_S_TIERS[i]&&okNum(p))REG_PRICE_S_TIERS[i].price=p;});
  if(Array.isArray(cfg.cTiers))cfg.cTiers.forEach((p,i)=>{if(REG_PRICE_C_TIERS[i]&&okNum(p))REG_PRICE_C_TIERS[i].price=p;});
}
// Trae 'reg-prices.json' y lo aplica en memoria. Se llama tanto desde el formulario público
// (renderInscripcionPublica) como desde la solapa Pagos (loadPagosCache), para que ambos lados
// cobren siempre lo mismo. Si no hay nada guardado, quedan los valores por defecto.
async function loadRegPricesIntoMemory(){
  try{
    const raw=await dbGetFile('reg-prices.json');
    if(raw)applyRegPricesCfg(JSON.parse(raw));
  }catch(e){/* si falla la lectura, se usan los valores por defecto */}
}
function regPriceTierRowsHTML(prefix,tiers){
  return tiers.map((t,i)=>`<div class="ctl edit-only" style="display:flex;align-items:center;gap:8px"><label for="${prefix}_${i}" style="flex:1;font-size:11.5px;color:var(--ink-soft);font-weight:400">${_escEd(t.label)}</label><input type="number" id="${prefix}_${i}" min="0" step="1000" style="width:120px;flex-shrink:0;box-sizing:border-box;padding:6px 8px;border:1px solid var(--line);border-radius:8px;font-size:12px;background:var(--bg);color:var(--ink)"></div>`).join('');
}
function regPricesFillInputs(){
  const el=id=>document.getElementById(id);
  if(el('rpc_baseM'))el('rpc_baseM').value=REG_PRICE_BASE_M;
  if(el('rpc_baseS'))el('rpc_baseS').value=REG_PRICE_BASE_S;
  if(el('rpc_baseC'))el('rpc_baseC').value=REG_PRICE_BASE_C;
  if(el('rpc_baseMSolo'))el('rpc_baseMSolo').value=REG_PRICE_BASE_M_SOLO;
  if(el('rpc_baseWest'))el('rpc_baseWest').value=REG_PRICE_BASE_WEST;
  if(el('rpc_baseJJLeader'))el('rpc_baseJJLeader').value=REG_PRICE_BASE_JJ_LEADER;
  if(el('rpc_baseJJFollower'))el('rpc_baseJJFollower').value=REG_PRICE_BASE_JJ_FOLLOWER;
  REG_PRICE_MD_TIERS.forEach((t,i)=>{if(el('rpc_md_'+i))el('rpc_md_'+i).value=t.price;});
  REG_PRICE_S_TIERS.forEach((t,i)=>{if(el('rpc_s_'+i))el('rpc_s_'+i).value=t.price;});
  REG_PRICE_C_TIERS.forEach((t,i)=>{if(el('rpc_c_'+i))el('rpc_c_'+i).value=t.price;});
}
async function loadRegPricesConfig(){
  const st=document.getElementById('regPricesConfigStatus');
  const mdList=document.getElementById('rpc_mdList'),sList=document.getElementById('rpc_sList'),cList=document.getElementById('rpc_cList');
  if(!mdList||!sList||!cList)return;
  mdList.innerHTML=regPriceTierRowsHTML('rpc_md',REG_PRICE_MD_TIERS);
  sList.innerHTML=regPriceTierRowsHTML('rpc_s',REG_PRICE_S_TIERS);
  cList.innerHTML=regPriceTierRowsHTML('rpc_c',REG_PRICE_C_TIERS);
  if(st)st.textContent='Cargando...';
  try{
    await loadRegPricesIntoMemory();
    regPricesFillInputs();
    if(st)st.textContent='Los cambios se aplican apenas guardás: impactan en el formulario público y en la solapa Pagos.';
  }catch(e){
    if(st)st.textContent='⚠ '+e.message;
  }
}
function restoreRegPricesDefaults(){
  applyRegPricesCfg({baseM:REG_PRICE_DEFAULTS.baseM,baseS:REG_PRICE_DEFAULTS.baseS,baseC:REG_PRICE_DEFAULTS.baseC,baseMSolo:REG_PRICE_DEFAULTS.baseMSolo,baseWest:REG_PRICE_DEFAULTS.baseWest,jjLeader:REG_PRICE_DEFAULTS.jjLeader,jjFollower:REG_PRICE_DEFAULTS.jjFollower,mdTiers:REG_PRICE_DEFAULTS.mdTiers,sTiers:REG_PRICE_DEFAULTS.sTiers,cTiers:REG_PRICE_DEFAULTS.cTiers});
  regPricesFillInputs();
  const st=document.getElementById('regPricesConfigStatus');
  if(st)st.textContent='Valores por defecto cargados en el formulario. Tocá "Guardar" para aplicarlos.';
}
function regPricesReadCfg(){
  const num=id=>{const el=document.getElementById(id);const v=parseFloat(el&&el.value);return (isFinite(v)&&v>=0)?Math.round(v):null;};
  return {
    baseM:num('rpc_baseM'),baseS:num('rpc_baseS'),baseC:num('rpc_baseC'),baseMSolo:num('rpc_baseMSolo'),baseWest:num('rpc_baseWest'),jjLeader:num('rpc_baseJJLeader'),jjFollower:num('rpc_baseJJFollower'),
    mdTiers:REG_PRICE_MD_TIERS.map((t,i)=>num('rpc_md_'+i)),
    sTiers:REG_PRICE_S_TIERS.map((t,i)=>num('rpc_s_'+i)),
    cTiers:REG_PRICE_C_TIERS.map((t,i)=>num('rpc_c_'+i))
  };
}
async function saveRegPricesConfig(){
  const st=document.getElementById('regPricesConfigStatus');
  const cfg=regPricesReadCfg();
  const allOk=cfg.baseM!=null&&cfg.baseS!=null&&cfg.baseC!=null&&cfg.baseMSolo!=null&&cfg.baseWest!=null&&cfg.jjLeader!=null&&cfg.jjFollower!=null&&!cfg.mdTiers.some(p=>p==null)&&!cfg.sTiers.some(p=>p==null)&&!cfg.cTiers.some(p=>p==null);
  if(!allOk){
    if(st)st.textContent='⚠ No se guardó: revisá que todos los montos sean números válidos (0 o mayores).';
    return;
  }
  if(st)st.textContent='Guardando...';
  const r=await dbUpload(JSON.stringify(cfg),true,'reg-prices.json');
  if(r.ok){
    applyRegPricesCfg(cfg);
    if(st)st.textContent='✓ Guardado. Ya se está cobrando con los nuevos montos.';
  }else{
    if(st)st.textContent='⚠ Error: '+r.msg;
  }
}
// ----- Cálculo de precio/detalle a partir de filas YA GUARDADAS (admin · solapa Pagos) -----
// A diferencia de regCountsPareja/regCountsSolista/etc. (que leen el DOM del formulario en vivo),
// estas funciones recalculan m/s/c directamente desde las filas canónicas guardadas en Supabase
// ('inscripciones.rows'), para poder mostrar cuánto debe pagar cada inscripción ya enviada.
// Si la inscripción quedó tageada para AABD y Privada a la vez (regBuildRowsForComps duplica las
// filas por competencia), hay que elegir UN solo conjunto — el cobro es uno solo por inscripción,
// igual que en la calculadora en vivo (que no duplica el monto por tildar ambas competencias).
function regPickCompRows(rows){
  rows=rows||[];
  const privRows=rows.filter(r=>(r['Competencia']||'').includes('Privada'));
  const aabdRows=rows.filter(r=>(r['Competencia']||'').includes('AABD'));
  return privRows.length?privRows:(aabdRows.length?aabdRows:rows);
}
function regCountsFromRows(rows){
  let m=0,s=0,c=0;
  regPickCompRows(rows).forEach(row=>{
    const mod=row['Elegir modalidad'];
    if(mod==='International Style'||mod==='American Style'||mod==='Sociales'){
      m++;
    }else if(mod==='Single Dance'){
      Object.keys(row).forEach(k=>{if(k.indexOf('Ritmos (')===0&&row[k])s+=row[k];});
    }else if(mod==='Challenge'){
      Object.keys(row).forEach(k=>{if(k.indexOf('Ritmos (')===0&&row[k])c++;});
    }
  });
  return {m,s,c};
}
// Línea legible de detalle para una fila canónica individual (qué bailó, en qué nivel/ritmos).
function regRowSummaryLine(row){
  const mod=row['Elegir modalidad'];
  const ritmoNames=()=>Object.keys(row).filter(k=>k.indexOf('Ritmos (')===0&&row[k]).map(k=>{
    const mt=k.match(/\[(.+)\]$/);const name=mt?mt[1]:k;
    return row[k]>1?`${name} x${row[k]}`:name;
  });
  if(mod==='Single Dance')return 'Single Dance: '+(ritmoNames().join(', ')||'—')+(row['Contested']?` (${row['Contested']})`:'');
  if(mod==='Challenge')return 'Challenge: '+(ritmoNames().join(', ')||'—');
  if(mod==='International Style'||mod==='American Style'||mod==='Sociales'){
    const styles=['Standard','Latin','Smooth','Rhythm','SocialLatino','SocialArgentino','SocialAmericano'];
    const parts=styles.filter(st=>row[st+' categoria']).map(st=>`${st}: ${row[st+' categoria']}`);
    return mod+(parts.length?' — '+parts.join(', '):'');
  }
  if(row['Elija la especialidad']==='Equipo coreográfico')return 'Equipo: '+(row['Nombre del equipo coreográfico']||'')+(row['Nombre de la coreografía']?' · "'+row['Nombre de la coreografía']+'"':'');
  return mod||'—';
}
// Detalle completo (HTML) de una inscripción: una línea por cada fila canónica relevante.
function regRowsSummaryHTML(rows){
  const use=regPickCompRows(rows);
  if(!use.length)return '<span style="color:var(--ink-soft)">—</span>';
  return use.map(r=>`<div>${regRowSummaryLine(r)}</div>`).join('');
}
// Suma de unidades de Single Dance (cada baile tildado cuenta su cantidad, no solo 1) para un
// conjunto de grupos+prefijo — mismo esquema de ids que regChecklistHTML/regReadChecklist.
function regCountSinglesFor(groups,prefix){
  let total=0;
  groups.forEach(g=>{
    regDanceList(g).forEach(dn=>{
      const fid=prefix+'_'+g+'_'+dn.replace(/[^a-zA-Z0-9]/g,'');
      const chk=document.getElementById(fid);
      if(chk&&chk.checked){
        const nEl=document.getElementById(fid+'_n');
        total+=parseInt(nEl&&nEl.value)||1;
      }
    });
  });
  return total;
}
function regCountsPareja(){
  const chk=id=>{const el=document.getElementById(id);return !!(el&&el.checked);};
  const val=id=>{const el=document.getElementById(id);return el?el.value:'';};
  const modEl=document.querySelector('input[name="reg_p_mod"]:checked');
  const mod=modEl?modEl.value:'international';
  const american=mod==='american',sociales=mod==='sociales';
  // "también Open" suma OTRO multidance (es aditivo, no alternativo): si el estilo tiene
  // Nivel Y Open tildados, son 2 multidance, no 1.
  let m=0,s=0;
  if(!american&&!sociales){
    if(val('reg_p_stCat'))m++;if(chk('reg_p_stOpen'))m++;
    if(val('reg_p_ltCat'))m++;if(chk('reg_p_ltOpen'))m++;
    if(chk('reg_p_singles_int_chk'))s+=regCountSinglesFor(['INT-ST','INT-LT'],'p');
  } else if(american){
    if(val('reg_p_smCat'))m++;if(chk('reg_p_smOpen'))m++;
    if(val('reg_p_rhCat'))m++;if(chk('reg_p_rhOpen'))m++;
    if(chk('reg_p_singles_am_chk'))s+=regCountSinglesFor(['AM-SM','AM-RH'],'p');
  } else {
    if(val('reg_p_slCat'))m++;if(chk('reg_p_slOpen'))m++;
    if(val('reg_p_sgCat'))m++;if(chk('reg_p_sgOpen'))m++;
    if(val('reg_p_saCat'))m++;if(chk('reg_p_saOpen'))m++;
    if(chk('reg_p_singles_soc_chk'))s+=regCountSinglesFor(['SOC-LA','SOC-AR','SOC-AM'],'p');
  }
  const c=chk('reg_p_chal_chk')?Object.keys(regReadChallengeChecklist('reg_p_chal')).length:0;
  return {m,s,c};
}
function regCountsSolista(){
  let m=0,s=0;
  ['s1','s2'].forEach(px=>{
    const styleEl=document.getElementById('reg_'+px+'_style');
    const style=styleEl?styleEl.value:'';
    if(!style)return;
    const nivEl=document.getElementById('reg_'+px+'_niv'),openEl=document.getElementById('reg_'+px+'_open');
    const cat=nivEl?nivEl.value:'',open=!!(openEl&&openEl.checked);
    if(!cat&&!open)return;
    // "también Open" suma OTRO multidance: Nivel y Open son contribuciones independientes.
    if(cat)m++;
    if(open)m++;
    const singlesChk=document.getElementById('reg_'+px+'_singles_chk');
    if(singlesChk&&singlesChk.checked){
      const group=STYLE2GROUP_REG[style];
      if(group)s+=regCountSinglesFor([group],px);
    }
  });
  const chalChk=document.getElementById('reg_s_chal_chk');
  const c=(chalChk&&chalChk.checked)?Object.keys(regReadChallengeChecklist('reg_s_chal')).length:0;
  return {m,s,c};
}
function regCountsSynchro(){
  let m=0,s=0;
  // "también Open" suma OTRO multidance: Nivel y Open son contribuciones independientes.
  const rhNiv=document.getElementById('reg_y_rhNiv').value,rhOpen=document.getElementById('reg_y_rhOpen').checked;
  if(rhNiv||rhOpen){
    if(rhNiv)m++;if(rhOpen)m++;
    if(document.getElementById('reg_y_rh_singles_chk').checked)s+=regCountSinglesFor(['AM-RH'],'y_rh');
  }
  const ltNiv=document.getElementById('reg_y_ltNiv').value,ltOpen=document.getElementById('reg_y_ltOpen').checked;
  if(ltNiv||ltOpen){
    if(ltNiv)m++;if(ltOpen)m++;
    if(document.getElementById('reg_y_lt_singles_chk').checked)s+=regCountSinglesFor(['INT-LT'],'y_lt');
  }
  return {m,s,c:0};
}
function regCountsSingles(){
  const s=regCountSinglesFor(['INT-ST','INT-LT','AM-SM','AM-RH','SOC-LA','SOC-AR','SOC-AM'],'si');
  return {m:0,s,c:0};
}
function regCountsChallenge(){
  return {m:0,s:0,c:Object.keys(regReadChallengeChecklist('reg_ch_chal')).length};
}
// Recalcula y repinta el cuadro de precio de la sección actualmente visible. Se llama tanto desde
// regSwitchTipo (al cambiar de sección) como desde los listeners de input/change delegados en cada
// contenedor #reg-sec-* (ver renderInscripcionPublica), así que se actualiza en vivo a medida que
// se completa el formulario.
function regCountsParejaWest(){return {m:0,s:0,c:0,flat:1};}
function regRecalcCostos(){
  const fns={pareja:regCountsPareja,solista:regCountsSolista,synchro:regCountsSynchro,singles:regCountsSingles,challenge:regCountsChallenge};
  Object.keys(fns).forEach(tipo=>{
    const sec=document.getElementById('reg-sec-'+tipo);
    const box=document.getElementById('reg-price-'+tipo);
    if(!sec||!box||sec.style.display==='none')return;
    const {m,s,c}=fns[tipo]();
    box.innerHTML=regPriceBoxHTML(m,s,c,tipo==='solista');
  });
  // Pareja WEST: precio fijo por inscripción
  const wSec=document.getElementById('reg-sec-parejawest');
  const wBox=document.getElementById('reg-price-parejawest');
  if(wSec&&wBox&&wSec.style.display!=='none'){
    wBox.innerHTML='<div style="background:var(--strip);border-radius:9px;padding:10px 14px;margin-top:8px;font-size:13px;font-weight:700;color:var(--ink)">Total: '+regPriceFmt(REG_PRICE_BASE_WEST)+'</div>';
  }
}
// ===== Consultar inscripción por PIN (público) ==================================================
// Pantalla standalone (?consultar=1): el atleta ingresa el PIN de 6 dígitos que le mandamos al
// inscribirse y ve (a) el detalle de su propia inscripción (categorías/ritmos, igual que admin ve
// en "Inscripciones") y (b) sus heats asignados, si la grilla ya está armada y publicada. No
// requiere login de roles — usa la misma anon key que ya usa el formulario público para leer/
// escribir en `inscripciones` (RLS abierta, igual que el resto de esta app).
//
// Heats: para no duplicar la lógica de armado de grilla, reutilizamos buildLocutorItems() (la
// misma función que alimenta el checklist del Locutor) tras cargar published-data.json con
// loadPublished() — así los heats que mostramos son siempre los mismos que ve el Locutor (con
// fusiones/reordenamientos manuales del escrutinador ya aplicados), no un cálculo paralelo propio.
// El match contra "qué couples están en cada heat" se hace por identidad (idOf: DNI si está, sino
// nombre normalizado) — el mismo esquema que ya usa buildModel()/findPartnerConflicts() para
// detectar a la misma persona entre filas. Los Equipos coreográficos no tienen leadId (no son
// persona física) y se matchean por nombre de equipo en cambio.
function consultaIdentitiesFromRows(rows){
  const ids=new Set(),teamNames=new Set();
  (rows||[]).forEach(r=>{
    const lead=r['Nombre (leader)'],leadDni=r['DNI del leader'];
    const foll=r['Follower (indicar nombre)'],follDni=r['DNI del follower'];
    const team=r['Nombre del equipo coreográfico'];
    if(clean(lead))ids.add(idOf(lead,leadDni));
    if(clean(foll))ids.add(idOf(foll,follDni));
    if(r['Elija la especialidad']==='Equipo coreográfico'&&clean(team))teamNames.add(key(team));
  });
  return {ids,teamNames};
}
// Devuelve, para esta inscripción puntual, solo SU puesto final en cada heat donde participó —
// nunca la planilla completa del heat (eso quedaría reservado a Admin/Escrutinador/Locutor/Juez).
// Reutiliza _jreportCache/_mdreportCache (alimentados por ensurePremiosData, los mismos que ya usa
// "Resultados premios" de Locutor/Juez) en vez de duplicar el cálculo de puestos.
function consultaOwnResultRows(ids,teamNames){
  const out=[];
  ((_jreportCache&&_jreportCache.units)||[]).forEach(u=>{
    const pushFromCouples=(couples,results,label)=>{
      const c=(couples||[]).find(c=>(c.leadId&&ids.has(c.leadId))||(c.follId&&ids.has(c.follId)));
      if(!c)return;
      const dorsal=dorsalOf(c);
      const row=withRanksSingle(results||[]).find(r=>r.dorsal===dorsal);
      out.push({heat:u.heat,label,kind:'single',puesto:row?row.puesto:null});
    };
    if(u.parts){(u.parts||[]).forEach((part,pi)=>pushFromCouples(part.couples,(u.partResults||[])[pi]&&u.partResults[pi].results,part.rl));}
    else{pushFromCouples(u.couples,u.results,u.name);}
  });
  ((_mdreportCache&&_mdreportCache.units)||[]).forEach(u=>{
    const label=u.isTeam?(((u.team&&u.team.name)||'Equipo')):(u.mergedLabel?(u.style+' · '+u.mergedLabel):(u.name?dnClean(u.name):(([u.style,(u.cat&&u.cat!=='—')?u.cat:'',u.age].filter(Boolean).join(' · ')||'Multidance')+mdRitmoSuffix(u))));
    if(u.isTeam){
      if(!teamNames.has(key((u.team&&u.team.name)||'')))return;
      out.push({heat:u.heat,label,kind:'team',tipo:u.tipo,puesto:u.teamPlace,total:u.teamTotal});
      return;
    }
    const c=(u.couples||[]).find(c=>(c.leadId&&ids.has(c.leadId))||(c.follId&&ids.has(c.follId)));
    if(!c)return;
    const dorsal=dorsalOf(c);
    if(u.skating){
      const row=(u.overallResults||[]).find(r=>r.dorsal===dorsal);
      out.push({heat:u.heat,label,kind:'multi',puesto:row?row.puesto:null});
    }else{
      // "Contra el puesto" / grupo-solo: si hay varias parejas, se rankean por promedio general.
      const avgs=[];
      (u.perDanceResults||[]).forEach(pd=>{const r=(pd.rows||[]).find(rr=>rr.dorsal===dorsal);if(r&&r.avg!=null)avgs.push(r.avg);});
      const avg=avgs.length?Math.round(avgs.reduce((s,v)=>s+v,0)/avgs.length*100)/100:null;
      let puesto=null;
      if(u.soloGroup&&avg!=null){
        const g=Math.round(avg*10)/10;
        puesto=(g%1)>0.6?Math.ceil(g):Math.floor(g)||1;
      }
      out.push({heat:u.heat,label,kind:'multi-avg',avg,puesto});
    }
  });
  return out.sort((a,b)=>(Number(a.heat)||0)-(Number(b.heat)||0));
}
// ===== Diplomas de participación (en la solapa "🏅 Resultados Multidance") =====================
// Genera un diploma por cada pareja/equipo (categoría o ritmo en el que compitió), con el puesto
// final obtenido — todas las parejas por defecto, o solo las que coincidan con el filtro de dorsal/
// nombre si se completó uno (pedido de Roberto 2026-06-29, reubicado desde Configuración → Acciones
// el mismo día para vivir junto a los resultados que describe). Reusa _mdreportCache (alimentado por
// loadMultiReportData, el mismo que ya pinta la solapa) — no pega a la red de nuevo. Se imprime con
// window.print() (mismo mecanismo que exportJudgeReportPDF/exportMultiReportPDF) — no hay librería
// de PDF cargada en la app.
function _diplomaMedal(p){return p===1?' 🥇':p===2?' 🥈':p===3?' 🥉':'';}
function _diplomaResultText(d){
  if(d.kind==='team')return d.puesto!=null?`Obtuvo el ${d.puesto}° puesto en ${_escEd(d.tipo||'Equipo')}${_diplomaMedal(d.puesto)}`:'Diploma de participación';
  if(d.kind==='multi-avg')return d.puesto!=null?`Obtuvo el ${d.puesto}° puesto${_diplomaMedal(d.puesto)}`:(d.avg!=null?`Participó con un puntaje de ${Math.round(d.avg)}`:'Diploma de participación');
  return d.puesto!=null?`Obtuvo el ${d.puesto}° puesto${_diplomaMedal(d.puesto)}`:'Diploma de participación';
}
// filterText vacío = todas las parejas/equipos de la grilla; si no, solo las que matcheen por
// dorsal exacto o por nombre (substring, normalizado con key()).
function buildMdDiplomasList(filterText,gkeyFilter){
  const q=filterText?key(filterText):'';
  const out=[];
  const allUnits=(_mdreportCache&&_mdreportCache.units)||[];
  (gkeyFilter?allUnits.filter(u=>u.gkey===gkeyFilter):allUnits).forEach(u=>{
    const label=u.isTeam?(((u.team&&u.team.name)||'Equipo')):(u.mergedLabel?(u.style+' · '+u.mergedLabel):(u.name?dnClean(u.name):(([u.style,(u.cat&&u.cat!=='—')?u.cat:'',u.age].filter(Boolean).join(' · ')||'Multidance')+mdRitmoSuffix(u))));
    if(u.isTeam){
      const teamName=(u.team&&u.team.name)||'Equipo';
      if(q&&!key(teamName).includes(q))return;
      out.push({names:_escEd(teamName),dorsal:'',label:_escEd(u.tipo||'Equipo'),kind:'team',tipo:u.tipo,puesto:u.teamPlace});
      return;
    }
    (u.couples||[]).forEach(c=>{
      const dorsal=dorsalOf(c);
      const nameKey=key((coupleTxt(c)||'').replace(/<[^>]+>/g,' '));
      if(q&&String(dorsal)!==filterText.trim()&&!nameKey.includes(q))return;
      if(u.skating){
        const row=(u.overallResults||[]).find(r=>r.dorsal===dorsal);
        out.push({names:coupleTxt(c),dorsal,label:_escEd(label||''),kind:'multi',puesto:row?row.puesto:null});
      }else{
        const avgs=[];
        (u.perDanceResults||[]).forEach(pd=>{const r=(pd.rows||[]).find(rr=>rr.dorsal===dorsal);if(r&&r.avg!=null)avgs.push(r.avg);});
        const avg=avgs.length?Math.round(avgs.reduce((s,v)=>s+v,0)/avgs.length*100)/100:null;
        let puesto=null;
        if(u.soloGroup&&avg!=null){
          const g=Math.round(avg*10)/10;
          puesto=(g%1)>0.6?Math.ceil(g):Math.floor(g)||1;
        }
        out.push({names:coupleTxt(c),dorsal,label:_escEd(label||''),kind:'multi-avg',avg,puesto});
      }
    });
  });
  // Una pareja/equipo puede aparecer en heats distintos para la MISMA categoría (heat combinado o
  // partido en dos turnos) — eso daría dos diplomas idénticos. Nos quedamos con uno solo por
  // (dorsal, categoría, tipo).
  const seen=new Set();
  return out.filter(d=>{
    const k=(d.dorsal||d.names)+'|'+d.label+'|'+d.kind;
    if(seen.has(k))return false;
    seen.add(k);
    return true;
  }).sort((a,b)=>a.names.localeCompare(b.names)||a.label.localeCompare(b.label));
}
async function printDiplomasForHeat(gkey){
  if(!_mdreportCache||!(_mdreportCache.units||[]).length){alert('Todavía no hay resultados para generar diplomas. Probá "🔄 Actualizar" primero.');return;}
  const list=buildMdDiplomasList('',gkey);
  if(!list.length){alert('No hay parejas/equipos con resultado en este heat.');return;}
  printDiplomas(list);
}
function triggerMdDiplomasPrint(){
  if(!_mdreportCache||!(_mdreportCache.units||[]).length){alert('Todavía no hay resultados de Multidance para imprimir. Probá "🔄 Actualizar" primero.');return;}
  const inp=document.getElementById('mdDipFilter');
  const filterText=(inp&&inp.value||'').trim();
  const list=buildMdDiplomasList(filterText);
  if(!list.length){alert(filterText?`No se encontró ninguna pareja/equipo que coincida con "${filterText}".`:'No hay parejas/equipos para generar diplomas.');return;}
  printDiplomas(list);
}
async function printDiplomas(list){
  if(!list||!list.length)return;
  const area=document.getElementById('diplomasPrintArea');
  if(!area)return;
  let logoUrl=null;
  try{const rawLogo=await dbGetFile('reg-logo.json');const lg=rawLogo?JSON.parse(rawLogo):null;if(lg&&lg.img)logoUrl=lg.img;}catch(e){}
  // Nombre de la competencia (dip-eyebrow, debajo del logo): se puede ocultar desde Configuración →
  // Jueces → "Quitar nombre de la competencia del diploma" (#dipHideEventName) — pedido de Roberto
  // 2026-06-29. Si está tildado, nombreEvento queda vacío y el `${nombreEvento?...}` del template ya
  // existente no renderiza nada, sin tocar el HTML del template.
  const dipHideEventNameEl=document.getElementById('dipHideEventName');
  const nombreEvento=(dipHideEventNameEl&&dipHideEventNameEl.checked)?'':_escEd((EDICION_VISTA&&EDICION_VISTA.nombre)||COMP_DISPLAY_NAME||COMPS[0]?.title||'');
  const fechaEvento=_escEd((EDICION_VISTA&&EDICION_VISTA.fecha)||(COMPS[CUR]&&COMPS[CUR].date)||'');
  // Jurado: reusa judgeNames() (mismo array que usa el resto de la app para Jueces·Votación), filtrando
  // huecos sin nombre cargado. Organizador: lee el campo de Configuración → Jueces (ver getControls/
  // setControls), no hardcodeado — pedido de Roberto 2026-06-29.
  const juecesTxt=_escEd(judgeNames().filter(Boolean).join(' · '));
  const organizadorEl=document.getElementById('organizadorNombre');
  const organizador=_escEd(((organizadorEl&&organizadorEl.value)||'').trim());
  // Tamaño del logo (Configuración → Jueces → "Tamaño del logo (diplomas) %"): % sobre la base
  // CSS .dip-logo (max-height:190px;max-width:420px) — pedido de Roberto 2026-06-29. Se aplica como
  // style inline (pisa la regla de styles.css por especificidad) para no tocar CSS por cada cambio.
  const dipLogoSizeEl=document.getElementById('dipLogoSize');
  let dipLogoPct=parseFloat(dipLogoSizeEl&&dipLogoSizeEl.value);
  if(!dipLogoPct||dipLogoPct<=0)dipLogoPct=100;
  dipLogoPct=Math.max(30,Math.min(300,dipLogoPct));
  const dipLogoScale=dipLogoPct/100;
  const dipLogoStyle=`max-height:${Math.round(190*dipLogoScale)}px;max-width:${Math.round(420*dipLogoScale)}px`;
  area.innerHTML=list.map(d=>`<div class="dip-page"><div class="dip-border">
    <div class="dip-top">
      ${logoUrl?`<img src="${logoUrl}" alt="Logo" class="dip-logo" style="${dipLogoStyle}">`:''}
      ${nombreEvento?`<div class="dip-eyebrow">${nombreEvento}</div>`:''}
    </div>
    <div class="dip-mid">
      <div class="dip-rule"></div>
      <div class="dip-text">Se otorga el presente diploma a</div>
      <div class="dip-name">${d.names}</div>
      <div class="dip-text">por su destacada participación en</div>
      <div class="dip-cat">${d.label}</div>
      <div class="dip-result">${_diplomaResultText(d)}</div>
      ${juecesTxt?`<div class="dip-judges">Jurado: ${juecesTxt}</div>`:''}
    </div>
    <div class="dip-bottom">
      <div class="dip-sign">
        <div class="dip-sign-line"></div>
        ${organizador?`<div class="dip-sign-name">${organizador}</div>`:''}
        <div class="dip-sign-role">Organizador</div>
      </div>
      ${fechaEvento?`<div class="dip-date">${fechaEvento}</div>`:''}
    </div>
  </div></div>`).join('');
  _printNoBrowserChrome('print-diplomas');
}
// ===== Resultados Singles, lista por dorsal (en la solapa "🏆 Resultados Singles") ==============
// A diferencia de Multidance (diploma por pareja), aquí Roberto pidió específicamente formato lista
// (no diploma): se filtra por UN dorsal/nombre puntual y se imprime una sola hoja con TODOS los
// resultados de esa pareja en Single Dances (una fila por categoría/ritmo + su puesto). Reusa
// _jreportCache, igual que exportJudgeReportPDF.
// Nota: el leader/follower se guarda POR FILA (no una sola vez por entry) porque un mismo dorsal
// puede competir con distinta pareja según la categoría (p.ej. un profesor con distintas alumnas) —
// guardarlo una sola vez "arriba" mostraba mal la pareja real de cada heat (pedido de Roberto
// 2026-06-29: "poneme en cada heat el nombre y apellido del leader y el folower").
function _singlesListMatches(filterText){
  const q=key(filterText||'');
  const exact=filterText.trim();
  const map=new Map();
  ((_jreportCache&&_jreportCache.units)||[]).forEach(u=>{
    const pushFromCouples=(couples,results,label)=>{
      const ranked=withRanksSingle(results||[]);
      (couples||[]).forEach(c=>{
        const dorsal=dorsalOf(c);
        const nameKey=key((coupleTxt(c)||'').replace(/<[^>]+>/g,' '));
        if(String(dorsal)!==exact&&!nameKey.includes(q))return;
        const row=ranked.find(r=>r.dorsal===dorsal);
        const mapKey=dorsal||nameKey;
        if(!map.has(mapKey))map.set(mapKey,{dorsal,rows:[]});
        map.get(mapKey).rows.push({label:label||'',puesto:row?row.puesto:null,lead:c.lead||'',foll:c.foll||''});
      });
    };
    if(u.parts){(u.parts||[]).forEach((part,pi)=>pushFromCouples(part.couples,(u.partResults||[])[pi]&&u.partResults[pi].results,part.rl));}
    else{pushFromCouples(u.couples,u.results,u.name);}
  });
  return [...map.values()];
}
function _singlesListPageHtml(entry,nombreEvento,fechaEvento){
  const rowsHtml=entry.rows.map(r=>`<tr><td>${_escEd(r.label)}</td><td>${_escEd(r.lead)||'—'}</td><td>${_escEd(r.foll)||'—'}</td><td class="jrpl-puesto">${r.puesto!=null?r.puesto+'°'+_diplomaMedal(r.puesto):'—'}</td></tr>`).join('');
  return `<div class="jrpl-page">
    <div class="jrpl-head"><div class="jrpl-title">🏆 Resultados — Single Dances</div>${nombreEvento?`<div class="jrpl-sub">${nombreEvento}${fechaEvento?' · '+fechaEvento:''}</div>`:''}</div>
    ${entry.dorsal?`<div class="jrpl-name">Dorsal ${_escEd(entry.dorsal)}</div>`:''}
    <table class="jrpl-table"><thead><tr><th>Categoría / Ritmo</th><th>Leader</th><th>Follower</th><th style="text-align:right">Puesto</th></tr></thead><tbody>${rowsHtml}</tbody></table>
  </div>`;
}
function printSFMultiListFromCache(gkey,advance,nDances,nextRound){
  if(!_mdVoteFilesCache&&!_mdreportCache){alert('Cargá los resultados primero (Actualizar).');return;}
  let u=null;
  if(_mdreportCache)u=(_mdreportCache.units||[]).find(x=>x.gkey===gkey);
  if(!u){const units=buildMultidanceVoteUnits();u=units.find(x=>x.gkey===gkey);}
  if(!u){alert('No se encontró la unidad de semifinal.');return;}
  const sfDancesR=(u.dances&&u.dances.length)?u.dances:[''];
  const nd=nDances||sfDancesR.length||1;
  const allVoteFiles=(_mdVoteFilesCache&&_mdVoteFilesCache.voteFiles)||[];
  const xCounts={};
  u.couples.forEach(c=>{xCounts[c.leadId]=0;});
  allVoteFiles.forEach(vf=>{
    const gvotes=(vf.votes&&vf.votes[u.gkey])||{};
    for(let di=0;di<nd;di++){const dv=gvotes[String(di)]||{};u.couples.forEach(c=>{if(dv[c.leadId]===1)xCounts[c.leadId]=(xCounts[c.leadId]||0)+1;});}
  });
  const sorted=u.couples.map(c=>({c,x:xCounts[c.leadId]||0})).sort((a,b)=>b.x-a.x||(dorsalOf(a.c)>dorsalOf(b.c)?1:-1));
  const pasan=sorted.slice(0,advance).map(r=>r.c);
  const noPasan=sorted.slice(advance).map(r=>r.c);
  printSemifinalList(u,nextRound||getNextRoundName(u.roundName||'Semifinal'),advance,pasan,noPasan);
}
function printSemifinalList(e,nextRound,advance,pasan,noPasan){
  const area=document.getElementById('sfPrintArea');
  if(!area)return;
  const nombreEvento=_escEd((EDICION_VISTA&&EDICION_VISTA.nombre)||COMPS[0]?.title||'');
  const fechaEvento=_escEd((EDICION_VISTA&&EDICION_VISTA.fecha)||(COMPS[CUR]&&COMPS[CUR].date)||'');
  const ahora=_escEd(new Date().toLocaleString('es-AR',{dateStyle:'medium',timeStyle:'short'}));
  const heatLabel=`Heat ${e.heat} · ${_escEd(e.name||'')}`;
  const rowHtml=(c,pass)=>{
    const dorsal=dorsalOf(c);
    const nombre=_escEd(c.lead||'')+(c.foll?` / ${_escEd(c.foll)}`:'');
    const esc=_escEd(c.esc||'');
    const bg=pass?'#f0faf0':'#fff8f8';
    const icon=pass?'✅':'❌';
    return `<tr style="background:${bg};border-bottom:1px solid #eee">
      <td style="padding:5px 8px;font-weight:700;color:#1d4e89;white-space:nowrap">${dorsal}</td>
      <td style="padding:5px 8px">${icon} ${nombre}</td>
      <td style="padding:5px 8px;color:#666;font-size:11px">${esc}</td>
    </tr>`;
  };
  const pasanRows=pasan.map(c=>rowHtml(c,true)).join('');
  const noPasanRows=noPasan.map(c=>rowHtml(c,false)).join('');
  const destLabel=nextRound==='Final'?'la Final':nextRound;
  area.innerHTML=`<div style="font-family:Arial,sans-serif;padding:14px 18px;max-width:700px;margin:0 auto">
    <div style="display:flex;justify-content:space-between;align-items:baseline;border-bottom:2px solid #1d4e89;padding-bottom:6px;margin-bottom:10px">
      <div style="font-size:17px;font-weight:700;color:#1d4e89">🏁 Pasantes a ${destLabel}</div>
      <div style="font-size:10px;color:#888">Generado el ${ahora}</div>
    </div>
    <div style="font-size:12px;color:#555;margin-bottom:12px">
      <b>${heatLabel}</b>${nombreEvento?` &nbsp;·&nbsp; ${nombreEvento}`:''}${fechaEvento?` &nbsp;·&nbsp; ${fechaEvento}`:''}
    </div>
    <div style="font-size:12px;font-weight:700;color:#27ae60;margin-bottom:4px">✅ Pasan a ${destLabel} (${pasan.length} de ${advance})</div>
    <table style="width:100%;border-collapse:collapse;font-size:12px;margin-bottom:16px">
      <thead><tr style="background:#d4edda"><th style="padding:5px 8px;text-align:left;border-bottom:1px solid #b8dac0">Dorsal</th><th style="padding:5px 8px;text-align:left;border-bottom:1px solid #b8dac0">Nombre</th><th style="padding:5px 8px;text-align:left;border-bottom:1px solid #b8dac0">Escuela</th></tr></thead>
      <tbody>${pasanRows||'<tr><td colspan="4" style="padding:6px 8px;color:#999;font-style:italic">—</td></tr>'}</tbody>
    </table>
    ${noPasan.length?`<div style="font-size:12px;font-weight:700;color:#c0392b;margin-bottom:4px">❌ No pasan (${noPasan.length})</div>
    <table style="width:100%;border-collapse:collapse;font-size:12px;margin-bottom:16px">
      <thead><tr style="background:#fde8e8"><th style="padding:5px 8px;text-align:left;border-bottom:1px solid #f0b8b8">Dorsal</th><th style="padding:5px 8px;text-align:left;border-bottom:1px solid #f0b8b8">Nombre</th><th style="padding:5px 8px;text-align:left;border-bottom:1px solid #f0b8b8">Escuela</th></tr></thead>
      <tbody>${noPasanRows}</tbody>
    </table>`:''}
    <div style="margin-top:10px;font-size:10px;color:#999;border-top:1px solid #ddd;padding-top:5px">RC · Baile Deportivo — Reporte generado automáticamente desde la app de gestión</div>
  </div>`;
  _printNoBrowserChrome('print-sflist');
}
function triggerSinglesListPrint(){
  if(!_jreportCache||!(_jreportCache.units||[]).length){alert('Todavía no hay resultados de jueces para imprimir. Probá "🔄 Actualizar" primero.');return;}
  const inp=document.getElementById('jrpDorsalFilter');
  const filterText=(inp&&inp.value||'').trim();
  if(!filterText){alert('Ingresá un dorsal o nombre para imprimir su lista de resultados.');return;}
  const matches=_singlesListMatches(filterText);
  if(!matches.length){alert(`No se encontró ninguna pareja/dorsal que coincida con "${filterText}".`);return;}
  const area=document.getElementById('jrplPrintArea');
  if(!area)return;
  const nombreEvento=_escEd((EDICION_VISTA&&EDICION_VISTA.nombre)||COMPS[0]?.title||'');
  const fechaEvento=_escEd((EDICION_VISTA&&EDICION_VISTA.fecha)||(COMPS[CUR]&&COMPS[CUR].date)||'');
  area.innerHTML=matches.map(m=>_singlesListPageHtml(m,nombreEvento,fechaEvento)).join('');
  _printNoBrowserChrome('print-jrplist');
}
// Helper compartido por ambos prints nuevos: agrega temporalmente un <style> con @page{margin:0}
// antes de imprimir y lo saca después. Pedido de Roberto: que ni el diploma ni la lista de singles
// lleven "la marca de encabezado y pie de página con el nombre del programa y la hora de impresión"
// — eso no es nuestro jrp-head/jrp-foot (que esta función no usa) sino el header/footer NATIVO que
// el navegador agrega solo (título de la pestaña + fecha/hora) en el margen de la hoja; con margen
// en 0 no le queda espacio donde dibujarlo. Los prints existentes (jreport/mdreport) siguen usando
// el @page compartido de siempre — no se tocó, para no afectarlos.
function _printNoBrowserChrome(bodyClass){
  const st=document.createElement('style');
  st.textContent='@page{margin:0 !important}';
  document.head.appendChild(st);
  document.body.classList.add(bodyClass);
  window.print();
  document.body.classList.remove(bodyClass);
  st.remove();
}
// Reemplaza los antiguos consultaHeatsHTML()+consultaResultadosHTML() (dos secciones separadas,
// "Tus heats" y "Tus resultados" repitiendo cada heat dos veces) por una sola lista: cada fila de
// heat ahora tiene una tercera columna con el resultado de ESE heat (si ya está publicado), en vez
// de listar todo de nuevo más abajo. Pedido de Roberto 2026-06-29 para ahorrar espacio vertical.
async function consultaHeatsAndResultsHTML(rows){
  if(!COMPS||!COMPS.length)return '<span style="color:var(--ink-soft)">La grilla todavía no está armada o publicada. Probá de nuevo más cerca de la competencia.</span>';
  const {ids,teamNames}=consultaIdentitiesFromRows(rows);
  if(!ids.size&&!teamNames.size)return '<span style="color:var(--ink-soft)">—</span>';
  let items;
  try{items=buildLocutorItems();}catch(e){return '<span style="color:var(--ink-soft)">No se pudo calcular la grilla en este momento.</span>';}
  const matched=items.filter(it=>(it.couples||[]).some(c=>{
    if(c.leadId&&ids.has(c.leadId))return true;
    if(c.follId&&ids.has(c.follId))return true;
    if(!c.leadId&&c.lead&&teamNames.has(key(c.lead)))return true;
    return false;
  }));
  if(!matched.length)return '<span style="color:var(--ink-soft)">Todavía no encontramos tu heat en la grilla — puede que el organizador no la haya armado todavía. Probá más tarde o consultá con el locutor.</span>';
  matched.sort((a,b)=>(a.heat||0)-(b.heat||0));
  // Resultados (si ya están publicados), agrupados por número de heat — un heat puede tener más de
  // un resultado propio cuando varias categorías del atleta comparten el mismo heat combinado.
  let resultsEnabled=false;
  try{const raw=await dbGetFile('results-published.json');if(raw){const c=JSON.parse(raw);resultsEnabled=!!(c&&c.enabled);}}catch(e){}
  const byHeat={};
  let resultsError=false;
  if(resultsEnabled){
    // force=true: esta pantalla se entra una sola vez por búsqueda de PIN, así que siempre conviene
    // traer datos frescos. Además evita quedar pegado para siempre si una carga anterior dejó
    // _jreportLoading/_mdreportLoading trabado en true (bug 2026-06-28).
    try{
      await ensurePremiosData(true);
      const medal=p=>p===1?' 🥇':p===2?' 🥈':p===3?' 🥉':'';
      consultaOwnResultRows(ids,teamNames).forEach(f=>{
        let txt;
        if(f.kind==='team')txt=f.puesto!=null?`${f.puesto}° en ${f.tipo||'Equipo'}${medal(f.puesto)} · ${f.total} pts`:'Pendiente de votos';
        else if(f.kind==='multi-avg')txt=f.avg!=null?`Puntaje ${f.avg}`:'Pendiente de votos';
        else txt=f.puesto!=null?`${f.puesto}° puesto${medal(f.puesto)}`:'Pendiente de votos';
        (byHeat[f.heat]=byHeat[f.heat]||[]).push(txt);
      });
    }catch(e){resultsError=true;}
  }
  const rowsHtml=matched.map(it=>{
    // Importante: tomar la pareja que matchea a ESTE atleta (mismo criterio que el filtro de
    // arriba), no couples[0] — un heat suele tener varias parejas, y tomar la primera mostraba el
    // dorsal de otro competidor cuando esa pareja no encabezaba la lista (bug reportado 2026-06-29).
    const c=(it.couples||[]).find(cc=>{
      if(cc.leadId&&ids.has(cc.leadId))return true;
      if(cc.follId&&ids.has(cc.follId))return true;
      if(!cc.leadId&&cc.lead&&teamNames.has(key(cc.lead)))return true;
      return false;
    });
    const dorsal=c&&c.leadId&&EVENT_DORSALS[c.leadId]!=null?EVENT_DORSALS[c.leadId]:'';
    let resCell='';
    if(resultsEnabled&&!resultsError){
      const txt=byHeat[it.heat]?byHeat[it.heat].join(' · '):'Pendiente de votos';
      resCell=`<span style="text-align:right;font-size:12.5px;font-weight:700;color:var(--wine);white-space:nowrap">${txt}</span>`;
    }
    return `<div style="display:flex;justify-content:space-between;align-items:baseline;gap:10px;padding:7px 0;border-bottom:1px solid var(--line)">
      <span><span style="font-weight:800;color:var(--wine)">Heat ${it.heat}</span>${dorsal!==''?` · Dorsal ${dorsal}`:''}</span>
      <span style="flex:1;text-align:right;font-size:13px">${(it.name||'').replace(' · pista compartida','')}</span>
      ${resCell}
    </div>`;
  }).join('');
  let note='';
  if(!resultsEnabled)note='<div style="margin-top:8px;font-size:11.5px;color:var(--ink-soft)">Los resultados todavía no fueron publicados por el organizador.</div>';
  else if(resultsError)note='<div style="margin-top:8px;font-size:11.5px;color:var(--ink-soft)">No se pudieron calcular los resultados en este momento.</div>';
  return `<div style="font-size:12px;font-weight:700;color:var(--ink-soft);text-transform:uppercase;letter-spacing:.05em;margin-bottom:6px">Tus heats${resultsEnabled&&!resultsError?' y resultados':''}</div>${rowsHtml}${note}`;
}
function consultaRenderResultHTML(insc){
  const rows=insc.rows||[];
  const detalle=rows.map(r=>`<div>${regRowSummaryLine(r)}</div>`).join('')||'<span style="color:var(--ink-soft)">—</span>';
  return `<div style="background:var(--card);border:1px solid var(--line);border-radius:16px;padding:20px">
    <div style="font-size:12px;font-weight:700;color:var(--ink-soft);text-transform:uppercase;letter-spacing:.05em;margin-bottom:8px">Tu inscripción</div>
    <div style="font-family:'Fraunces',serif;font-weight:700;font-size:17px;color:var(--wine);margin-bottom:8px">${insc.resumen||'—'}</div>
    <div style="font-size:13.5px;line-height:1.6">${detalle}</div>
    <div id="consulta-heats-box" style="margin-top:14px;font-size:13.5px">⏳ Buscando tus heats y resultados...</div>
  </div>`;
}
async function consultaBuscarPin(){
  const input=document.getElementById('consulta-pin');
  const status=document.getElementById('consulta-status');
  const resultBox=document.getElementById('consulta-result');
  if(!input||!status||!resultBox)return;
  const pin=(input.value||'').trim();
  resultBox.innerHTML='';
  if(!/^\d{6}$/.test(pin)){
    status.style.color='#c0392b';status.textContent='⚠ Ingresá los 6 dígitos del PIN.';
    return;
  }
  status.style.color='#666';status.textContent='⏳ Buscando...';
  try{
    const {data,error}=await sb.from('inscripciones').select('id,tipo,resumen,rows,created_at').eq('pin',pin).order('created_at',{ascending:false}).limit(1);
    if(error)throw new Error(error.message);
    if(!data||!data.length){
      status.style.color='#c0392b';status.textContent='⚠ No encontramos ninguna inscripción con ese PIN. Revisá que esté bien escrito.';
      return;
    }
    status.textContent='';
    const insc=data[0];
    {
      resultBox.innerHTML=consultaRenderResultHTML(insc);
      loadPublished().catch(()=>{}).then(async ()=>{
        const heatsBox=document.getElementById('consulta-heats-box');
        if(heatsBox)heatsBox.innerHTML=await consultaHeatsAndResultsHTML(insc.rows);
      });
    }
  }catch(e){
    status.style.color='#c0392b';status.textContent='⚠ No se pudo consultar: '+e.message;
  }
}
