function regFillSolista(rows){
  const tags=regCollectCompTags(rows);
  regSetCompCheckboxes(tags);
  const privRows=rows.filter(r=>(r['Competencia']||'').includes('Privada'));
  const aabdRows=rows.filter(r=>(r['Competencia']||'').includes('AABD'));
  const useRows=privRows.length?privRows:(aabdRows.length?aabdRows:rows);
  const main=useRows[0]||rows[0];
  if(!main)return;
  if(privRows.length)regSetVal('reg_s_edad',privRows[0]['Grupo de edad']);
  if(aabdRows.length)regSetVal('reg_s_edadAabd',aabdRows[0]['Grupo de edad']);
  regSetVal('reg_s_nombre',main['Nombre (leader)']);
  regSetVal('reg_s_dni',main['DNI del leader']);
  regSetVal('reg_s_esc',main['Seleccione su escuela']);
  const STYLES=['Standard','Latin','Smooth','Rhythm','SocialLatino','SocialArgentino','SocialAmericano'];
  const bloqueRows=useRows.filter(r=>r['Elegir modalidad']!=='Single Dance');
  // Por estilo puede haber HASTA 2 filas (Nivel + Open) — se mergean en un solo bloque antes
  // de repartirlas entre los slots s1/s2.
  const blockMap={};
  bloqueRows.forEach(r=>{STYLES.forEach(st=>{
    const v=r[st+' categoria'];
    if(v==null)return;
    if(!blockMap[st])blockMap[st]={style:st,val:null,open:false};
    if(v==='Open')blockMap[st].open=true;else blockMap[st].val=v;
  });});
  const blocks=Object.values(blockMap);
  ['s1','s2'].forEach((px,i)=>{
    const b=blocks[i];
    const sel=document.getElementById('reg_'+px+'_style');
    if(!sel)return;
    if(!b){sel.value='';regSolistaStyleChange(px);return;}
    sel.value=b.style;
    regSolistaStyleChange(px);
    if(b.val!=null)regSetVal('reg_'+px+'_niv',b.val);
    if(b.open){const o=document.getElementById('reg_'+px+'_open');if(o)o.checked=true;}
  });
  const sd=useRows.find(r=>r['Elegir modalidad']==='Single Dance');
  if(sd){
    ['s1','s2'].forEach(px=>{
      const style=document.getElementById('reg_'+px+'_style').value;
      if(!style)return;
      const group=STYLE2GROUP_REG[style];
      const hasAny=Object.keys(sd).some(k=>k.startsWith('Ritmos ('+group+')')&&sd[k]);
      if(hasAny){
        const chk=document.getElementById('reg_'+px+'_singles_chk'),list=document.getElementById('reg_'+px+'_singles_list');
        if(chk)chk.checked=true;
        if(list)list.style.display='block';
        regFillChecklistFromRow(sd,px);
      }
    });
    const cv=document.querySelector(`input[name="reg_s_contested"][value="${sd['Contested']||'Contested'}"]`);
    if(cv)cv.checked=true;
  }
  regSUpdateContestedVisibility();
  regFillChalEmbed(rows,'s');
}
function regFillSynchro(rows){
  const tags=regCollectCompTags(rows);
  regSetCompCheckboxes(tags);
  const privRows=rows.filter(r=>(r['Competencia']||'').includes('Privada'));
  const aabdRows=rows.filter(r=>(r['Competencia']||'').includes('AABD'));
  const useRows=privRows.length?privRows:(aabdRows.length?aabdRows:rows);
  const main=useRows[0]||rows[0];
  if(!main)return;
  if(privRows.length)regSetVal('reg_y_edad',privRows[0]['Grupo de edad']);
  if(aabdRows.length)regSetVal('reg_y_edadAabd',aabdRows[0]['Grupo de edad']);
  regSetVal('reg_y_a1',main['Nombre (leader)']);regSetVal('reg_y_a1Dni',main['DNI del leader']);
  regSetVal('reg_y_a2',main['Follower (indicar nombre)']);regSetVal('reg_y_a2Dni',main['DNI del follower']);
  regSetVal('reg_y_esc',main['Seleccione su escuela']);
  // Puede haber HASTA 2 filas por estilo (Nivel + Open) — se recorren todas, no solo la primera.
  const rhRows=useRows.filter(r=>r['Elegir modalidad']!=='Single Dance'&&r['Rhythm categoria']!=null);
  rhRows.forEach(r=>{
    const v=r['Rhythm categoria'];
    if(v==='Open'){const o=document.getElementById('reg_y_rhOpen');if(o)o.checked=true;}
    else regSetVal('reg_y_rhNiv',v);
  });
  const ltRows=useRows.filter(r=>r['Elegir modalidad']!=='Single Dance'&&r['Latin categoria']!=null);
  ltRows.forEach(r=>{
    const v=r['Latin categoria'];
    if(v==='Open'){const o=document.getElementById('reg_y_ltOpen');if(o)o.checked=true;}
    else regSetVal('reg_y_ltNiv',v);
  });
  const sdRows=useRows.filter(r=>r['Elegir modalidad']==='Single Dance');
  sdRows.forEach(r=>{
    const hasRh=Object.keys(r).some(k=>k.startsWith('Ritmos (AM-RH)')&&r[k]);
    const hasLt=Object.keys(r).some(k=>k.startsWith('Ritmos (INT-LT)')&&r[k]);
    if(hasRh){
      const chk=document.getElementById('reg_y_rh_singles_chk'),list=document.getElementById('reg_y_rh_singles_list');
      if(chk)chk.checked=true;if(list)list.style.display='block';
      regFillChecklistFromRow(r,'y_rh');
    }
    if(hasLt){
      const chk=document.getElementById('reg_y_lt_singles_chk'),list=document.getElementById('reg_y_lt_singles_list');
      if(chk)chk.checked=true;if(list)list.style.display='block';
      regFillChecklistFromRow(r,'y_lt');
    }
    const cv=document.querySelector(`input[name="reg_y_contested"][value="${r['Contested']||'Contested'}"]`);
    if(cv)cv.checked=true;
  });
  regYUpdateContestedVisibility();
}
