function _updateDorsalLogoPreview(n,dataUrl){
  const el=document.getElementById('dorsalLogo'+n+'Preview');
  if(!el)return;
  if(dataUrl){el.innerHTML=`<img src="${dataUrl}" style="max-height:32px;max-width:50px;object-fit:contain">`;}
  else{el.textContent='Logo '+n;}
}
function dorsalExtraLogoChange(n,input){
  const file=input.files[0];if(!file)return;
  const st=document.getElementById('dorsalLogoStatus');
  if(st){st.style.color='var(--ink-soft)';st.textContent='⏳ Guardando...';}
  const reader=new FileReader();
  reader.onload=async e=>{
    const dataUrl=e.target.result;
    DORSAL_EXTRA_LOGOS['logo'+n]=dataUrl;
    _updateDorsalLogoPreview(n,dataUrl);
    try{
      await dbUpload(JSON.stringify(DORSAL_EXTRA_LOGOS),true,'dorsal-extra-logos.json');
      if(st){st.style.color='#27ae60';st.textContent='✓ Logo guardado.';}
    }catch(err){if(st){st.style.color='#c0392b';st.textContent='⚠ Error: '+err.message;}}
  };
  reader.readAsDataURL(file);
}
async function dorsalExtraLogoRemove(n){
  DORSAL_EXTRA_LOGOS['logo'+n]=null;
  _updateDorsalLogoPreview(n,null);
  const inp=document.getElementById('dorsalLogo'+n+'Input');if(inp)inp.value='';
  const st=document.getElementById('dorsalLogoStatus');
  if(st){st.style.color='var(--ink-soft)';st.textContent='⏳ Guardando...';}
  try{
    await dbUpload(JSON.stringify(DORSAL_EXTRA_LOGOS),true,'dorsal-extra-logos.json');
    if(st){st.style.color='#27ae60';st.textContent='✓ Logo eliminado.';}
  }catch(err){if(st){st.style.color='#c0392b';st.textContent='⚠ Error: '+err.message;}}
}

