// Logo del formulario público de inscripción. Se guarda en Supabase (kv_store, key 'reg-logo')
// para que cualquiera que abra el link de inscripción lo vea, sin depender de este admin en particular.
// Se redimensiona en el navegador antes de subirlo: el form lo cargan los celulares de todos los
// competidores, así que conviene mantenerlo liviano (no guardar la foto original tal cual).
function regLogoResize(file){
  return new Promise((resolve,reject)=>{
    const reader=new FileReader();
    reader.onload=ev=>{
      const img=new Image();
      img.onload=()=>{
        const maxDim=480;
        let w=img.width,h=img.height;
        if(w>maxDim||h>maxDim){
          if(w>=h){h=Math.round(h*maxDim/w);w=maxDim;}else{w=Math.round(w*maxDim/h);h=maxDim;}
        }
        const canvas=document.createElement('canvas');
        canvas.width=w;canvas.height=h;
        canvas.getContext('2d').drawImage(img,0,0,w,h);
        resolve(canvas.toDataURL('image/png'));
      };
      img.onerror=()=>reject(new Error('No se pudo leer la imagen'));
      img.src=ev.target.result;
    };
    reader.onerror=()=>reject(new Error('No se pudo leer el archivo'));
    reader.readAsDataURL(file);
  });
}
function regLogoSetPreview(dataUrl){
  const wrap=document.getElementById('regLogoPreviewWrap');
  const img=document.getElementById('regLogoPreview');
  const rmBtn=document.getElementById('regLogoRemoveBtn');
  if(!wrap||!img)return;
  if(dataUrl){
    img.src=dataUrl;wrap.style.display='block';if(rmBtn)rmBtn.style.display='inline-block';
  }else{
    wrap.style.display='none';img.src='';if(rmBtn)rmBtn.style.display='none';
  }
}
