// ================== Página pública / Marketing (home comercial) ==================
// Contenido editable desde "Página pública / Marketing" que alimenta la landing pública
// (#pin-overlay / eb-commercial-hero): tagline/descripción/sede + CTAs, categorías, galería
// de fotos y sponsors. Mismo mecanismo que comp-name/reg-logo: kv_store + dbUpload/dbGetFile,
// cada sección en su propia clave para que un guardado no pise a las demás.
function mktResizeImage(file,maxDim,mime,quality){
  return new Promise((resolve,reject)=>{
    const reader=new FileReader();
    reader.onload=ev=>{
      const img=new Image();
      img.onload=()=>{
        let w=img.width,h=img.height;
        if(w>maxDim||h>maxDim){
          if(w>=h){h=Math.round(h*maxDim/w);w=maxDim;}else{w=Math.round(w*maxDim/h);h=maxDim;}
        }
        const canvas=document.createElement('canvas');
        canvas.width=w;canvas.height=h;
        canvas.getContext('2d').drawImage(img,0,0,w,h);
        resolve(quality!=null?canvas.toDataURL(mime,quality):canvas.toDataURL(mime));
      };
      img.onerror=()=>reject(new Error('No se pudo leer la imagen'));
      img.src=ev.target.result;
    };
    reader.onerror=()=>reject(new Error('No se pudo leer el archivo'));
    reader.readAsDataURL(file);
  });
}
