function startImportInscripciones(){
  const idx=COMPS.findIndex(c=>c.sheet==='__inscripciones_web__');
  let forcedTitle=null;
  if(idx<0){
    const r=prompt('¿Cómo querés llamar a esta competencia? (vas a poder cambiarlo después en "Competencia")','Inscripciones web');
    if(r===null)return; // canceló
    forcedTitle=r.trim()||'Inscripciones web';
  }
  document.getElementById('controls')?.classList.add('show');
  document.getElementById('sidebarControls')?.classList.add('open');
  importInscripcionesOnline(forcedTitle);
}
async function importInscripcionesOnline(forcedTitle,_silent=false){
  const st=document.getElementById('regImportStatus');
  const setMsg=(bg,bc,c,t)=>{if(_silent||!st)return;st.style.display='block';st.style.background=bg;st.style.borderColor=bc;st.style.color=c;st.textContent=t;};
  if(!_silent)setMsg('#f5f5f5','#ccc','#666','⏳ Importando inscripciones online...');
  try{
    const {data,error}=await sb.from('inscripciones').select('rows');
    if(error)throw new Error(error.message);
    const allRows=[];
    (data||[]).forEach(r=>{if(Array.isArray(r.rows))allRows.push(...r.rows);});
    if(!allRows.length){
      setMsg('#fdf0ee','#e3b8b0','#a00','⚠ Todavía no hay inscripciones online para importar.');
      setTimeout(()=>{if(st)st.style.display='none';},5000);
      return;
    }
    // Cada fila puede venir tageada con 'Competencia' = 'Privada', 'AABD' o ambas (separadas por
    // coma) — el atleta elige en el formulario público a qué competencia(s) se inscribe. Las filas
    // viejas, enviadas antes de que existiera esta columna, no tienen el tag: se tratan como Privada
    // para no perder inscripciones previas al importar.
    const aabdRows=allRows.filter(r=>String(r['Competencia']||'').includes('AABD'));
    const privRows=allRows.filter(r=>{const c=String(r['Competencia']||'');return!c||c.includes('Privada');});
    const sessions=[];
    if(privRows.length){
      const idx=COMPS.findIndex(c=>c.sheet==='__inscripciones_web__');
      sessions.push({sheet:'__inscripciones_web__',rows:privRows,ageMode:undefined,ageFn:ageNorm,idx,defaultTitle:forcedTitle||'Inscripciones web'});
    }
    if(aabdRows.length){
      const idx=COMPS.findIndex(c=>c.sheet==='__inscripciones_web_aabd__');
      sessions.push({sheet:'__inscripciones_web_aabd__',rows:aabdRows,ageMode:'AABD',ageFn:ageNormAABD,idx,defaultTitle:'Federación'});
    }
    sessions.forEach(s=>{
      const model=buildModel(s.rows,s.ageFn);
      model.dorsalOf=cp=>{const p=model.persons[cp.leadId];return p&&p.dorsal!==''?p.dorsal:'';};
      const sess={sheet:s.sheet,title:s.idx>=0?COMPS[s.idx].title:uniqTitle(s.defaultTitle),date:'',rows:s.rows,model,ageMode:s.ageMode};
      if(s.idx>=0){COMPS[s.idx]=sess;}else{COMPS.push(sess);}
    });
    // Tras importar, siempre nos movemos a la vista que incluye lo recién importado — antes esto
    // solo pasaba si no había ninguna competencia cargada. Si el admin ya tenía una
    // competencia puntual seleccionada, el selector se quedaba fijo en esa y la sesión nueva (p.ej.
    // una inscripción de Solista enviada desde el formulario web) quedaba invisible en Dorsales y
    // no sumaba al stat "Competencias", aunque sí tuviera dorsal asignado y apareciera en la lista
    // de inscripciones recibidas. Replicamos el mismo criterio que ya se usa al cargar un archivo.
    if(COMPS.length>1){CUR='all';MODEL=null;}
    else if(COMPS.length===1){CUR=0;MODEL=COMPS[0].model;}
    const dStart=parseInt(document.getElementById('dStart').value)||1;
    const sStartRaw=document.getElementById('sStart').value;
    const sStart=sStartRaw?parseInt(sStartRaw):0;
    applyManualCouplesSession();rebuildDorsals(dStart,sStart);applyDorsalOverrides();
    _jreportCache=null;_mdreportCache=null;_mdVoteFilesCache=null; // hay heats/singles nuevos: refrescar "Resultados Singles"
    document.getElementById('controls').classList.add('show');
    document.getElementById('stats').classList.add('show');
    document.getElementById('tabs').classList.add('show');
    document.getElementById('drop').style.display='none';
    document.getElementById('empty').style.display='none';
    document.getElementById('fileInfo').style.display='block';
    document.getElementById('fileInfo').textContent=COMPS.length+(COMPS.length===1?' sesión cargada':' sesiones cargadas')+' · '+Object.keys(EVENT_DORSALS).length+' competidores con dorsal';
    buildCompSel();syncCompInputs();updateCompHeader();renderLogoPanel();render();
    scheduleAdminBackup(); // guardar backup para que el refresh restaure las inscripciones importadas
    loadJudgeReportData(true); // forzar recálculo inmediato del reporte de jueces
    const sessLabel=sessions.map(s=>s.sheet==='__inscripciones_web_aabd__'?'Federación':'Privada').join(' + ');
    setMsg('#eef6f0','#b8d4bb','#3f6b4a','✓ Importadas '+data.length+' inscripciones online ('+allRows.length+' filas) como sesión'+(sessions.length>1?'es':'')+' "'+sessLabel+'".');
    // Guardamos el momento de este import (en Supabase, no localStorage, para que cuente sin
    // importar desde qué dispositivo se haga el próximo import) — es lo que usa
    // refreshRegPendingCount para saber qué inscripciones son "nuevas desde la última vez".
    const nowIso=new Date().toISOString();
    _regLastImportAtCache=new Date(nowIso);
    dbUpload(JSON.stringify({at:nowIso}),true,'reg-last-import.json');
    loadInscripcionesAdmin();
  }catch(e){
    setMsg('#fdf0ee','#e3b8b0','#a00','⚠ Error al importar: '+e.message);
  }
  if(!_silent)setTimeout(()=>{if(st)st.style.display='none';},7000);
}

// ==================== Parejas manuales ====================
let MANUAL_COUPLES_ROWS=[];

async function loadManualCouplesFromDB(){
  try{const raw=await dbGetFile('manual-couples.json');MANUAL_COUPLES_ROWS=raw?(JSON.parse(raw).rows||[]):[];}
  catch(e){MANUAL_COUPLES_ROWS=[];}
  // Deduplicar al cargar: misma lógica que applyManualCouplesSession
  const _cn=['Standard categoria','Latin categoria','Smooth categoria','Rhythm categoria','SocialLatino categoria','SocialArgentino categoria','SocialAmericano categoria'];
  const _sk=r=>{const nm=(r['Nombre (leader)']||'').toLowerCase().trim();const stCol=_cn.find(c=>r[c]!=null)||'';const stVal=stCol?(r[stCol]||''):'';const ag=(r['Grupo de edad']||'');const ts=r._targetSheet||'';return nm+'|'+stCol+'|'+stVal+'|'+ag+'|'+ts;};
  const _seen=new Map();MANUAL_COUPLES_ROWS.forEach(r=>_seen.set(_sk(r),r));
  const _dd=Array.from(_seen.values());
  if(_dd.length!==MANUAL_COUPLES_ROWS.length){MANUAL_COUPLES_ROWS=_dd;await saveManualCouplesDB();console.log('manual-couples: deduplicados '+(MANUAL_COUPLES_ROWS.length)+' registros');}
}
async function saveManualCouplesDB(){
  try{await dbUpload(JSON.stringify({rows:MANUAL_COUPLES_ROWS,updatedAt:new Date().toISOString()}),true,'manual-couples.json');}
  catch(e){console.error('saveManualCouples:',e);}
}
function applyManualCouplesSession(){
  // Deduplicar MANUAL_COUPLES_ROWS: si hay dos filas con mismo lead+targetSheet+estilo, conservar la más reciente
  const _colNames=['Standard categoria','Latin categoria','Smooth categoria','Rhythm categoria','SocialLatino categoria','SocialArgentino categoria','SocialAmericano categoria'];
  const _styleOf=r=>_colNames.find(c=>r[c]!=null)||'';
  const _seenKey=r=>{const nm=(r['Nombre (leader)']||'').toLowerCase().trim();const stCol=_styleOf(r);const stVal=stCol?(r[stCol]||''):'';const ag=(r['Grupo de edad']||'');const ts=r._targetSheet||'';return nm+'|'+stCol+'|'+stVal+'|'+ag+'|'+ts;};
  const _seen=new Map();
  // Iterar en orden para que el último (más reciente) gane
  MANUAL_COUPLES_ROWS.forEach(r=>{const k=_seenKey(r);_seen.set(k,r);});
  const _deduped=Array.from(_seen.values());
  if(_deduped.length!==MANUAL_COUPLES_ROWS.length){MANUAL_COUPLES_ROWS=_deduped;saveManualCouplesDB();}
  // Clean any previously injected rows from real COMPs
  const _vs=new Set(['__manual_couples__','__inscripciones_web__','__inscripciones_web_aabd__']);
  COMPS.forEach(comp=>{
    if(_vs.has(comp.sheet))return;
    if((comp.rows||[]).some(r=>r._targetSheet)){
      comp.rows=comp.rows.filter(r=>!r._targetSheet);
      comp.model=buildModel(comp.rows,ageNorm);
      comp.model.dorsalOf=cp=>{const p=comp.model.persons[cp.leadId];return p&&p.dorsal!==''?p.dorsal:'';};
    }
  });
  // Inject rows that target a specific COMP into that COMP's model
  MANUAL_COUPLES_ROWS.filter(r=>r._targetSheet).forEach(row=>{
    const comp=COMPS.find(c=>c.sheet===row._targetSheet);
    if(comp&&!_vs.has(comp.sheet)){
      comp.rows.push(row);
      comp.model=buildModel(comp.rows,ageNorm);
      comp.model.dorsalOf=cp=>{const p=comp.model.persons[cp.leadId];return p&&p.dorsal!==''?p.dorsal:'';};
    }
  });
  // Handle untargeted rows with the __manual_couples__ virtual COMP
  const idx=COMPS.findIndex(c=>c.sheet==='__manual_couples__');
  const unRows=MANUAL_COUPLES_ROWS.filter(r=>!r._targetSheet);
  if(!unRows.length){if(idx>=0)COMPS.splice(idx,1);return;}
  const model=buildModel(unRows,ageNorm);
  model.events=[]; // personas registradas para dorsales, pero sin heats automáticos
  model.dorsalOf=cp=>{const p=model.persons[cp.leadId];return p&&p.dorsal!==''?p.dorsal:'';};
  const sess={sheet:'__manual_couples__',title:'Parejas manuales',date:'',rows:unRows,model,ageMode:undefined};
  if(idx>=0)COMPS[idx]=sess;else COMPS.push(sess);
}
async function deleteManualCouple(id){
  // Borrar todas las filas del mismo "grupo" (baseId): multidance + _sd + _ch
  MANUAL_COUPLES_ROWS=MANUAL_COUPLES_ROWS.filter(r=>r._manual_id!==id&&r._manual_id!==id+'_sd'&&r._manual_id!==id+'_ch');
  await saveManualCouplesDB();
  applyManualCouplesSession();
  if(COMPS.length===1){CUR=0;MODEL=COMPS[0].model;}else if(COMPS.length>1){CUR='all';MODEL=null;}else{CUR=null;MODEL=null;}
  const ds=parseInt(document.getElementById('dStart').value)||1;const ss=parseInt(document.getElementById('sStart').value)||0;
  rebuildDorsals(ds,ss);applyDorsalOverrides();_jreportCache=null;_mdreportCache=null;
  render();renderManualCouplesList();
}
function renderManualCouplesList(){
  const el=document.getElementById('manualCouplesList');
  if(!el)return;
  if(!MANUAL_COUPLES_ROWS.length){el.innerHTML='<div style="font-size:11px;color:var(--ink-soft);padding:4px 0">No hay parejas manuales.</div>';return;}
  // Agrupar filas por baseId (una entrada puede tener fila _sd y/o _ch adicionales)
  const groups={};
  MANUAL_COUPLES_ROWS.forEach(r=>{
    const baseId=r._manual_id.replace(/_sd$/,'').replace(/_ch$/,'');
    if(!groups[baseId])groups[baseId]={rows:[],baseId};
    groups[baseId].rows.push(r);
  });
  el.innerHTML=Object.values(groups).map(({rows,baseId})=>{
    const main=rows.find(r=>!r._manual_id.endsWith('_sd')&&!r._manual_id.endsWith('_ch'))||rows[0];
    const lead=main['Nombre (leader)']||'?';
    const foll=main['Follower (indicar nombre)']||'';
    const edad=main['Grupo de edad']||'';
    const esp=(main['Elija la especialidad']||'').replace(' Letra / Medalla Open','').replace(' Letra / Medalla','');
    const mods=rows.map(r=>{
      const m=r['Elegir modalidad']||'';
      if(m.includes('Single'))return'SD';
      if(m.includes('Challenge'))return'Chal';
      if(m.includes('International')||m.includes('American'))return'MD';
      return m;
    }).filter((v,i,a)=>a.indexOf(v)===i).join('+');
    const styles=['Standard','Latin','Smooth','Rhythm','SocialLatino','SocialArgentino','SocialAmericano'].filter(s=>main[s+' categoria']).map(s=>main[s+' categoria']).join(', ');
    return `<div style="display:flex;align-items:center;gap:8px;padding:7px 10px;border:1px solid var(--line);border-radius:8px;margin-bottom:4px;font-size:12px;background:var(--strip)">
      <div style="flex:1;line-height:1.5">
        <div style="font-weight:700">${lead}${foll?' / '+foll:''}</div>
        <div style="color:var(--ink-soft)">${[mods,esp,edad,styles].filter(Boolean).join(' · ')}</div>
      </div>
      <button class="act" style="font-size:11px;padding:3px 8px;border-color:#e3b8b0;color:#a00;white-space:nowrap" onclick="deleteManualCouple('${baseId}')">✕ Quitar</button>
    </div>`;
  }).join('');
}
function openAddDorsalToHeat(heatNum,style,cat,age,rl){
  const ex=document.getElementById('addDorsalModal');if(ex)ex.remove();
  const modal=document.createElement('div');
  modal.id='addDorsalModal';
  modal.style.cssText='position:fixed;inset:0;z-index:9999;background:rgba(0,0,0,.5);display:flex;align-items:center;justify-content:center;padding:16px';
  const INP='width:100%;box-sizing:border-box;padding:8px 10px;border:1.5px solid var(--line);border-radius:8px;font-size:14px;background:var(--card);color:var(--ink)';
  // Si cat contiene '+' (ej: "A+B"), permitir elegir la categoría específica
  const catParts=cat&&cat.includes('+')?cat.split('+'):null;
  const catSelHtml=catParts?`<div style="margin-bottom:12px">
    <label style="font-size:12px;font-weight:600;color:var(--ink-soft);display:block;margin-bottom:4px">Categoría específica</label>
    <select id="adCatSel" style="${INP}">${catParts.map(c=>`<option value="${c}">${c}</option>`).join('')}</select>
  </div>`:'';
  modal.innerHTML=`<div style="background:var(--card);border-radius:14px;padding:22px;max-width:380px;width:100%;box-shadow:0 16px 48px rgba(0,0,0,.35)">
    <div style="display:flex;align-items:center;justify-content:space-between;margin-bottom:14px">
      <b style="font-size:15px">➕ Agregar dorsal a heat ${heatNum}</b>
      <button onclick="document.getElementById('addDorsalModal').remove()" style="background:none;border:none;font-size:20px;cursor:pointer;color:var(--ink-soft)">×</button>
    </div>
    <div style="font-size:12px;color:var(--ink-soft);margin-bottom:12px">${rl||''}</div>
    <div style="margin-bottom:12px">
      <label style="font-size:12px;font-weight:600;color:var(--ink-soft);display:block;margin-bottom:4px">Número de dorsal</label>
      <input id="adDorsal" type="number" min="1" placeholder="Ej: 51" style="${INP}">
    </div>
    ${catSelHtml}
    <div id="adPreview" style="font-size:13px;margin-bottom:12px;min-height:20px;color:var(--ink-soft)"></div>
    <div id="adError" style="display:none;font-size:12px;color:#c0392b;margin-bottom:8px"></div>
    <div style="display:flex;gap:8px">
      <button id="adConfirmBtn" class="act solid" style="flex:1;padding:9px 0;font-size:13px">✓ Agregar</button>
      <button id="adCancelBtn" class="act" style="padding:9px 14px;font-size:13px">Cancelar</button>
    </div>
  </div>`;
  document.body.appendChild(modal);
  const inp=modal.querySelector('#adDorsal');
  const getFinalCat=()=>catParts?(modal.querySelector('#adCatSel')?.value||catParts[0]):cat;
  const doAdd=()=>addDorsalToHeat(heatNum,style,getFinalCat(),age);
  inp.addEventListener('input',()=>{
    const d=parseInt(inp.value);
    const prev=modal.querySelector('#adPreview');
    if(!d||isNaN(d)){prev.textContent='';return;}
    const found=_findCoupleByDorsal(d);
    prev.innerHTML=found?`<span style="color:var(--ink)">✓ ${found.lead}${found.foll?' — '+found.foll:''}</span>`:'<span style="color:#c0392b">Dorsal no encontrado</span>';
  });
  inp.addEventListener('keydown',ev=>{if(ev.key==='Enter')doAdd();});
  modal.querySelector('#adConfirmBtn').addEventListener('click',doAdd);
  modal.querySelector('#adCancelBtn').addEventListener('click',()=>modal.remove());
  setTimeout(()=>inp.focus(),50);
}
function _findCoupleByDorsal(d){
  const leadId=Object.keys(EVENT_DORSALS).find(id=>Number(EVENT_DORSALS[id])===Number(d));
  if(!leadId)return null;
  let lead='',foll='',leadDni='',follDni='',esc='';
  for(const comp of COMPS){
    const p=comp.model.persons[leadId];
    if(p){lead=p.name||'';leadDni=p.dni||'';}
    for(const e of (comp.model.events||[])){
      const cp=(e.couples||[]).find(c=>c.leadId===leadId);
      if(cp&&cp.foll){foll=cp.foll||'';esc=cp.esc||'';if(cp.follId){const pf=comp.model.persons[cp.follId];if(pf)follDni=pf.dni||'';}break;}
    }
    if(lead&&foll)break;
    if(lead)break;
  }
  // Fallback: buscar follower en MANUAL_COUPLES_ROWS (model.events puede estar vacío)
  if(lead&&!foll){
    const mr=MANUAL_COUPLES_ROWS.find(r=>{
      const rn=r['Nombre (leader)']||'';
      const rd=r['DNI del Leader']||'';
      return (leadDni&&rd&&dniKey(rd)===dniKey(leadDni))||(rn&&nameKey(rn)===nameKey(lead));
    });
    if(mr){foll=mr['Follower (indicar nombre)']||'';follDni=mr['DNI del Follower']||'';esc=mr['Seleccione su escuela']||'';}
  }
  return lead?{lead,foll,leadDni,follDni,esc,leadId}:null;
}
async function addDorsalToHeat(heatNum,style,cat,age){
  const errEl=document.getElementById('adError');
  if(errEl)errEl.style.display='none';
  const showErr=m=>{if(errEl){errEl.textContent=m;errEl.style.display='block';}};
  const d=parseInt(document.getElementById('adDorsal')?.value);
  if(!d||isNaN(d)){showErr('Ingresá un número de dorsal válido.');return;}
  const found=_findCoupleByDorsal(d);
  if(!found){showErr('No se encontró nadie con ese dorsal.');return;}
  // Completar DNI/follower desde MANUAL_COUPLES_ROWS si _findCoupleByDorsal no los trajo
  if(!found.leadDni||!found.foll||!found.follDni){
    const _mr=MANUAL_COUPLES_ROWS.find(r=>nameKey(r['Nombre (leader)']||'')===nameKey(found.lead));
    if(_mr){
      if(!found.leadDni)found.leadDni=_mr['DNI del Leader']||'';
      if(!found.foll)found.foll=_mr['Follower (indicar nombre)']||'';
      if(!found.follDni)found.follDni=_mr['DNI del Follower']||'';
      if(!found.esc)found.esc=_mr['Seleccione su escuela']||'';
    }
  }
  const compVals=[...new Set(COMPS.flatMap(c=>(c.rows||[]).map(r=>r['Competencia']).filter(Boolean)))];
  const colMap={Standard:'Standard categoria',Latin:'Latin categoria',Smooth:'Smooth categoria',Rhythm:'Rhythm categoria',SocialLatino:'SocialLatino categoria',SocialArgentino:'SocialArgentino categoria',SocialAmericano:'SocialAmericano categoria'};
  const modMap={Standard:'International Style',Latin:'International Style',Smooth:'American Style',Rhythm:'American Style',SocialLatino:'Social Latino',SocialArgentino:'Social Argentino',SocialAmericano:'Social Americano'};
  const col=colMap[style];const mod=modMap[style]||'International Style';
  const baseId=Date.now()+':'+Math.random().toString(36).slice(2);
  // Detect which COMP owns this heat so the couple lands in the right event
  const _vSheets=new Set(['__manual_couples__','__inscripciones_web__','__inscripciones_web_aabd__']);
  let targetSheet=null;
  if(LAST_SCH&&LAST_SCH.isAll){
    for(const B of(LAST_SCH.blocks||[])){
      if((B.singles||[]).some(s=>s.heat===heatNum)||(B.comps||[]).some(e=>e.heat===heatNum)){targetSheet=B._compSheet||null;break;}
    }
  }else if(CUR!=='all'&&COMPS[CUR]){targetSheet=COMPS[CUR].sheet;}
  if(targetSheet&&_vSheets.has(targetSheet))targetSheet=null;
  const targetComp=targetSheet?COMPS.find(c=>c.sheet===targetSheet):null;
  const compName=targetComp?(targetComp.rows.find(r=>r['Competencia'])||{})['Competencia']||(compVals[0]||'Privada'):(compVals[0]||'Privada');
  // Detectar si el evento target es OPEN (no LM) para que buildModel cree el tipo correcto
  let _targetEvKind='LM';
  if(LAST_SCH&&LAST_SCH.blocks){
    outer: for(const _B of(LAST_SCH.blocks||[])){
      for(const _ev of(_B.comps||[])){
        if(_ev.heat!==heatNum)continue;
        if(_ev.shared&&_ev.buckets){
          const _bkt=_ev.buckets.find(b=>b.style===style&&(b.cat===cat||(b.kind==='OPEN'&&cat==='Open'))&&ageNorm(b.age)===ageNorm(age));
          if(_bkt)_targetEvKind=_bkt.kind||'LM';
        } else {
          _targetEvKind=_ev.kind||'LM';
        }
        break outer;
      }
    }
  }
  const _espBase=found.foll?'Pareja':'Solista';
  const _esp=_targetEvKind==='OPEN'?_espBase+' Open':_espBase;
  const row={_manual_id:baseId,'Nombre (leader)':found.lead,'Follower (indicar nombre)':found.foll||'','DNI del Leader':found.leadDni||'','DNI del Follower':found.follDni||'','Seleccione su escuela':found.esc||'','Grupo de edad':age||'Adu','Competencia':compName,'Elegir modalidad':mod,'Elija la especialidad':_esp,'Tipo de pareja':'Amateur-Amateur'};
  if(col&&cat)row[col]=cat;
  if(targetSheet)row._targetSheet=targetSheet;
  // Eliminar filas previas del mismo lead+estilo+cat+edad en el mismo COMP (verdaderos duplicados)
  if(targetSheet){
    MANUAL_COUPLES_ROWS=MANUAL_COUPLES_ROWS.filter(r=>{
      if(r._targetSheet!==targetSheet)return true;
      const rName=r['Nombre (leader)']||'';const rDni=r['DNI del Leader']||'';
      const sameLead=(found.leadDni&&rDni&&dniKey(rDni)===dniKey(found.leadDni))||(found.lead&&rName&&nameKey(rName)===nameKey(found.lead));
      const sameStyle=colMap[style]&&r[colMap[style]]===cat; // mismo cat-valor, no solo misma columna
      const sameAge=(r['Grupo de edad']||'')===(age||'');
      return!(sameLead&&sameStyle&&sameAge);
    });
  }
  MANUAL_COUPLES_ROWS.push(row);
  // Antes esto no tenía try/catch: si algo fallaba (guardar, reconstruir el
  // modelo, re-render) la promesa quedaba rechazada en silencio, el modal no se
  // cerraba y el usuario no veía ningún aviso. Ahora el error se muestra y la
  // fila recién agregada se revierte para no dejar el estado a medias.
  try{
    await saveManualCouplesDB();
    applyManualCouplesSession();
    if(COMPS.length===1){CUR=0;MODEL=COMPS[0].model;}else{CUR='all';MODEL=null;}
    const ds=parseInt(document.getElementById('dStart').value)||1;const ss=parseInt(document.getElementById('sStart').value)||0;
    rebuildDorsals(ds,ss);applyDorsalOverrides();_jreportCache=null;_mdreportCache=null;
    buildCompSel();syncCompInputs();updateCompHeader();renderLogoPanel();render();
  }catch(err){
    MANUAL_COUPLES_ROWS=MANUAL_COUPLES_ROWS.filter(r=>r._manual_id!==baseId);
    console.error('addDorsalToHeat:',err);
    showErr('No se pudo agregar: '+(err&&err.message?err.message:err));
    return;
  }
  // ¿Dónde terminó la pareja? Puede caer en OTRO heat si su categoría/edad/estilo
  // arman un evento distinto, o no entrar en ninguno. Antes no se avisaba nada.
  const _landed=_heatsOfLead(found.leadId);
  document.getElementById('addDorsalModal')?.remove();
  renderManualCouplesList();
  if(!_landed.length){
    _dorsalNotice('warn','El dorsal '+d+' se agregó, pero no quedó en ningún heat. Revisá que la categoría y el grupo de edad coincidan con alguna competencia.');
  }else if(!_landed.includes(heatNum)){
    _dorsalNotice('warn','El dorsal '+d+' no entró en el heat '+heatNum+': quedó en el heat '+_landed.join(' y ')+' porque su categoría/edad arma otro evento.');
  }else{
    _dorsalNotice('ok','Dorsal '+d+' agregado al heat '+heatNum+'.');
  }
}
// Heats (números de display) en los que aparece un leadId después de rearmar.
function _heatsOfLead(leadId){
  const out=[];
  ((LAST_SCH&&LAST_SCH.blocks)||[]).forEach(B=>{
    (B.comps||[]).forEach(e=>{
      if((e.couples||[]).some(c=>c.leadId===leadId))out.push(e._displayHeat??e.heat);
    });
  });
  return [...new Set(out)].sort((a,b)=>a-b);
}
// Aviso flotante (no hay sistema de toasts en la app).
function _dorsalNotice(kind,msg){
  document.getElementById('dorsalNotice')?.remove();
  const n=document.createElement('div');
  n.id='dorsalNotice';
  const bg=kind==='ok'?'#eef6f0':'#fff8e6', bd=kind==='ok'?'#2e7d4f':'#b8860b', fg=kind==='ok'?'#1e5c39':'#7a5c00';
  n.style.cssText='position:fixed;left:50%;transform:translateX(-50%);bottom:24px;z-index:10000;max-width:520px;padding:12px 18px;border-radius:10px;border:1.5px solid '+bd+';background:'+bg+';color:'+fg+';font-size:13px;font-weight:600;line-height:1.45;box-shadow:0 10px 30px rgba(0,0,0,.18);cursor:pointer';
  n.textContent=(kind==='ok'?'\u2713 ':'\u26a0 ')+msg;
  n.addEventListener('click',()=>n.remove());
  document.body.appendChild(n);
  setTimeout(()=>{if(n.isConnected)n.remove();},kind==='ok'?4000:9000);
}

